 wanted jsonb := $eight_data$[{"id":"tcf-listening-07","version":"tcf-listening-2026-11-test07-v2","title":"TCF Listening · Test 07","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La scène représente une personne assise, occupée à consulter un billet d'exposition.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un billet d'exposition à une table. D. Elle court sur un terrain de sport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un billet d'exposition à une table. D. Elle court sur un terrain de sport."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.027,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Un homme présente une affiche liée à arts, culture et patrimoine.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il peint une façade extérieure. B. Il présente une affiche sur arts, culture et patrimoine à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il peint une façade extérieure. B. Il présente une affiche sur arts, culture et patrimoine à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":18.013,"slotSeconds":34},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Deux interlocuteurs préparent une nuit des musées autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes préparent une nuit des musées autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes préparent une nuit des musées autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.675,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'illustration montre une personne portant un sac devant le centre culturel de Rouen.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre culturel de Rouen.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre culturel de Rouen."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.396,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse précise le point de départ de l'activité.","transcript":"Question 5.\nExcusez-moi, où commence une visite commentée des collections ?\nA. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Le point de départ est devant l’accueil. D. Oui, j'en ai acheté trois kilos.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où commence une visite commentée des collections ?"},{"voice":"female","text":"A. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Le point de départ est devant l’accueil. D. Oui, j'en ai acheté trois kilos."}],"audio":"q-05.mp3","audioSeconds":17.717,"slotSeconds":33},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un billet d'exposition pour participer à une nuit des musées ?\nA. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un billet d'exposition pour participer à une nuit des musées ?"},{"voice":"female","text":"A. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail."}],"audio":"q-06.mp3","audioSeconds":18.953,"slotSeconds":34},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour une visite commentée des collections ?\nA. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour une visite commentée des collections ?"},{"voice":"female","text":"A. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat."}],"audio":"q-07.mp3","audioSeconds":17.2,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une nuit des musées. Est-ce possible ?\nA. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une nuit des musées. Est-ce possible ?"},{"voice":"female","text":"A. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau."}],"audio":"q-08.mp3","audioSeconds":20.915,"slotSeconds":36},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles.","Une séance avec interprétation en langue des signes.","Une adaptation des tarifs des activités déjà annoncées."],"correct":"C","explanation":"Le document permet de retenir « Une séance avec interprétation en langue des signes ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans le centre culturel de Rouen, à compter de lundi prochain, nous mettons en place une séance avec interprétation en langue des signes. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans le centre culturel de Rouen, à compter de lundi prochain, nous mettons en place une séance avec interprétation en langue des signes. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":22.552,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Un autre créneau est proposé pour une visite commentée des collections en raison des transports.","La personne arrivera plus tard à une visite commentée des collections à cause d’une autre obligation.","Le rendez-vous pour une visite commentée des collections est avancé d’une demi-heure.","Le rendez-vous pour une visite commentée des collections est reporté au lendemain."],"correct":"B","explanation":"Le document permet de retenir « La personne arrivera plus tard à une visite commentée des collections à cause d’une autre obligation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour une visite commentée des collections ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour une visite commentée des collections ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.1,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Remplir le formulaire d’inscription en ligne avant jeudi.","Réserver sa place pour une nuit des musées par téléphone avant jeudi.","Envoyer le formulaire de une nuit des musées par courriel avant vendredi.","Déposer sa demande pour une nuit des musées à l’accueil le jour même."],"correct":"A","explanation":"Le document permet de retenir « Remplir le formulaire d’inscription en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Arts, culture et patrimoine » aura lieu dans le centre culturel de Rouen. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Arts, culture et patrimoine » aura lieu dans le centre culturel de Rouen. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.467,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Remplir un nouveau formulaire d’inscription pour participer à une visite commentée des collections.","Demander une confirmation écrite après la fin de une visite commentée des collections.","Présenter une pièce d’identité à l’accueil pour accéder à une visite commentée des collections.","Présenter le message de confirmation pour une visite commentée des collections à l’accueil."],"correct":"D","explanation":"Le document permet de retenir « Présenter le message de confirmation pour une visite commentée des collections à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à une visite commentée des collections, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à une visite commentée des collections, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.676,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de une visite commentée des collections change de salle mais garde le même horaire.","La séance de une visite commentée des collections commence une heure plus tôt que prévu.","La séance prévue pour une visite commentée des collections commence une heure plus tard.","La séance de une visite commentée des collections est reportée au lendemain à la même heure."],"correct":"C","explanation":"Le document permet de retenir « La séance prévue pour une visite commentée des collections commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour une visite commentée des collections. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour une visite commentée des collections. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.017,"slotSeconds":40},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Maintenir une visite commentée des collections avec une démonstration réalisée sans le matériel.","Conserver une visite commentée des collections et envoyer ensuite la démonstration manquante.","Reporter une visite commentée des collections jusqu’à ce que le matériel soit disponible.","Garder une visite commentée des collections mais renoncer à fournir la démonstration prévue."],"correct":"B","explanation":"Le document permet de retenir « Conserver une visite commentée des collections et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à une visite commentée des collections n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à une visite commentée des collections n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.09,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans le centre culturel de Rouen, les difficultés ont été réglées avant le lancement.","Dans le centre culturel de Rouen, l’initiative est désormais réservée aux habitués.","Dans le centre culturel de Rouen, la mesure a été suspendue faute de participants."],"correct":"A","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre culturel de Rouen : une séance avec interprétation en langue des signes. Le dispositif vise à répondre à une difficulté bien connue : les habitants éloignés du centre assistent rarement aux manifestations. Plusieurs représentants soulignent toutefois que les salles de spectacle ne disposent pas toutes d'ascenseur. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre culturel de Rouen : une séance avec interprétation en langue des signes. Le dispositif vise à répondre à une difficulté bien connue : les habitants éloignés du centre assistent rarement aux manifestations. Plusieurs représentants soulignent toutefois que les salles de spectacle ne disposent pas toutes d'ascenseur. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.92,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Répartir les permanences de la médiation culturelle itinérante entre deux lieux différents.","Avancer les horaires de la médiation culturelle itinérante en supprimant le relais du soir.","Réserver les permanences de la médiation culturelle itinérante aux inscriptions du matin.","Répartir les permanences de la médiation culturelle itinérante pour maintenir l’accueil continu."],"correct":"D","explanation":"Le document permet de retenir « Répartir les permanences de la médiation culturelle itinérante pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la médiation culturelle itinérante.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la médiation culturelle itinérante."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.724,"slotSeconds":42},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les visiteurs ayant déjà terminé leurs démarches dans le centre culturel de Rouen.","Les personnes qui fréquentent régulièrement les ateliers de le centre culturel de Rouen.","Les visiteurs du centre culturel de Rouen qui peinent à accéder au service ordinaire.","Les employés chargés d’accueillir et d’orienter les visiteurs de le centre culturel de Rouen."],"correct":"C","explanation":"Le document permet de retenir « Les visiteurs du centre culturel de Rouen qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans le centre culturel de Rouen. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les habitants éloignés du centre assistent rarement aux manifestations. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans le centre culturel de Rouen. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les habitants éloignés du centre assistent rarement aux manifestations. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.436,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle souhaite déplacer une nuit des musées à cause d’un changement de salle.","Elle travaille encore vendredi à seize heures, au moment d’une nuit des musées.","Elle demande un autre horaire pour une nuit des musées afin d’accompagner un proche.","Elle ne peut se rendre à une nuit des musées à cause d’un retard de transport."],"correct":"B","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une nuit des musées ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une nuit des musées. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une nuit des musées. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.538,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Permettre à chaque participant de poser ses questions et d’échanger.","Répartir les participants de une nuit des musées selon leur expérience.","Réduire le groupe de une nuit des musées pour utiliser moins de matériel.","Adapter le nombre de places de une nuit des musées à la taille de la salle."],"correct":"A","explanation":"Le document permet de retenir « Permettre à chaque participant de poser ses questions et d’échanger ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une nuit des musées, des visites en petits groupes seront proposées dans le centre culturel de Rouen. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une nuit des musées, des visites en petits groupes seront proposées dans le centre culturel de Rouen. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":23.539,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","La visiteuse souhaite des précisions sur la fragilité des œuvres prêtées."],"correct":"D","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la fragilité des œuvres prêtées ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la fragilité des œuvres prêtées. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la fragilité des œuvres prêtées. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":28.987,"slotSeconds":45},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Prévoir le matériel nécessaire selon les inscriptions à une nuit des musées.","Définir les activités prioritaires selon le public attendu pour une nuit des musées.","Répartir les bénévoles d’une nuit des musées selon les créneaux où ils sont libres.","Adapter les tâches des bénévoles aux compétences requises pour une nuit des musées."],"correct":"C","explanation":"Le document permet de retenir « Répartir les bénévoles d’une nuit des musées selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans le centre culturel de Rouen, pour préparer une nuit des musées, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans le centre culturel de Rouen, pour préparer une nuit des musées, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":35.428,"slotSeconds":52},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["La meilleure organisation des activités obtenue grâce à une visite commentée des collections.","Les relations de confiance établies pendant une visite commentée des collections avec les participants.","Les connaissances pratiques acquises au cours de une visite commentée des collections.","Les nouveaux contacts professionnels pris pendant une visite commentée des collections."],"correct":"B","explanation":"Le document permet de retenir « Les relations de confiance établies pendant une visite commentée des collections avec les participants ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à une visite commentée des collections. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les habitants éloignés du centre assistent rarement aux manifestations. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à une visite commentée des collections. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les habitants éloignés du centre assistent rarement aux manifestations. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":44.757,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Tester des événements dans les bibliothèques de quartier, consulter les usagers puis publier un bilan.","Mettre en place des événements dans les bibliothèques de quartier partout avant de mesurer les résultats.","Consulter les habitants sur des événements dans les bibliothèques de quartier sans mener d’essai concret.","Expérimenter des événements dans les bibliothèques de quartier mais ne publier aucun retour des participants."],"correct":"A","explanation":"Le document permet de retenir « Tester des événements dans les bibliothèques de quartier, consulter les usagers puis publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Arts, culture et patrimoine ».\nNous avons discuté de des événements dans les bibliothèques de quartier, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan.\nLes usagers craignent surtout la fragilité des œuvres prêtées. Une application immédiate, sans consultation, risquerait de perdre leur confiance.\nAlors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Arts, culture et patrimoine »."},{"voice":"male","text":"Nous avons discuté de des événements dans les bibliothèques de quartier, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan."},{"voice":"female","text":"Les usagers craignent surtout la fragilité des œuvres prêtées. Une application immédiate, sans consultation, risquerait de perdre leur confiance."},{"voice":"male","text":"Alors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":56.226,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de la médiation culturelle itinérante comprend surtout des personnes en attente.","L’étude de la médiation culturelle itinérante s’appuie principalement sur les réponses des agents.","L’étude de la médiation culturelle itinérante donne peu de place aux nouveaux inscrits.","L’étude sur la médiation culturelle itinérante n’a presque pas touché ceux qui ont abandonné."],"correct":"D","explanation":"Le document permet de retenir « L’étude sur la médiation culturelle itinérante n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant la médiation culturelle itinérante. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les habitants éloignés du centre assistent rarement aux manifestations. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant la médiation culturelle itinérante. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les habitants éloignés du centre assistent rarement aux manifestations. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":52.53,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Concilier les événements de quartier avec les inquiétudes liées aux œuvres prêtées.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement."],"correct":"C","explanation":"Le document permet de retenir « Concilier les événements de quartier avec les inquiétudes liées aux œuvres prêtées ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans le centre culturel de Rouen, une initiative propose des événements dans les bibliothèques de quartier. Les responsables espèrent ainsi répondre à une difficulté bien connue : les habitants éloignés du centre assistent rarement aux manifestations.\nNous soutenons l’objectif général, mais il faut prendre en compte la fragilité des œuvres prêtées. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que former les médiateurs et financer l'accès pour différents publics. Pourtant, les salles de spectacle ne disposent pas toutes d'ascenseur. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans le centre culturel de Rouen, une initiative propose des événements dans les bibliothèques de quartier. Les responsables espèrent ainsi répondre à une difficulté bien connue : les habitants éloignés du centre assistent rarement aux manifestations."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la fragilité des œuvres prêtées. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que former les médiateurs et financer l'accès pour différents publics. Pourtant, les salles de spectacle ne disposent pas toutes d'ascenseur. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":53.553,"slotSeconds":70},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Le projet de une séance avec interprétation en langue des signes est annoncé mais n’a pas encore été lancé.","La nouvelle mesure, une séance avec interprétation en langue des signes, doit encore être évaluée sur la durée.","Les résultats de une séance avec interprétation en langue des signes concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre une séance avec interprétation en langue des signes dès la fin des premiers essais."],"correct":"B","explanation":"Le document permet de retenir « La nouvelle mesure, une séance avec interprétation en langue des signes, doit encore être évaluée sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une séance avec interprétation en langue des signes. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les salles de spectacle ne disposent pas toutes d'ascenseur. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la diversité du public qui revient aux activités. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une séance avec interprétation en langue des signes. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les salles de spectacle ne disposent pas toutes d'ascenseur. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la diversité du public qui revient aux activités. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":49.39,"slotSeconds":67},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Adapter les horaires de la médiation culturelle itinérante sans pénaliser les usagers du soir.","Conserver les horaires de la médiation culturelle itinérante malgré les demandes du matin.","Réserver les créneaux matinaux de la médiation culturelle itinérante aux seuls abonnés.","Ouvrir la médiation culturelle itinérante plus tôt en supprimant les créneaux tardifs."],"correct":"A","explanation":"Le document permet de retenir « Adapter les horaires de la médiation culturelle itinérante sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que la médiation culturelle itinérante ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que la médiation culturelle itinérante ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.526,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Tester un parcours tactile accessible sur un seul site avant de l’ouvrir à tous.","Préparer le budget de un parcours tactile accessible avant de calculer son entretien.","Adapter les équipements de un parcours tactile accessible après consultation des équipes.","Concevoir un parcours tactile accessible avant de comprendre les besoins réels des utilisateurs."],"correct":"D","explanation":"Le document permet de retenir « Concevoir un parcours tactile accessible avant de comprendre les besoins réels des utilisateurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un parcours tactile accessible a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la fragilité des œuvres prêtées est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un parcours tactile accessible a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la fragilité des œuvres prêtées est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.008,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut comparer les coûts de la diversité du public qui revient aux activités ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut mesurer la diversité du public qui revient aux activités ; l’autre demande des récits.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres."],"correct":"C","explanation":"Le document permet de retenir « L’un veut mesurer la diversité du public qui revient aux activités ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Arts, culture et patrimoine ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la diversité du public qui revient aux activités et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les habitants éloignés du centre assistent rarement aux manifestations. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Arts, culture et patrimoine »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la diversité du public qui revient aux activités et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les habitants éloignés du centre assistent rarement aux manifestations. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":50.187,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Conserver le bâtiment de une visite commentée des collections uniquement pour ses activités passées.","Conserver l’identité du lieu accueillant une visite commentée des collections tout en permettant de nouveaux usages.","Moderniser les salles de une visite commentée des collections en effaçant les anciennes traces.","Rénover le lieu de une visite commentée des collections sans changer l’usage actuel des espaces."],"correct":"B","explanation":"Le document permet de retenir « Conserver l’identité du lieu accueillant une visite commentée des collections tout en permettant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule une visite commentée des collections, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule une visite commentée des collections, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.294,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Confronter les prévisions d’un modèle aux observations réelles.","Réviser les hypothèses avant toute observation de terrain.","Comparer les prévisions de plusieurs modèles entre elles.","Vérifier seulement si le modèle retrouve les données de départ."],"correct":"A","explanation":"Le document permet de retenir « Confronter les prévisions d’un modèle aux observations réelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la diversité du public qui revient aux activités. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les habitants éloignés du centre assistent rarement aux manifestations. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la diversité du public qui revient aux activités. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les habitants éloignés du centre assistent rarement aux manifestations. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":56.93,"slotSeconds":74},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour la médiation culturelle itinérante, annoncer une moyenne sans préciser les hypothèses retenues.","Pour la médiation culturelle itinérante, accorder la même fiabilité à toutes les prévisions disponibles.","Pour la médiation culturelle itinérante, publier un chiffre précis sans détailler ses limites.","Pour la médiation culturelle itinérante, présenter les hypothèses et les incertitudes des prévisions."],"correct":"D","explanation":"Le document permet de retenir « Pour la médiation culturelle itinérante, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant la médiation culturelle itinérante, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant la médiation culturelle itinérante, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.13,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Les chiffres de le centre culturel de Rouen ne tiennent pas compte du prix des activités.","La hausse des visites à le centre culturel de Rouen vient surtout des horaires étendus.","La hausse des visites ne démontre pas un bénéfice durable du projet.","La fréquentation de le centre culturel de Rouen varie trop selon les saisons."],"correct":"C","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans le centre culturel de Rouen, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une séance avec interprétation en langue des signes. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la diversité du public qui revient aux activités ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans le centre culturel de Rouen, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une séance avec interprétation en langue des signes. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la diversité du public qui revient aux activités ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.977,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Évaluer la médiation culturelle itinérante auprès de tous puis supprimer l’accueil individuel.","Faire tester la médiation culturelle itinérante par différents publics et maintenir une aide humaine.","Faire tester la médiation culturelle itinérante uniquement par les usagers réguliers.","Maintenir une aide humaine à la médiation culturelle itinérante pendant le seul lancement."],"correct":"B","explanation":"Le document permet de retenir « Faire tester la médiation culturelle itinérante par différents publics et maintenir une aide humaine ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans le centre culturel de Rouen.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la fragilité des œuvres prêtées.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans le centre culturel de Rouen."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la fragilité des œuvres prêtées."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.279,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les résultats annoncés suffisent, même si les usages réels diffèrent.","La performance du dispositif de la galerie des Arts exige un entretien régulier.","Les usages quotidiens du matériel de la galerie des Arts peuvent changer ses effets.","Les conditions de terrain de la galerie des Arts influencent les résultats observés."],"correct":"A","explanation":"Le document permet de retenir « Les résultats annoncés suffisent, même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la galerie des Arts affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la galerie des Arts affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.736,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Répartir les rôles de une visite commentée des collections entre des participants désignés à l’avance.","Évaluer le lien créé à une visite commentée des collections uniquement par le nombre de présences.","Assurer une présence régulière aux séances de une visite commentée des collections sans échanger.","Permettre une participation volontaire et réciproque à une visite commentée des collections."],"correct":"D","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à une visite commentée des collections ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de une visite commentée des collections réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la fragilité des œuvres prêtées. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de une visite commentée des collections réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la fragilité des œuvres prêtées. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":52.78,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits de la médiation culturelle itinérante sans consulter les archives disponibles.","Conserver les récits de la médiation culturelle itinérante qui concordent avec la majorité.","Comparer les récits concernant la médiation culturelle itinérante aux faits vérifiables.","Classer les témoignages de la médiation culturelle itinérante selon l’ancienneté de leurs auteurs."],"correct":"C","explanation":"Le document permet de retenir « Comparer les récits concernant la médiation culturelle itinérante aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant la médiation culturelle itinérante, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant la médiation culturelle itinérante, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.43,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès de une séance avec interprétation en langue des signes réduit les demandes des services voisins.","Une initiative comme une séance avec interprétation en langue des signes peut devenir victime de son succès et fragiliser les usagers.","La fréquentation de une séance avec interprétation en langue des signes ralentit la promotion du dispositif.","La croissance de une séance avec interprétation en langue des signes augmente le budget sans effet sur les usagers."],"correct":"B","explanation":"Le document permet de retenir « Une initiative comme une séance avec interprétation en langue des signes peut devenir victime de son succès et fragiliser les usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Arts, culture et patrimoine ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une séance avec interprétation en langue des signes peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les habitants éloignés du centre assistent rarement aux manifestations. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la fragilité des œuvres prêtées. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Arts, culture et patrimoine ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une séance avec interprétation en langue des signes peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les habitants éloignés du centre assistent rarement aux manifestations. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la fragilité des œuvres prêtées. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":62.944,"slotSeconds":80},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Stabiliser les moyens et suivre la diversité du public qui revient aux activités dans la durée.","Obtenir des moyens durables mais ne plus mesurer la diversité du public qui revient aux activités.","Étendre le service en privilégiant seulement les premiers résultats de la diversité du public qui revient aux activités.","Suivre la diversité du public qui revient aux activités en comptant sur les bénévoles actuels."],"correct":"A","explanation":"Le document permet de retenir « Stabiliser les moyens et suivre la diversité du public qui revient aux activités dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à la médiation culturelle itinérante, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les salles de spectacle ne disposent pas toutes d'ascenseur. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la diversité du public qui revient aux activités. L’idée n’est pas d’abandonner l’ambition de départ : former les médiateurs et financer l'accès pour différents publics. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à la médiation culturelle itinérante, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les salles de spectacle ne disposent pas toutes d'ascenseur. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la diversité du public qui revient aux activités. L’idée n’est pas d’abandonner l’ambition de départ : former les médiateurs et financer l'accès pour différents publics. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":64.198,"slotSeconds":83}]},{"id":"tcf-listening-08","version":"tcf-listening-2026-11-test08-v2","title":"TCF Listening · Test 08","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La scène représente une personne assise, occupée à consulter un dossier de candidature.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un dossier de candidature à une table.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte un dossier de candidature à une table."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.431,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Un homme présente une affiche liée à travail et vie professionnelle.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur travail et vie professionnelle à un groupe. D. Il prépare un repas dans la cuisine.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur travail et vie professionnelle à un groupe. D. Il prépare un repas dans la cuisine."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.932,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Deux interlocuteurs préparent un forum des métiers autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Trois personnes font de la randonnée. B. Deux personnes préparent un forum des métiers autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Trois personnes font de la randonnée. B. Deux personnes préparent un forum des métiers autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.199,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'illustration montre une personne portant un sac devant la maison de l'emploi de Lille.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme porte un sac devant la maison de l'emploi de Lille. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme porte un sac devant la maison de l'emploi de Lille. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.454,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de préparation aux entretiens ?\nA. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de préparation aux entretiens ?"},{"voice":"female","text":"A. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Dans la salle du premier étage, juste après l'accueil."}],"audio":"q-05.mp3","audioSeconds":19.76,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un dossier de candidature pour participer à un forum des métiers ?\nA. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un dossier de candidature pour participer à un forum des métiers ?"},{"voice":"female","text":"A. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche."}],"audio":"q-06.mp3","audioSeconds":19.789,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de préparation aux entretiens ?\nA. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de préparation aux entretiens ?"},{"voice":"female","text":"A. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr."}],"audio":"q-07.mp3","audioSeconds":18.013,"slotSeconds":34},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à un forum des métiers. Est-ce possible ?\nA. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à un forum des métiers. Est-ce possible ?"},{"voice":"female","text":"A. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue."}],"audio":"q-08.mp3","audioSeconds":20.486,"slotSeconds":36},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","La nouvelle mesure annoncée est une permanence de conseil en soirée."],"correct":"D","explanation":"Le document permet de retenir « La nouvelle mesure annoncée est une permanence de conseil en soirée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la maison de l'emploi de Lille, à compter de lundi prochain, nous mettons en place une permanence de conseil en soirée. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la maison de l'emploi de Lille, à compter de lundi prochain, nous mettons en place une permanence de conseil en soirée. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":20.997,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier de préparation aux entretiens est avancé d’une demi-heure.","Le rendez-vous pour un atelier de préparation aux entretiens est reporté au lendemain.","Le rendez-vous d’un atelier de préparation aux entretiens est repoussé à cause d’une réunion prolongée.","Un autre créneau est proposé pour un atelier de préparation aux entretiens en raison des transports."],"correct":"C","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de préparation aux entretiens est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de préparation aux entretiens ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de préparation aux entretiens ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.263,"slotSeconds":44},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Envoyer le formulaire de un forum des métiers par courriel avant vendredi.","Remplir en ligne le formulaire d’inscription pour un forum des métiers avant jeudi.","Déposer sa demande pour un forum des métiers à l’accueil le jour même.","Réserver sa place pour un forum des métiers par téléphone avant jeudi."],"correct":"B","explanation":"Le document permet de retenir « Remplir en ligne le formulaire d’inscription pour un forum des métiers avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Travail et vie professionnelle » aura lieu dans la maison de l'emploi de Lille. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Travail et vie professionnelle » aura lieu dans la maison de l'emploi de Lille. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.445,"slotSeconds":42},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Montrer le courriel de confirmation à l’accueil pour retrouver son inscription.","Demander une confirmation écrite après la fin de un atelier de préparation aux entretiens.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier de préparation aux entretiens.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de préparation aux entretiens."],"correct":"A","explanation":"Le document permet de retenir « Montrer le courriel de confirmation à l’accueil pour retrouver son inscription ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de préparation aux entretiens, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de préparation aux entretiens, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.955,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier de préparation aux entretiens commence une heure plus tôt que prévu.","La séance de un atelier de préparation aux entretiens est reportée au lendemain à la même heure.","La séance de un atelier de préparation aux entretiens change de salle mais garde le même horaire.","La séance prévue pour un atelier de préparation aux entretiens commence une heure plus tard."],"correct":"D","explanation":"Le document permet de retenir « La séance prévue pour un atelier de préparation aux entretiens commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de préparation aux entretiens. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de préparation aux entretiens. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.483,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Reporter un atelier de préparation aux entretiens jusqu’à ce que le matériel soit disponible.","Garder un atelier de préparation aux entretiens mais renoncer à fournir la démonstration prévue.","Conserver un atelier de préparation aux entretiens et envoyer ensuite la démonstration manquante.","Maintenir un atelier de préparation aux entretiens avec une démonstration réalisée sans le matériel."],"correct":"C","explanation":"Le document permet de retenir « Conserver un atelier de préparation aux entretiens et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de préparation aux entretiens n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de préparation aux entretiens n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":31.059,"slotSeconds":48},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans la maison de l'emploi de Lille, l’initiative est désormais réservée aux habitués.","La mesure présentée à la maison de l'emploi de Lille répond au besoin sans lever toutes les difficultés.","Dans la maison de l'emploi de Lille, la mesure a été suspendue faute de participants.","Dans la maison de l'emploi de Lille, les difficultés ont été réglées avant le lancement."],"correct":"B","explanation":"Le document permet de retenir « La mesure présentée à la maison de l'emploi de Lille répond au besoin sans lever toutes les difficultés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la maison de l'emploi de Lille : une permanence de conseil en soirée. Le dispositif vise à répondre à une difficulté bien connue : les salariés en poste n'ont pas le temps de suivre les formations en journée. Plusieurs représentants soulignent toutefois que les petites entreprises peinent à remplacer les salariés absents. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la maison de l'emploi de Lille : une permanence de conseil en soirée. Le dispositif vise à répondre à une difficulté bien connue : les salariés en poste n'ont pas le temps de suivre les formations en journée. Plusieurs représentants soulignent toutefois que les petites entreprises peinent à remplacer les salariés absents. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":31.297,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Maintenir un accueil sans interruption malgré les changements de service.","Avancer les horaires de l'accompagnement des reconversions en supprimant le relais du soir.","Réserver les permanences de l'accompagnement des reconversions aux inscriptions du matin.","Répartir les permanences de l'accompagnement des reconversions entre deux lieux différents."],"correct":"A","explanation":"Le document permet de retenir « Maintenir un accueil sans interruption malgré les changements de service ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour l'accompagnement des reconversions.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour l'accompagnement des reconversions."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":24.923,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui fréquentent régulièrement les ateliers de la maison de l'emploi de Lille.","Les employés chargés d’accueillir et d’orienter les visiteurs de la maison de l'emploi de Lille.","Les visiteurs ayant déjà terminé leurs démarches dans la maison de l'emploi de Lille.","Les visiteurs de la maison de l'emploi de Lille qui peinent à accéder au service ordinaire."],"correct":"D","explanation":"Le document permet de retenir « Les visiteurs de la maison de l'emploi de Lille qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la maison de l'emploi de Lille. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les salariés en poste n'ont pas le temps de suivre les formations en journée. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la maison de l'emploi de Lille. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les salariés en poste n'ont pas le temps de suivre les formations en journée. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.076,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle demande un autre horaire pour un forum des métiers afin d’accompagner un proche.","Elle ne peut se rendre à un forum des métiers à cause d’un retard de transport.","Elle travaille encore vendredi à seize heures, au moment d’un forum des métiers.","Elle souhaite déplacer un forum des métiers à cause d’un changement de salle."],"correct":"C","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’un forum des métiers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour un forum des métiers. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour un forum des métiers. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.033,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Réduire le groupe de un forum des métiers pour utiliser moins de matériel.","Limiter le groupe pendant un forum des métiers afin que chacun puisse poser des questions.","Adapter le nombre de places de un forum des métiers à la taille de la salle.","Répartir les participants de un forum des métiers selon leur expérience."],"correct":"B","explanation":"Le document permet de retenir « Limiter le groupe pendant un forum des métiers afin que chacun puisse poser des questions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour un forum des métiers, des visites en petits groupes seront proposées dans la maison de l'emploi de Lille. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour un forum des métiers, des visites en petits groupes seront proposées dans la maison de l'emploi de Lille. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":23.412,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["La visiteuse souhaite des précisions sur les horaires imprévisibles des travailleurs précaires.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet."],"correct":"A","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur les horaires imprévisibles des travailleurs précaires ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte les horaires imprévisibles des travailleurs précaires. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte les horaires imprévisibles des travailleurs précaires. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.823,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Définir les activités prioritaires selon le public attendu pour un forum des métiers.","Adapter les tâches des bénévoles aux compétences requises pour un forum des métiers.","Prévoir le matériel nécessaire selon les inscriptions à un forum des métiers.","Répartir les bénévoles d’un forum des métiers selon les créneaux où ils sont libres."],"correct":"D","explanation":"Le document permet de retenir « Répartir les bénévoles d’un forum des métiers selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la maison de l'emploi de Lille, pour préparer un forum des métiers, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la maison de l'emploi de Lille, pour préparer un forum des métiers, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":35.939,"slotSeconds":52},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les connaissances pratiques acquises au cours de un atelier de préparation aux entretiens.","Les nouveaux contacts professionnels pris pendant un atelier de préparation aux entretiens.","Les relations de confiance créées autour d’un atelier de préparation aux entretiens.","La meilleure organisation des activités obtenue grâce à un atelier de préparation aux entretiens."],"correct":"C","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de préparation aux entretiens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de préparation aux entretiens. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les salariés en poste n'ont pas le temps de suivre les formations en journée. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de préparation aux entretiens. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les salariés en poste n'ont pas le temps de suivre les formations en journée. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":46.145,"slotSeconds":64},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Consulter les habitants sur des séances courtes et des congés de formation négociés sans mener d’essai concret.","Expérimenter des séances courtes et des congés de formation négociés, recueillir les avis et publier un bilan.","Expérimenter des séances courtes et des congés de formation négociés mais ne publier aucun retour des participants.","Mettre en place des séances courtes et des congés de formation négociés partout avant de mesurer les résultats."],"correct":"B","explanation":"Le document permet de retenir « Expérimenter des séances courtes et des congés de formation négociés, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Travail et vie professionnelle ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des séances courtes et des congés de formation négociés.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les salariés en poste n'ont pas le temps de suivre les formations en journée.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Travail et vie professionnelle »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des séances courtes et des congés de formation négociés."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les salariés en poste n'ont pas le temps de suivre les formations en journée."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":54.206,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les usagers qui ont abandonné l'accompagnement des reconversions sont peu représentés.","L’étude de l'accompagnement des reconversions s’appuie principalement sur les réponses des agents.","L’étude de l'accompagnement des reconversions donne peu de place aux nouveaux inscrits.","L’étude de l'accompagnement des reconversions comprend surtout des personnes en attente."],"correct":"A","explanation":"Le document permet de retenir « Les usagers qui ont abandonné l'accompagnement des reconversions sont peu représentés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant l'accompagnement des reconversions. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les salariés en poste n'ont pas le temps de suivre les formations en journée. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant l'accompagnement des reconversions. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les salariés en poste n'ont pas le temps de suivre les formations en journée. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":52.315,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Concilier des formations adaptées avec les contraintes d’horaires des salariés."],"correct":"D","explanation":"Le document permet de retenir « Concilier des formations adaptées avec les contraintes d’horaires des salariés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la maison de l'emploi de Lille, une initiative propose des séances courtes et des congés de formation négociés. Les responsables espèrent ainsi répondre à une difficulté bien connue : les salariés en poste n'ont pas le temps de suivre les formations en journée.\nNous soutenons l’objectif général, mais il faut prendre en compte les horaires imprévisibles des travailleurs précaires. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que garantir des formations reconnues et un accompagnement durable. Pourtant, les petites entreprises peinent à remplacer les salariés absents. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la maison de l'emploi de Lille, une initiative propose des séances courtes et des congés de formation négociés. Les responsables espèrent ainsi répondre à une difficulté bien connue : les salariés en poste n'ont pas le temps de suivre les formations en journée."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte les horaires imprévisibles des travailleurs précaires. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que garantir des formations reconnues et un accompagnement durable. Pourtant, les petites entreprises peinent à remplacer les salariés absents. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":54.516,"slotSeconds":72},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les résultats de une permanence de conseil en soirée concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre une permanence de conseil en soirée dès la fin des premiers essais.","Les premiers effets d’une permanence de conseil en soirée doivent être vérifiés dans la durée.","Le projet de une permanence de conseil en soirée est annoncé mais n’a pas encore été lancé."],"correct":"C","explanation":"Le document permet de retenir « Les premiers effets d’une permanence de conseil en soirée doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une permanence de conseil en soirée. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les petites entreprises peinent à remplacer les salariés absents. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la stabilité des emplois obtenus six mois après la formation. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une permanence de conseil en soirée. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les petites entreprises peinent à remplacer les salariés absents. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la stabilité des emplois obtenus six mois après la formation. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.956,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Réserver les créneaux matinaux de l'accompagnement des reconversions aux seuls abonnés.","Réorganiser les horaires de l'accompagnement des reconversions sans supprimer les créneaux du soir.","Ouvrir l'accompagnement des reconversions plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de l'accompagnement des reconversions malgré les demandes du matin."],"correct":"B","explanation":"Le document permet de retenir « Réorganiser les horaires de l'accompagnement des reconversions sans supprimer les créneaux du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que l'accompagnement des reconversions ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que l'accompagnement des reconversions ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":40.714,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Préparer le budget de une salle de simulation professionnelle avant de calculer son entretien.","Adapter les équipements de une salle de simulation professionnelle après consultation des équipes.","Tester une salle de simulation professionnelle sur un seul site avant de l’ouvrir à tous."],"correct":"A","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de une salle de simulation professionnelle a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de les horaires imprévisibles des travailleurs précaires est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une salle de simulation professionnelle a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de les horaires imprévisibles des travailleurs précaires est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.784,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de la stabilité des emplois obtenus six mois après la formation ; l’autre mesure la fréquentation.","L’un veut mesurer la stabilité des emplois obtenus six mois après la formation ; l’autre demande des récits."],"correct":"D","explanation":"Le document permet de retenir « L’un veut mesurer la stabilité des emplois obtenus six mois après la formation ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Travail et vie professionnelle ».\nSans chiffres comparables, impossible de dire si une permanence de conseil en soirée apporte un bénéfice mesurable. Nous devons étudier la stabilité des emplois obtenus six mois après la formation.\nLes chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les salariés en poste n'ont pas le temps de suivre les formations en journée.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Travail et vie professionnelle »."},{"voice":"male","text":"Sans chiffres comparables, impossible de dire si une permanence de conseil en soirée apporte un bénéfice mesurable. Nous devons étudier la stabilité des emplois obtenus six mois après la formation."},{"voice":"female","text":"Les chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les salariés en poste n'ont pas le temps de suivre les formations en journée."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":47.006,"slotSeconds":65},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Moderniser les salles de un atelier de préparation aux entretiens en effaçant les anciennes traces.","Rénover le lieu de un atelier de préparation aux entretiens sans changer l’usage actuel des espaces.","Préserver l’histoire du lieu d’un atelier de préparation aux entretiens tout en y proposant de nouveaux usages.","Conserver le bâtiment de un atelier de préparation aux entretiens uniquement pour ses activités passées."],"correct":"C","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de préparation aux entretiens tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de préparation aux entretiens, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de préparation aux entretiens, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":52.199,"slotSeconds":70},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Comparer la force d’une corrélation dans plusieurs échantillons.","Ne pas confondre une corrélation statistique et une cause démontrée.","Déduire un effet causal lorsque deux tendances se répètent.","Établir une cause unique à partir de deux changements simultanés."],"correct":"B","explanation":"Le document permet de retenir « Ne pas confondre une corrélation statistique et une cause démontrée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la stabilité des emplois obtenus six mois après la formation. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les salariés en poste n'ont pas le temps de suivre les formations en journée. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la stabilité des emplois obtenus six mois après la formation. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : les salariés en poste n'ont pas le temps de suivre les formations en journée. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":50.741,"slotSeconds":68},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour l'accompagnement des reconversions, présenter les hypothèses et les incertitudes des prévisions.","Pour l'accompagnement des reconversions, accorder la même fiabilité à toutes les prévisions disponibles.","Pour l'accompagnement des reconversions, publier un chiffre précis sans détailler ses limites.","Pour l'accompagnement des reconversions, annoncer une moyenne sans préciser les hypothèses retenues."],"correct":"A","explanation":"Le document permet de retenir « Pour l'accompagnement des reconversions, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant l'accompagnement des reconversions, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant l'accompagnement des reconversions, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":51.787,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites à la maison de l'emploi de Lille vient surtout des horaires étendus.","La fréquentation de la maison de l'emploi de Lille varie trop selon les saisons.","Les chiffres de la maison de l'emploi de Lille ne tiennent pas compte du prix des activités.","La hausse des visites ne démontre pas un bénéfice durable du projet."],"correct":"D","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la maison de l'emploi de Lille, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une permanence de conseil en soirée. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la stabilité des emplois obtenus six mois après la formation ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la maison de l'emploi de Lille, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une permanence de conseil en soirée. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la stabilité des emplois obtenus six mois après la formation ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":47.943,"slotSeconds":65},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester l'accompagnement des reconversions uniquement par les usagers réguliers.","Maintenir une aide humaine à l'accompagnement des reconversions pendant le seul lancement.","Faire tester l'accompagnement des reconversions par divers publics, avec une aide humaine conservée.","Évaluer l'accompagnement des reconversions auprès de tous puis supprimer l’accueil individuel."],"correct":"C","explanation":"Le document permet de retenir « Faire tester l'accompagnement des reconversions par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la maison de l'emploi de Lille.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : les horaires imprévisibles des travailleurs précaires.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la maison de l'emploi de Lille."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : les horaires imprévisibles des travailleurs précaires."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.685,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les usages quotidiens du matériel de le centre de formation peuvent changer ses effets.","Une technologie installée dans le centre de formation garantit un bon résultat sans tenir compte des usages.","Les conditions de terrain de le centre de formation influencent les résultats observés.","La performance du dispositif de le centre de formation exige un entretien régulier."],"correct":"B","explanation":"Le document permet de retenir « Une technologie installée dans le centre de formation garantit un bon résultat sans tenir compte des usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le centre de formation affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le centre de formation affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.053,"slotSeconds":69},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Permettre une participation volontaire et réciproque à un atelier de préparation aux entretiens.","Évaluer le lien créé à un atelier de préparation aux entretiens uniquement par le nombre de présences.","Assurer une présence régulière aux séances de un atelier de préparation aux entretiens sans échanger.","Répartir les rôles de un atelier de préparation aux entretiens entre des participants désignés à l’avance."],"correct":"A","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier de préparation aux entretiens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de préparation aux entretiens réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : les horaires imprévisibles des travailleurs précaires. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de préparation aux entretiens réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : les horaires imprévisibles des travailleurs précaires. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":53.871,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Conserver les récits de l'accompagnement des reconversions qui concordent avec la majorité.","Classer les témoignages de l'accompagnement des reconversions selon l’ancienneté de leurs auteurs.","Comparer les récits de l'accompagnement des reconversions sans consulter les archives disponibles.","Comparer les récits concernant l'accompagnement des reconversions aux faits vérifiables."],"correct":"D","explanation":"Le document permet de retenir « Comparer les récits concernant l'accompagnement des reconversions aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant l'accompagnement des reconversions, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant l'accompagnement des reconversions, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.987,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La fréquentation de une permanence de conseil en soirée ralentit la promotion du dispositif.","La croissance de une permanence de conseil en soirée augmente le budget sans effet sur les usagers.","Le succès d’une permanence de conseil en soirée peut créer des difficultés aux usagers.","Le succès de une permanence de conseil en soirée réduit les demandes des services voisins."],"correct":"C","explanation":"Le document permet de retenir « Le succès d’une permanence de conseil en soirée peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Travail et vie professionnelle ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une permanence de conseil en soirée peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les salariés en poste n'ont pas le temps de suivre les formations en journée. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner les horaires imprévisibles des travailleurs précaires. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Travail et vie professionnelle ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une permanence de conseil en soirée peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les salariés en poste n'ont pas le temps de suivre les formations en journée. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner les horaires imprévisibles des travailleurs précaires. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":62.839,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Étendre le service en privilégiant seulement les premiers résultats de la stabilité des emplois obtenus six mois après la formation.","Organiser des ressources durables et suivre la stabilité des emplois obtenus six mois après la formation pour poursuivre l'accompagnement des reconversions.","Suivre la stabilité des emplois obtenus six mois après la formation en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer la stabilité des emplois obtenus six mois après la formation."],"correct":"B","explanation":"Le document permet de retenir « Organiser des ressources durables et suivre la stabilité des emplois obtenus six mois après la formation pour poursuivre l'accompagnement des reconversions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à l'accompagnement des reconversions, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les petites entreprises peinent à remplacer les salariés absents. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la stabilité des emplois obtenus six mois après la formation. L’idée n’est pas d’abandonner l’ambition de départ : garantir des formations reconnues et un accompagnement durable. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à l'accompagnement des reconversions, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les petites entreprises peinent à remplacer les salariés absents. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la stabilité des emplois obtenus six mois après la formation. L’idée n’est pas d’abandonner l’ambition de départ : garantir des formations reconnues et un accompagnement durable. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.49,"slotSeconds":82}]},{"id":"tcf-listening-09","version":"tcf-listening-2026-11-test09-v2","title":"TCF Listening · Test 09","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La scène représente une personne assise, occupée à consulter une tablette électronique.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle consulte une tablette électronique à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle consulte une tablette électronique à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.885,"slotSeconds":33},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Un homme présente une affiche liée à technologie et services numériques.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur technologie et services numériques à un groupe.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur technologie et services numériques à un groupe."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":18.431,"slotSeconds":34},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Deux interlocuteurs préparent une semaine du numérique autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une semaine du numérique autour d'une table. D. Deux personnes traversent une rivière.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent une semaine du numérique autour d'une table. D. Deux personnes traversent une rivière."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.942,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'illustration montre une personne portant un sac devant l'espace numérique de Grenoble.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Des enfants jouent dans un jardin. B. Une femme porte un sac devant l'espace numérique de Grenoble. C. Une femme nage dans une piscine. D. Un homme répare un vélo.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Des enfants jouent dans un jardin. B. Une femme porte un sac devant l'espace numérique de Grenoble. C. Une femme nage dans une piscine. D. Un homme répare un vélo."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.791,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier de sécurité informatique ?\nA. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier de sécurité informatique ?"},{"voice":"female","text":"A. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie."}],"audio":"q-05.mp3","audioSeconds":19.209,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter une tablette électronique pour participer à une semaine du numérique ?\nA. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter une tablette électronique pour participer à une semaine du numérique ?"},{"voice":"female","text":"A. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place."}],"audio":"q-06.mp3","audioSeconds":19.708,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier de sécurité informatique ?\nA. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier de sécurité informatique ?"},{"voice":"female","text":"A. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles."}],"audio":"q-07.mp3","audioSeconds":17.589,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une semaine du numérique. Est-ce possible ?\nA. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une semaine du numérique. Est-ce possible ?"},{"voice":"female","text":"A. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage."}],"audio":"q-08.mp3","audioSeconds":21.24,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["un service d'assistance téléphonique sans frais","Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles."],"correct":"A","explanation":"Le document permet de retenir « un service d'assistance téléphonique sans frais ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans l'espace numérique de Grenoble, à compter de lundi prochain, nous mettons en place un service d'assistance téléphonique sans frais. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans l'espace numérique de Grenoble, à compter de lundi prochain, nous mettons en place un service d'assistance téléphonique sans frais. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.612,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier de sécurité informatique est reporté au lendemain.","Un autre créneau est proposé pour un atelier de sécurité informatique en raison des transports.","Le rendez-vous pour un atelier de sécurité informatique est avancé d’une demi-heure.","Le rendez-vous d’un atelier de sécurité informatique est repoussé à cause d’une réunion prolongée."],"correct":"D","explanation":"Le document permet de retenir « Le rendez-vous d’un atelier de sécurité informatique est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier de sécurité informatique ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier de sécurité informatique ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.71,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Déposer sa demande pour une semaine du numérique à l’accueil le jour même.","Réserver sa place pour une semaine du numérique par téléphone avant jeudi.","Pour une semaine du numérique, le formulaire doit être rempli en ligne avant jeudi.","Envoyer le formulaire de une semaine du numérique par courriel avant vendredi."],"correct":"C","explanation":"Le document permet de retenir « Pour une semaine du numérique, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Technologie et services numériques » aura lieu dans l'espace numérique de Grenoble. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Technologie et services numériques » aura lieu dans l'espace numérique de Grenoble. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.236,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Présenter une pièce d’identité à l’accueil pour accéder à un atelier de sécurité informatique.","Présenter le message de confirmation pour un atelier de sécurité informatique à l’accueil.","Remplir un nouveau formulaire d’inscription pour participer à un atelier de sécurité informatique.","Demander une confirmation écrite après la fin de un atelier de sécurité informatique."],"correct":"B","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier de sécurité informatique à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier de sécurité informatique, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier de sécurité informatique, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.524,"slotSeconds":44},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance prévue pour un atelier de sécurité informatique commence une heure plus tard.","La séance de un atelier de sécurité informatique est reportée au lendemain à la même heure.","La séance de un atelier de sécurité informatique change de salle mais garde le même horaire.","La séance de un atelier de sécurité informatique commence une heure plus tôt que prévu."],"correct":"A","explanation":"Le document permet de retenir « La séance prévue pour un atelier de sécurité informatique commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier de sécurité informatique. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier de sécurité informatique. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.52,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Garder un atelier de sécurité informatique mais renoncer à fournir la démonstration prévue.","Maintenir un atelier de sécurité informatique avec une démonstration réalisée sans le matériel.","Reporter un atelier de sécurité informatique jusqu’à ce que le matériel soit disponible.","Conserver un atelier de sécurité informatique et envoyer ensuite la démonstration manquante."],"correct":"D","explanation":"Le document permet de retenir « Conserver un atelier de sécurité informatique et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier de sécurité informatique n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier de sécurité informatique n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.873,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans l'espace numérique de Grenoble, la mesure a été suspendue faute de participants.","Dans l'espace numérique de Grenoble, les difficultés ont été réglées avant le lancement.","La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans l'espace numérique de Grenoble, l’initiative est désormais réservée aux habitués."],"correct":"C","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans l'espace numérique de Grenoble : un service d'assistance téléphonique sans frais. Le dispositif vise à répondre à une difficulté bien connue : les procédures en ligne demeurent difficiles pour les personnes peu équipées. Plusieurs représentants soulignent toutefois que le portail connaît des ralentissements aux heures de pointe. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans l'espace numérique de Grenoble : un service d'assistance téléphonique sans frais. Le dispositif vise à répondre à une difficulté bien connue : les procédures en ligne demeurent difficiles pour les personnes peu équipées. Plusieurs représentants soulignent toutefois que le portail connaît des ralentissements aux heures de pointe. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":31.028,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Réserver les permanences de l'aide aux démarches en ligne aux inscriptions du matin.","Répartir les permanences de l'aide aux démarches en ligne pour maintenir l’accueil continu.","Répartir les permanences de l'aide aux démarches en ligne entre deux lieux différents.","Avancer les horaires de l'aide aux démarches en ligne en supprimant le relais du soir."],"correct":"B","explanation":"Le document permet de retenir « Répartir les permanences de l'aide aux démarches en ligne pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour l'aide aux démarches en ligne.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour l'aide aux démarches en ligne."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.295,"slotSeconds":42},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui rencontrent des obstacles dans l'espace numérique de Grenoble.","Les employés chargés d’accueillir et d’orienter les visiteurs de l'espace numérique de Grenoble.","Les visiteurs ayant déjà terminé leurs démarches dans l'espace numérique de Grenoble.","Les personnes qui fréquentent régulièrement les ateliers de l'espace numérique de Grenoble."],"correct":"A","explanation":"Le document permet de retenir « Les personnes qui rencontrent des obstacles dans l'espace numérique de Grenoble ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans l'espace numérique de Grenoble. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les procédures en ligne demeurent difficiles pour les personnes peu équipées. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans l'espace numérique de Grenoble. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les procédures en ligne demeurent difficiles pour les personnes peu équipées. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":30.006,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle ne peut se rendre à une semaine du numérique à cause d’un retard de transport.","Elle souhaite déplacer une semaine du numérique à cause d’un changement de salle.","Elle demande un autre horaire pour une semaine du numérique afin d’accompagner un proche.","Elle travaille encore vendredi à seize heures, au moment d’une semaine du numérique."],"correct":"D","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une semaine du numérique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une semaine du numérique. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une semaine du numérique. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.01,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Adapter le nombre de places de une semaine du numérique à la taille de la salle.","Répartir les participants de une semaine du numérique selon leur expérience.","Le petit groupe permet d’échanger davantage pendant une semaine du numérique.","Réduire le groupe de une semaine du numérique pour utiliser moins de matériel."],"correct":"C","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant une semaine du numérique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une semaine du numérique, des visites en petits groupes seront proposées dans l'espace numérique de Grenoble. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une semaine du numérique, des visites en petits groupes seront proposées dans l'espace numérique de Grenoble. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.05,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle cherche à connaître le prix définitif de sa participation au projet.","Elle souhaite savoir comment sera pris en compte la protection des données personnelles.","Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués."],"correct":"B","explanation":"Le document permet de retenir « Elle souhaite savoir comment sera pris en compte la protection des données personnelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la protection des données personnelles. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la protection des données personnelles. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.381,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Organiser les permanences selon les horaires disponibles des bénévoles.","Adapter les tâches des bénévoles aux compétences requises pour une semaine du numérique.","Prévoir le matériel nécessaire selon les inscriptions à une semaine du numérique.","Définir les activités prioritaires selon le public attendu pour une semaine du numérique."],"correct":"A","explanation":"Le document permet de retenir « Organiser les permanences selon les horaires disponibles des bénévoles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans l'espace numérique de Grenoble, pour préparer une semaine du numérique, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans l'espace numérique de Grenoble, pour préparer une semaine du numérique, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.438,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les nouveaux contacts professionnels pris pendant un atelier de sécurité informatique.","La meilleure organisation des activités obtenue grâce à un atelier de sécurité informatique.","Les connaissances pratiques acquises au cours de un atelier de sécurité informatique.","Les relations de confiance créées autour d’un atelier de sécurité informatique."],"correct":"D","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’un atelier de sécurité informatique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier de sécurité informatique. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les procédures en ligne demeurent difficiles pour les personnes peu équipées. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier de sécurité informatique. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les procédures en ligne demeurent difficiles pour les personnes peu équipées. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.291,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Expérimenter des conseillers accessibles et des interfaces testées avec les usagers mais ne publier aucun retour des participants.","Mettre en place des conseillers accessibles et des interfaces testées avec les usagers partout avant de mesurer les résultats.","Expérimenter des conseillers accessibles et des interfaces testées avec les usagers, recueillir les avis et publier un bilan.","Consulter les habitants sur des conseillers accessibles et des interfaces testées avec les usagers sans mener d’essai concret."],"correct":"C","explanation":"Le document permet de retenir « Expérimenter des conseillers accessibles et des interfaces testées avec les usagers, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Technologie et services numériques ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des conseillers accessibles et des interfaces testées avec les usagers.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les procédures en ligne demeurent difficiles pour les personnes peu équipées.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Technologie et services numériques »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des conseillers accessibles et des interfaces testées avec les usagers."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les procédures en ligne demeurent difficiles pour les personnes peu équipées."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":55.738,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de l'aide aux démarches en ligne donne peu de place aux nouveaux inscrits.","L’étude de l'aide aux démarches en ligne exclut presque ceux qui ont cessé de l’utiliser.","L’étude de l'aide aux démarches en ligne comprend surtout des personnes en attente.","L’étude de l'aide aux démarches en ligne s’appuie principalement sur les réponses des agents."],"correct":"B","explanation":"Le document permet de retenir « L’étude de l'aide aux démarches en ligne exclut presque ceux qui ont cessé de l’utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant l'aide aux démarches en ligne. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les procédures en ligne demeurent difficiles pour les personnes peu équipées. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant l'aide aux démarches en ligne. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les procédures en ligne demeurent difficiles pour les personnes peu équipées. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":50.794,"slotSeconds":67},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Concilier l’assistance numérique avec les difficultés des personnes peu équipées.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants."],"correct":"A","explanation":"Le document permet de retenir « Concilier l’assistance numérique avec les difficultés des personnes peu équipées ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans l'espace numérique de Grenoble, une initiative propose des conseillers accessibles et des interfaces testées avec les usagers. Les responsables espèrent ainsi répondre à une difficulté bien connue : les procédures en ligne demeurent difficiles pour les personnes peu équipées.\nNous soutenons l’objectif général, mais il faut prendre en compte la protection des données personnelles. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que financer l'accompagnement humain et simplifier les formulaires. Pourtant, le portail connaît des ralentissements aux heures de pointe. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans l'espace numérique de Grenoble, une initiative propose des conseillers accessibles et des interfaces testées avec les usagers. Les responsables espèrent ainsi répondre à une difficulté bien connue : les procédures en ligne demeurent difficiles pour les personnes peu équipées."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la protection des données personnelles. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que financer l'accompagnement humain et simplifier les formulaires. Pourtant, le portail connaît des ralentissements aux heures de pointe. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":53.645,"slotSeconds":70},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["L’équipe souhaite interrompre un service d'assistance téléphonique sans frais dès la fin des premiers essais.","Le projet de un service d'assistance téléphonique sans frais est annoncé mais n’a pas encore été lancé.","Les résultats de un service d'assistance téléphonique sans frais concernent uniquement les coûts de gestion.","Les premiers effets d’un service d'assistance téléphonique sans frais doivent être vérifiés dans la durée."],"correct":"D","explanation":"Le document permet de retenir « Les premiers effets d’un service d'assistance téléphonique sans frais doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé un service d'assistance téléphonique sans frais. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Le portail connaît des ralentissements aux heures de pointe. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la proportion de démarches achevées sans assistance supplémentaire. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé un service d'assistance téléphonique sans frais. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Le portail connaît des ralentissements aux heures de pointe. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la proportion de démarches achevées sans assistance supplémentaire. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.281,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Ouvrir l'aide aux démarches en ligne plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de l'aide aux démarches en ligne malgré les demandes du matin.","Adapter les horaires de l'aide aux démarches en ligne sans pénaliser les usagers du soir.","Réserver les créneaux matinaux de l'aide aux démarches en ligne aux seuls abonnés."],"correct":"C","explanation":"Le document permet de retenir « Adapter les horaires de l'aide aux démarches en ligne sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que l'aide aux démarches en ligne ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que l'aide aux démarches en ligne ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.642,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Adapter les équipements de un guichet hybride après consultation des équipes.","Les équipements d’un guichet hybride ont été choisis avant la consultation des futurs usagers.","Tester un guichet hybride sur un seul site avant de l’ouvrir à tous.","Préparer le budget de un guichet hybride avant de calculer son entretien."],"correct":"B","explanation":"Le document permet de retenir « Les équipements d’un guichet hybride ont été choisis avant la consultation des futurs usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un guichet hybride a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la protection des données personnelles est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un guichet hybride a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la protection des données personnelles est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":48.031,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut mesurer la proportion de démarches achevées sans assistance supplémentaire ; l’autre demande des récits.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de la proportion de démarches achevées sans assistance supplémentaire ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières."],"correct":"A","explanation":"Le document permet de retenir « L’un veut mesurer la proportion de démarches achevées sans assistance supplémentaire ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Technologie et services numériques ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la proportion de démarches achevées sans assistance supplémentaire et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les procédures en ligne demeurent difficiles pour les personnes peu équipées. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Technologie et services numériques »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la proportion de démarches achevées sans assistance supplémentaire et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les procédures en ligne demeurent difficiles pour les personnes peu équipées. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":51.569,"slotSeconds":69},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Rénover le lieu de un atelier de sécurité informatique sans changer l’usage actuel des espaces.","Conserver le bâtiment de un atelier de sécurité informatique uniquement pour ses activités passées.","Moderniser les salles de un atelier de sécurité informatique en effaçant les anciennes traces.","Préserver l’histoire du lieu d’un atelier de sécurité informatique tout en y proposant de nouveaux usages."],"correct":"D","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’un atelier de sécurité informatique tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier de sécurité informatique, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier de sécurité informatique, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.398,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Mesurer l’évolution d’un projet uniquement pendant son lancement.","Suivre seulement les personnes arrivées au cours du premier mois.","Distinguer une amélioration immédiate d’un changement durable.","Comparer les progrès enregistrés lors des deux premières semaines."],"correct":"C","explanation":"Le document permet de retenir « Distinguer une amélioration immédiate d’un changement durable ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la proportion de démarches achevées sans assistance supplémentaire. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les procédures en ligne demeurent difficiles pour les personnes peu équipées. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la proportion de démarches achevées sans assistance supplémentaire. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les procédures en ligne demeurent difficiles pour les personnes peu équipées. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":54.886,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour l'aide aux démarches en ligne, publier un chiffre précis sans détailler ses limites.","Pour l'aide aux démarches en ligne, présenter les hypothèses et les incertitudes des prévisions.","Pour l'aide aux démarches en ligne, annoncer une moyenne sans préciser les hypothèses retenues.","Pour l'aide aux démarches en ligne, accorder la même fiabilité à toutes les prévisions disponibles."],"correct":"B","explanation":"Le document permet de retenir « Pour l'aide aux démarches en ligne, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant l'aide aux démarches en ligne, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant l'aide aux démarches en ligne, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.09,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites ne démontre pas un bénéfice durable du projet.","La fréquentation de l'espace numérique de Grenoble varie trop selon les saisons.","Les chiffres de l'espace numérique de Grenoble ne tiennent pas compte du prix des activités.","La hausse des visites à l'espace numérique de Grenoble vient surtout des horaires étendus."],"correct":"A","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans l'espace numérique de Grenoble, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un service d'assistance téléphonique sans frais. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la proportion de démarches achevées sans assistance supplémentaire ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans l'espace numérique de Grenoble, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un service d'assistance téléphonique sans frais. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la proportion de démarches achevées sans assistance supplémentaire ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.851,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Maintenir une aide humaine à l'aide aux démarches en ligne pendant le seul lancement.","Évaluer l'aide aux démarches en ligne auprès de tous puis supprimer l’accueil individuel.","Faire tester l'aide aux démarches en ligne uniquement par les usagers réguliers.","Faire tester l'aide aux démarches en ligne par divers publics, avec une aide humaine conservée."],"correct":"D","explanation":"Le document permet de retenir « Faire tester l'aide aux démarches en ligne par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans l'espace numérique de Grenoble.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la protection des données personnelles.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans l'espace numérique de Grenoble."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la protection des données personnelles."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.639,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les conditions de terrain de le laboratoire de médiation numérique influencent les résultats observés.","La performance du dispositif de le laboratoire de médiation numérique exige un entretien régulier.","Les résultats techniques du laboratoire de médiation numérique suffiraient même si les usages réels diffèrent.","Les usages quotidiens du matériel de le laboratoire de médiation numérique peuvent changer ses effets."],"correct":"C","explanation":"Le document permet de retenir « Les résultats techniques du laboratoire de médiation numérique suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le laboratoire de médiation numérique affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le laboratoire de médiation numérique affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":51.463,"slotSeconds":69},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Assurer une présence régulière aux séances de un atelier de sécurité informatique sans échanger.","Le volontariat et les échanges réciproques pendant un atelier de sécurité informatique renforcent les liens.","Répartir les rôles de un atelier de sécurité informatique entre des participants désignés à l’avance.","Évaluer le lien créé à un atelier de sécurité informatique uniquement par le nombre de présences."],"correct":"B","explanation":"Le document permet de retenir « Le volontariat et les échanges réciproques pendant un atelier de sécurité informatique renforcent les liens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier de sécurité informatique réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la protection des données personnelles. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier de sécurité informatique réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la protection des données personnelles. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":52.867,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Confronter des récits divergents aux documents vérifiables.","Classer les témoignages de l'aide selon l’ancienneté de leurs auteurs.","Comparer les récits de l'aide sans consulter les archives disponibles.","Conserver les récits de l'aide qui concordent avec la majorité."],"correct":"A","explanation":"Le document permet de retenir « Confronter des récits divergents aux documents vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant l'aide aux démarches en ligne, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant l'aide aux démarches en ligne, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.25,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La croissance de un service d'assistance téléphonique sans frais augmente le budget sans effet sur les usagers.","Le succès de un service d'assistance téléphonique sans frais réduit les demandes des services voisins.","La fréquentation de un service d'assistance téléphonique sans frais ralentit la promotion du dispositif.","Le succès d’un service d'assistance téléphonique sans frais peut créer des difficultés aux usagers."],"correct":"D","explanation":"Le document permet de retenir « Le succès d’un service d'assistance téléphonique sans frais peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Technologie et services numériques ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un service d'assistance téléphonique sans frais peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les procédures en ligne demeurent difficiles pour les personnes peu équipées. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la protection des données personnelles. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Technologie et services numériques ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un service d'assistance téléphonique sans frais peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les procédures en ligne demeurent difficiles pour les personnes peu équipées. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la protection des données personnelles. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.199,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Suivre la proportion de démarches achevées sans assistance supplémentaire en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer la proportion de démarches achevées sans assistance supplémentaire.","Assurer des moyens durables et suivre la proportion de démarches achevées sans assistance supplémentaire sur la durée.","Étendre le service en privilégiant seulement les premiers résultats de la proportion de démarches achevées sans assistance supplémentaire."],"correct":"C","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre la proportion de démarches achevées sans assistance supplémentaire sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à l'aide aux démarches en ligne, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper le portail connaît des ralentissements aux heures de pointe. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la proportion de démarches achevées sans assistance supplémentaire. L’idée n’est pas d’abandonner l’ambition de départ : financer l'accompagnement humain et simplifier les formulaires. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à l'aide aux démarches en ligne, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper le portail connaît des ralentissements aux heures de pointe. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la proportion de démarches achevées sans assistance supplémentaire. L’idée n’est pas d’abandonner l’ambition de départ : financer l'accompagnement humain et simplifier les formulaires. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.978,"slotSeconds":82}]},{"id":"tcf-listening-10","version":"tcf-listening-2026-11-test10-v2","title":"TCF Listening · Test 10","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La scène représente une personne assise, occupée à consulter un relevé de consommation électrique.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle répare le moteur d'une voiture. B. Elle consulte un relevé de consommation électrique à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle répare le moteur d'une voiture. B. Elle consulte un relevé de consommation électrique à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":19.255,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Un homme présente une affiche liée à climat et énergie.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il présente une affiche sur climat et énergie à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il présente une affiche sur climat et énergie à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.514,"slotSeconds":32},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Deux interlocuteurs préparent une journée de la transition énergétique autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une journée de la transition énergétique autour d'une table.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une journée de la transition énergétique autour d'une table."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.267,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'illustration montre une personne portant un sac devant l'agence locale de l'énergie de Tours.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant l'agence locale de l'énergie de Tours. D. Une femme nage dans une piscine.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant l'agence locale de l'énergie de Tours. D. Une femme nage dans une piscine."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.477,"slotSeconds":33},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse précise le point de départ de l'activité.","transcript":"Question 5.\nExcusez-moi, où commence une visite d'une maison isolée ?\nA. La météo annonce de la pluie. B. Le point de départ est devant l’accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où commence une visite d'une maison isolée ?"},{"voice":"female","text":"A. La météo annonce de la pluie. B. Le point de départ est devant l’accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir."}],"audio":"q-05.mp3","audioSeconds":17.138,"slotSeconds":33},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un relevé de consommation électrique pour participer à une journée de la transition énergétique ?\nA. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un relevé de consommation électrique pour participer à une journée de la transition énergétique ?"},{"voice":"female","text":"A. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie."}],"audio":"q-06.mp3","audioSeconds":21.032,"slotSeconds":37},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour une visite d'une maison isolée ?\nA. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour une visite d'une maison isolée ?"},{"voice":"female","text":"A. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée."}],"audio":"q-07.mp3","audioSeconds":17.27,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une journée de la transition énergétique. Est-ce possible ?\nA. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une journée de la transition énergétique. Est-ce possible ?"},{"voice":"female","text":"A. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver."}],"audio":"q-08.mp3","audioSeconds":21.879,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un nouveau lieu d’accueil pour les visiteurs inscrits.","Une aide à l'installation de protections solaires.","Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées."],"correct":"B","explanation":"Le document permet de retenir « Une aide à l'installation de protections solaires ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans l'agence locale de l'énergie de Tours, à compter de lundi prochain, nous mettons en place une aide à l'installation de protections solaires. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans l'agence locale de l'énergie de Tours, à compter de lundi prochain, nous mettons en place une aide à l'installation de protections solaires. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.893,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous est décalé parce qu’une réunion finit plus tard.","Un autre créneau est proposé pour une visite d'une maison isolée en raison des transports.","Le rendez-vous pour une visite d'une maison isolée est avancé d’une demi-heure.","Le rendez-vous pour une visite d'une maison isolée est reporté au lendemain."],"correct":"A","explanation":"Le document permet de retenir « Le rendez-vous est décalé parce qu’une réunion finit plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour une visite d'une maison isolée ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour une visite d'une maison isolée ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":26.821,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Réserver sa place pour une journée de la transition énergétique par téléphone avant jeudi.","Envoyer le formulaire de une journée de la transition énergétique par courriel avant vendredi.","Déposer sa demande pour une journée de la transition énergétique à l’accueil le jour même.","Pour une journée de la transition énergétique, le formulaire doit être rempli en ligne avant jeudi."],"correct":"D","explanation":"Le document permet de retenir « Pour une journée de la transition énergétique, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Climat et énergie » aura lieu dans l'agence locale de l'énergie de Tours. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Climat et énergie » aura lieu dans l'agence locale de l'énergie de Tours. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.165,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Remplir un nouveau formulaire d’inscription pour participer à une visite d'une maison isolée.","Demander une confirmation écrite après la fin de une visite d'une maison isolée.","Présenter le message de confirmation pour une visite d'une maison isolée à l’accueil.","Présenter une pièce d’identité à l’accueil pour accéder à une visite d'une maison isolée."],"correct":"C","explanation":"Le document permet de retenir « Présenter le message de confirmation pour une visite d'une maison isolée à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à une visite d'une maison isolée, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à une visite d'une maison isolée, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.769,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de une visite d'une maison isolée change de salle mais garde le même horaire.","La séance d’une visite d'une maison isolée est décalée à quinze heures, au même endroit.","La séance de une visite d'une maison isolée commence une heure plus tôt que prévu.","La séance de une visite d'une maison isolée est reportée au lendemain à la même heure."],"correct":"B","explanation":"Le document permet de retenir « La séance d’une visite d'une maison isolée est décalée à quinze heures, au même endroit ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour une visite d'une maison isolée. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour une visite d'une maison isolée. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.624,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Maintenir l’introduction et transmettre la démonstration plus tard.","Maintenir une visite d'une maison isolée avec une démonstration réalisée sans le matériel.","Reporter une visite d'une maison isolée jusqu’à ce que le matériel soit disponible.","Garder une visite d'une maison isolée mais renoncer à fournir la démonstration prévue."],"correct":"A","explanation":"Le document permet de retenir « Maintenir l’introduction et transmettre la démonstration plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à une visite d'une maison isolée n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à une visite d'une maison isolée n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.049,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans l'agence locale de l'énergie de Tours, les difficultés ont été réglées avant le lancement.","Dans l'agence locale de l'énergie de Tours, l’initiative est désormais réservée aux habitués.","Dans l'agence locale de l'énergie de Tours, la mesure a été suspendue faute de participants.","La mesure présentée à l'agence locale de l'énergie de Tours répond au besoin sans lever toutes les difficultés."],"correct":"D","explanation":"Le document permet de retenir « La mesure présentée à l'agence locale de l'énergie de Tours répond au besoin sans lever toutes les difficultés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans l'agence locale de l'énergie de Tours : une aide à l'installation de protections solaires. Le dispositif vise à répondre à une difficulté bien connue : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Plusieurs représentants soulignent toutefois que les entreprises spécialisées affichent plusieurs mois d'attente. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans l'agence locale de l'énergie de Tours : une aide à l'installation de protections solaires. Le dispositif vise à répondre à une difficulté bien connue : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Plusieurs représentants soulignent toutefois que les entreprises spécialisées affichent plusieurs mois d'attente. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":34.432,"slotSeconds":50},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Répartir les permanences de le conseil gratuit en rénovation thermique entre deux lieux différents.","Avancer les horaires de le conseil gratuit en rénovation thermique en supprimant le relais du soir.","Répartir les permanences du conseil gratuit en rénovation thermique pour maintenir l’accueil continu.","Réserver les permanences de le conseil gratuit en rénovation thermique aux inscriptions du matin."],"correct":"C","explanation":"Le document permet de retenir « Répartir les permanences du conseil gratuit en rénovation thermique pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le conseil gratuit en rénovation thermique.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le conseil gratuit en rénovation thermique."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":26.2,"slotSeconds":42},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les visiteurs ayant déjà terminé leurs démarches dans l'agence locale de l'énergie de Tours.","Les visiteurs de l'agence locale de l'énergie de Tours qui peinent à accéder au service ordinaire.","Les personnes qui fréquentent régulièrement les ateliers de l'agence locale de l'énergie de Tours.","Les employés chargés d’accueillir et d’orienter les visiteurs de l'agence locale de l'énergie de Tours."],"correct":"B","explanation":"Le document permet de retenir « Les visiteurs de l'agence locale de l'énergie de Tours qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans l'agence locale de l'énergie de Tours. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans l'agence locale de l'énergie de Tours. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":32.27,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["La personne travaille à l’heure prévue pour une journée de la transition énergétique.","Elle souhaite déplacer une journée de la transition énergétique à cause d’un changement de salle.","Elle demande un autre horaire pour une journée de la transition énergétique afin d’accompagner un proche.","Elle ne peut se rendre à une journée de la transition énergétique à cause d’un retard de transport."],"correct":"A","explanation":"Le document permet de retenir « La personne travaille à l’heure prévue pour une journée de la transition énergétique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une journée de la transition énergétique. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une journée de la transition énergétique. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.212,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Répartir les participants de une journée de la transition énergétique selon leur expérience.","Réduire le groupe de une journée de la transition énergétique pour utiliser moins de matériel.","Adapter le nombre de places de une journée de la transition énergétique à la taille de la salle.","Le petit groupe permet d’échanger davantage pendant une journée de la transition énergétique."],"correct":"D","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant une journée de la transition énergétique ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une journée de la transition énergétique, des visites en petits groupes seront proposées dans l'agence locale de l'énergie de Tours. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une journée de la transition énergétique, des visites en petits groupes seront proposées dans l'agence locale de l'énergie de Tours. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.944,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués.","La visiteuse souhaite des précisions sur la performance réelle des matériaux après installation.","Elle cherche à connaître le prix définitif de sa participation au projet."],"correct":"C","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la performance réelle des matériaux après installation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la performance réelle des matériaux après installation. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la performance réelle des matériaux après installation. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.148,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Prévoir le matériel nécessaire selon les inscriptions à une journée de la transition énergétique.","Répartir les bénévoles d’une journée de la transition énergétique selon les créneaux où ils sont libres.","Définir les activités prioritaires selon le public attendu pour une journée de la transition énergétique.","Adapter les tâches des bénévoles aux compétences requises pour une journée de la transition énergétique."],"correct":"B","explanation":"Le document permet de retenir « Répartir les bénévoles d’une journée de la transition énergétique selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans l'agence locale de l'énergie de Tours, pour préparer une journée de la transition énergétique, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans l'agence locale de l'énergie de Tours, pour préparer une journée de la transition énergétique, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":37.715,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["La confiance née des rencontres entre des participants différents.","La meilleure organisation des activités obtenue grâce à une visite d'une maison isolée.","Les connaissances pratiques acquises au cours de une visite d'une maison isolée.","Les nouveaux contacts professionnels pris pendant une visite d'une maison isolée."],"correct":"A","explanation":"Le document permet de retenir « La confiance née des rencontres entre des participants différents ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à une visite d'une maison isolée. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à une visite d'une maison isolée. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.936,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Mettre en place des aides ciblées et des travaux adaptés à chaque bâtiment partout avant de mesurer les résultats.","Consulter les habitants sur des aides ciblées et des travaux adaptés à chaque bâtiment sans mener d’essai concret.","Expérimenter des aides ciblées et des travaux adaptés à chaque bâtiment mais ne publier aucun retour des participants.","Expérimenter des aides ciblées et des travaux adaptés à chaque bâtiment, recueillir les avis et publier un bilan."],"correct":"D","explanation":"Le document permet de retenir « Expérimenter des aides ciblées et des travaux adaptés à chaque bâtiment, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Climat et énergie ».\nNous avons discuté de des aides ciblées et des travaux adaptés à chaque bâtiment, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan.\nLes usagers craignent surtout la performance réelle des matériaux après installation. Une application immédiate, sans consultation, risquerait de perdre leur confiance.\nAlors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Climat et énergie »."},{"voice":"male","text":"Nous avons discuté de des aides ciblées et des travaux adaptés à chaque bâtiment, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan."},{"voice":"female","text":"Les usagers craignent surtout la performance réelle des matériaux après installation. Une application immédiate, sans consultation, risquerait de perdre leur confiance."},{"voice":"male","text":"Alors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":57.608,"slotSeconds":74},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le conseil gratuit en rénovation thermique comprend surtout des personnes en attente.","L’étude de le conseil gratuit en rénovation thermique s’appuie principalement sur les réponses des agents.","L’étude sur le conseil gratuit en rénovation thermique n’a presque pas touché ceux qui ont abandonné.","L’étude de le conseil gratuit en rénovation thermique donne peu de place aux nouveaux inscrits."],"correct":"C","explanation":"Le document permet de retenir « L’étude sur le conseil gratuit en rénovation thermique n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le conseil gratuit en rénovation thermique. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le conseil gratuit en rénovation thermique. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":54.214,"slotSeconds":71},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Concilier les nouvelles aides énergétiques avec les contraintes des ménages modestes.","Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement."],"correct":"B","explanation":"Le document permet de retenir « Concilier les nouvelles aides énergétiques avec les contraintes des ménages modestes ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans l'agence locale de l'énergie de Tours, une initiative propose des aides ciblées et des travaux adaptés à chaque bâtiment. Les responsables espèrent ainsi répondre à une difficulté bien connue : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes.\nNous soutenons l’objectif général, mais il faut prendre en compte la performance réelle des matériaux après installation. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que financer la maintenance et évaluer les économies sur plusieurs années. Pourtant, les entreprises spécialisées affichent plusieurs mois d'attente. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans l'agence locale de l'énergie de Tours, une initiative propose des aides ciblées et des travaux adaptés à chaque bâtiment. Les responsables espèrent ainsi répondre à une difficulté bien connue : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la performance réelle des matériaux après installation. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que financer la maintenance et évaluer les économies sur plusieurs années. Pourtant, les entreprises spécialisées affichent plusieurs mois d'attente. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":57.872,"slotSeconds":74},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les premiers effets d’une aide à l'installation de protections solaires doivent être vérifiés dans la durée.","Le projet de une aide à l'installation de protections solaires est annoncé mais n’a pas encore été lancé.","Les résultats de une aide à l'installation de protections solaires concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre une aide à l'installation de protections solaires dès la fin des premiers essais."],"correct":"A","explanation":"Le document permet de retenir « Les premiers effets d’une aide à l'installation de protections solaires doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une aide à l'installation de protections solaires. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les entreprises spécialisées affichent plusieurs mois d'attente. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une aide à l'installation de protections solaires. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les entreprises spécialisées affichent plusieurs mois d'attente. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.722,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Conserver les horaires de le conseil gratuit en rénovation thermique malgré les demandes du matin.","Réserver les créneaux matinaux de le conseil gratuit en rénovation thermique aux seuls abonnés.","Ouvrir le conseil gratuit en rénovation thermique plus tôt en supprimant les créneaux tardifs.","Adapter les horaires du conseil gratuit en rénovation thermique sans pénaliser les usagers du soir."],"correct":"D","explanation":"Le document permet de retenir « Adapter les horaires du conseil gratuit en rénovation thermique sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le conseil gratuit en rénovation thermique ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le conseil gratuit en rénovation thermique ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":42.768,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Tester un toit végétalisé sur un seul site avant de l’ouvrir à tous.","Préparer le budget de un toit végétalisé avant de calculer son entretien.","Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Adapter les équipements de un toit végétalisé après consultation des équipes."],"correct":"C","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un toit végétalisé a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la performance réelle des matériaux après installation est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un toit végétalisé a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la performance réelle des matériaux après installation est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":48.747,"slotSeconds":65},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut comparer les coûts de la réduction mesurée de la consommation et des températures intérieures ; l’autre mesure la fréquentation.","L’un veut suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures; l’autre demande aussi des témoignages.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres."],"correct":"B","explanation":"Le document permet de retenir « L’un veut suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures; l’autre demande aussi des témoignages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Climat et énergie ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Climat et énergie »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la réduction mesurée de la consommation et des températures intérieures et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":51.824,"slotSeconds":68},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Préserver l’histoire du lieu tout en lui donnant de nouvelles fonctions.","Conserver le bâtiment de une visite d'une maison isolée uniquement pour ses activités passées.","Moderniser les salles de une visite d'une maison isolée en effaçant les anciennes traces.","Rénover le lieu de une visite d'une maison isolée sans changer l’usage actuel des espaces."],"correct":"A","explanation":"Le document permet de retenir « Préserver l’histoire du lieu tout en lui donnant de nouvelles fonctions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule une visite d'une maison isolée, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule une visite d'une maison isolée, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.787,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Privilégier les chiffres globaux plutôt que les résultats détaillés.","Calculer une nouvelle moyenne globale avec davantage de données.","Comparer la moyenne d’un groupe à la moyenne de l’ensemble.","Examiner les différences entre groupes, cachées par une moyenne."],"correct":"D","explanation":"Le document permet de retenir « Examiner les différences entre groupes, cachées par une moyenne ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la réduction mesurée de la consommation et des températures intérieures. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la réduction mesurée de la consommation et des températures intérieures. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":56.583,"slotSeconds":73},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le conseil gratuit en rénovation thermique, annoncer une moyenne sans préciser les hypothèses retenues.","Pour le conseil gratuit en rénovation thermique, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le conseil gratuit en rénovation thermique, présenter les hypothèses et les incertitudes des prévisions.","Pour le conseil gratuit en rénovation thermique, publier un chiffre précis sans détailler ses limites."],"correct":"C","explanation":"Le document permet de retenir « Pour le conseil gratuit en rénovation thermique, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le conseil gratuit en rénovation thermique, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le conseil gratuit en rénovation thermique, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.658,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["Les chiffres de l'agence locale de l'énergie de Tours ne tiennent pas compte du prix des activités.","La hausse de fréquentation dans l'agence locale de l'énergie de Tours ne suffit pas à mesurer les résultats durables.","La hausse des visites à l'agence locale de l'énergie de Tours vient surtout des horaires étendus.","La fréquentation de l'agence locale de l'énergie de Tours varie trop selon les saisons."],"correct":"B","explanation":"Le document permet de retenir « La hausse de fréquentation dans l'agence locale de l'énergie de Tours ne suffit pas à mesurer les résultats durables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans l'agence locale de l'énergie de Tours, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une aide à l'installation de protections solaires. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la réduction mesurée de la consommation et des températures intérieures ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans l'agence locale de l'énergie de Tours, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une aide à l'installation de protections solaires. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la réduction mesurée de la consommation et des températures intérieures ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":49.534,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester le conseil gratuit en rénovation thermique par divers publics, avec une aide humaine conservée.","Évaluer le conseil gratuit en rénovation thermique auprès de tous puis supprimer l’accueil individuel.","Faire tester le conseil gratuit en rénovation thermique uniquement par les usagers réguliers.","Maintenir une aide humaine à le conseil gratuit en rénovation thermique pendant le seul lancement."],"correct":"A","explanation":"Le document permet de retenir « Faire tester le conseil gratuit en rénovation thermique par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans l'agence locale de l'énergie de Tours.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la performance réelle des matériaux après installation.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans l'agence locale de l'énergie de Tours."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la performance réelle des matériaux après installation."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.765,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["La performance du dispositif de le bâtiment démonstrateur exige un entretien régulier.","Les usages quotidiens du matériel de le bâtiment démonstrateur peuvent changer ses effets.","Les conditions de terrain de le bâtiment démonstrateur influencent les résultats observés.","Les résultats techniques du bâtiment démonstrateur suffiraient même si les usages réels diffèrent."],"correct":"D","explanation":"Le document permet de retenir « Les résultats techniques du bâtiment démonstrateur suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le bâtiment démonstrateur affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le bâtiment démonstrateur affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.011,"slotSeconds":67},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Répartir les rôles de une visite d'une maison isolée entre des participants désignés à l’avance.","Évaluer le lien créé à une visite d'une maison isolée uniquement par le nombre de présences.","Permettre une participation volontaire et réciproque à une visite d'une maison isolée.","Assurer une présence régulière aux séances de une visite d'une maison isolée sans échanger."],"correct":"C","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à une visite d'une maison isolée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de une visite d'une maison isolée réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la performance réelle des matériaux après installation. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de une visite d'une maison isolée réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la performance réelle des matériaux après installation. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.167,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits de le conseil gratuit en rénovation thermique sans consulter les archives disponibles.","La chercheuse confronte les témoignages sur le conseil gratuit en rénovation thermique aux dates et décisions vérifiables.","Conserver les récits de le conseil gratuit en rénovation thermique qui concordent avec la majorité.","Classer les témoignages de le conseil gratuit en rénovation thermique selon l’ancienneté de leurs auteurs."],"correct":"B","explanation":"Le document permet de retenir « La chercheuse confronte les témoignages sur le conseil gratuit en rénovation thermique aux dates et décisions vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le conseil gratuit en rénovation thermique, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le conseil gratuit en rénovation thermique, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":54.441,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès d’une aide à l'installation de protections solaires peut créer des difficultés aux usagers.","Le succès de une aide à l'installation de protections solaires réduit les demandes des services voisins.","La fréquentation de une aide à l'installation de protections solaires ralentit la promotion du dispositif.","La croissance de une aide à l'installation de protections solaires augmente le budget sans effet sur les usagers."],"correct":"A","explanation":"Le document permet de retenir « Le succès d’une aide à l'installation de protections solaires peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Climat et énergie ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une aide à l'installation de protections solaires peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la performance réelle des matériaux après installation. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Climat et énergie ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une aide à l'installation de protections solaires peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les pics de chaleur et le coût des rénovations touchent davantage les ménages modestes. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la performance réelle des matériaux après installation. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":64.662,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Obtenir des moyens durables mais ne plus mesurer la réduction mesurée de la consommation et des températures intérieures.","Étendre le service en privilégiant seulement les premiers résultats de la réduction mesurée de la consommation et des températures intérieures.","Suivre la réduction mesurée de la consommation et des températures intérieures en comptant sur les bénévoles actuels.","Assurer des moyens durables et suivre la réduction mesurée de la consommation et des températures intérieures sur la durée."],"correct":"D","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre la réduction mesurée de la consommation et des températures intérieures sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le conseil gratuit en rénovation thermique, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les entreprises spécialisées affichent plusieurs mois d'attente. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la réduction mesurée de la consommation et des températures intérieures. L’idée n’est pas d’abandonner l’ambition de départ : financer la maintenance et évaluer les économies sur plusieurs années. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le conseil gratuit en rénovation thermique, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les entreprises spécialisées affichent plusieurs mois d'attente. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la réduction mesurée de la consommation et des températures intérieures. L’idée n’est pas d’abandonner l’ambition de départ : financer la maintenance et évaluer les économies sur plusieurs années. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":66.514,"slotSeconds":83}]},{"id":"tcf-listening-11","version":"tcf-listening-2026-11-test11-v2","title":"TCF Listening · Test 11","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La scène représente une personne assise, occupée à consulter un petit télescope.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un petit télescope à une table. D. Elle court sur un terrain de sport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle transporte une grande valise. B. Elle répare le moteur d'une voiture. C. Elle consulte un petit télescope à une table. D. Elle court sur un terrain de sport."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.943,"slotSeconds":32},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Un homme présente une affiche liée à sciences et recherche.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il peint une façade extérieure. B. Il présente une affiche sur sciences et recherche à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il peint une façade extérieure. B. Il présente une affiche sur sciences et recherche à un groupe. C. Il prépare un repas dans la cuisine. D. Il prend le train avec deux sacs."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.609,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Deux interlocuteurs préparent une fête de la science autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes préparent une fête de la science autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes préparent une fête de la science autour d'une table. B. Deux personnes traversent une rivière. C. Une seule personne conduit un autobus. D. Trois personnes font de la randonnée."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.93,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'illustration montre une personne portant un sac devant le centre scientifique de Montpellier.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre scientifique de Montpellier.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme nage dans une piscine. B. Un homme répare un vélo. C. Des enfants jouent dans un jardin. D. Une femme porte un sac devant le centre scientifique de Montpellier."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.758,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient un atelier d'observation des étoiles ?\nA. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient un atelier d'observation des étoiles ?"},{"voice":"female","text":"A. Je suis rentré hier soir. B. La météo annonce de la pluie. C. Dans la salle du premier étage, juste après l'accueil. D. Oui, j'en ai acheté trois kilos."}],"audio":"q-05.mp3","audioSeconds":19.783,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un petit télescope pour participer à une fête de la science ?\nA. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un petit télescope pour participer à une fête de la science ?"},{"voice":"female","text":"A. La gare est en face de la pharmacie. B. Oui, prenez-le avec vous, il sera utile sur place. C. Nous arriverons seulement dimanche. D. Il a changé de travail."}],"audio":"q-06.mp3","audioSeconds":19.371,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour un atelier d'observation des étoiles ?\nA. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour un atelier d'observation des étoiles ?"},{"voice":"female","text":"A. Bien sûr, disons dix heures devant l'entrée. B. J'en ai acheté cinq bouteilles. C. Il n'est pas encore assez mûr. D. Ce vêtement doit sécher à plat."}],"audio":"q-07.mp3","audioSeconds":17.713,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une fête de la science. Est-ce possible ?\nA. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une fête de la science. Est-ce possible ?"},{"voice":"female","text":"A. Le parc est fermé en hiver. B. J'habite au troisième étage. C. Je préfère la couleur bleue. D. Oui, donnez-moi votre nom et nous chercherons un autre créneau."}],"audio":"q-08.mp3","audioSeconds":21.426,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées.","L'ouverture d'un laboratoire aux visiteurs le jeudi.","Un nouveau lieu d’accueil pour les visiteurs inscrits."],"correct":"C","explanation":"Le document permet de retenir « L'ouverture d'un laboratoire aux visiteurs le jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans le centre scientifique de Montpellier, à compter de lundi prochain, nous mettons en place l'ouverture d'un laboratoire aux visiteurs le jeudi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans le centre scientifique de Montpellier, à compter de lundi prochain, nous mettons en place l'ouverture d'un laboratoire aux visiteurs le jeudi. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":22.401,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour un atelier d'observation des étoiles est avancé d’une demi-heure.","La personne arrivera plus tard à un atelier d'observation des étoiles à cause d’une autre obligation.","Le rendez-vous pour un atelier d'observation des étoiles est reporté au lendemain.","Un autre créneau est proposé pour un atelier d'observation des étoiles en raison des transports."],"correct":"B","explanation":"Le document permet de retenir « La personne arrivera plus tard à un atelier d'observation des étoiles à cause d’une autre obligation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour un atelier d'observation des étoiles ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour un atelier d'observation des étoiles ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":26.943,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Remplir le formulaire d’inscription en ligne avant jeudi.","Envoyer le formulaire de une fête de la science par courriel avant vendredi.","Déposer sa demande pour une fête de la science à l’accueil le jour même.","Réserver sa place pour une fête de la science par téléphone avant jeudi."],"correct":"A","explanation":"Le document permet de retenir « Remplir le formulaire d’inscription en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Sciences et recherche » aura lieu dans le centre scientifique de Montpellier. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Sciences et recherche » aura lieu dans le centre scientifique de Montpellier. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.002,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Demander une confirmation écrite après la fin de un atelier d'observation des étoiles.","Présenter une pièce d’identité à l’accueil pour accéder à un atelier d'observation des étoiles.","Remplir un nouveau formulaire d’inscription pour participer à un atelier d'observation des étoiles.","Présenter le message de confirmation pour un atelier d'observation des étoiles à l’accueil."],"correct":"D","explanation":"Le document permet de retenir « Présenter le message de confirmation pour un atelier d'observation des étoiles à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à un atelier d'observation des étoiles, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à un atelier d'observation des étoiles, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.094,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de un atelier d'observation des étoiles commence une heure plus tôt que prévu.","La séance de un atelier d'observation des étoiles est reportée au lendemain à la même heure.","La séance prévue pour un atelier d'observation des étoiles commence une heure plus tard.","La séance de un atelier d'observation des étoiles change de salle mais garde le même horaire."],"correct":"C","explanation":"Le document permet de retenir « La séance prévue pour un atelier d'observation des étoiles commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour un atelier d'observation des étoiles. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour un atelier d'observation des étoiles. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.833,"slotSeconds":38},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Reporter un atelier d'observation des étoiles jusqu’à ce que le matériel soit disponible.","Conserver un atelier d'observation des étoiles et envoyer ensuite la démonstration manquante.","Garder un atelier d'observation des étoiles mais renoncer à fournir la démonstration prévue.","Maintenir un atelier d'observation des étoiles avec une démonstration réalisée sans le matériel."],"correct":"B","explanation":"Le document permet de retenir « Conserver un atelier d'observation des étoiles et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à un atelier d'observation des étoiles n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à un atelier d'observation des étoiles n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.647,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans le centre scientifique de Montpellier, l’initiative est désormais réservée aux habitués.","Dans le centre scientifique de Montpellier, la mesure a été suspendue faute de participants.","Dans le centre scientifique de Montpellier, les difficultés ont été réglées avant le lancement."],"correct":"A","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre scientifique de Montpellier : l'ouverture d'un laboratoire aux visiteurs le jeudi. Le dispositif vise à répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Plusieurs représentants soulignent toutefois que certaines observations restent impossibles par mauvais temps. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans le centre scientifique de Montpellier : l'ouverture d'un laboratoire aux visiteurs le jeudi. Le dispositif vise à répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Plusieurs représentants soulignent toutefois que certaines observations restent impossibles par mauvais temps. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":33.582,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Avancer les horaires de le programme de sciences participatives en supprimant le relais du soir.","Réserver les permanences de le programme de sciences participatives aux inscriptions du matin.","Répartir les permanences de le programme de sciences participatives entre deux lieux différents.","Répartir les permanences du programme de sciences participatives pour maintenir l’accueil continu."],"correct":"D","explanation":"Le document permet de retenir « Répartir les permanences du programme de sciences participatives pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de sciences participatives.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de sciences participatives."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.527,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui fréquentent régulièrement les ateliers de le centre scientifique de Montpellier.","Les employés chargés d’accueillir et d’orienter les visiteurs de le centre scientifique de Montpellier.","Les visiteurs du centre scientifique de Montpellier qui peinent à accéder au service ordinaire.","Les visiteurs ayant déjà terminé leurs démarches dans le centre scientifique de Montpellier."],"correct":"C","explanation":"Le document permet de retenir « Les visiteurs du centre scientifique de Montpellier qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans le centre scientifique de Montpellier. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans le centre scientifique de Montpellier. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":31.643,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle demande un autre horaire pour une fête de la science afin d’accompagner un proche.","Elle travaille encore vendredi à seize heures, au moment d’une fête de la science.","Elle ne peut se rendre à une fête de la science à cause d’un retard de transport.","Elle souhaite déplacer une fête de la science à cause d’un changement de salle."],"correct":"B","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une fête de la science ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une fête de la science. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une fête de la science. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.043,"slotSeconds":47},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Permettre à chaque participant de poser ses questions et d’échanger.","Réduire le groupe de une fête de la science pour utiliser moins de matériel.","Adapter le nombre de places de une fête de la science à la taille de la salle.","Répartir les participants de une fête de la science selon leur expérience."],"correct":"A","explanation":"Le document permet de retenir « Permettre à chaque participant de poser ses questions et d’échanger ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une fête de la science, des visites en petits groupes seront proposées dans le centre scientifique de Montpellier. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une fête de la science, des visites en petits groupes seront proposées dans le centre scientifique de Montpellier. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":23.818,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet.","La visiteuse souhaite des précisions sur la qualité des données issues d'observations irrégulières."],"correct":"D","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur la qualité des données issues d'observations irrégulières ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte la qualité des données issues d'observations irrégulières. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte la qualité des données issues d'observations irrégulières. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.939,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Définir les activités prioritaires selon le public attendu pour une fête de la science.","Adapter les tâches des bénévoles aux compétences requises pour une fête de la science.","Répartir les bénévoles d’une fête de la science selon les créneaux où ils sont libres.","Prévoir le matériel nécessaire selon les inscriptions à une fête de la science."],"correct":"C","explanation":"Le document permet de retenir « Répartir les bénévoles d’une fête de la science selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans le centre scientifique de Montpellier, pour préparer une fête de la science, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans le centre scientifique de Montpellier, pour préparer une fête de la science, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.426,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les connaissances pratiques acquises au cours de un atelier d'observation des étoiles.","Les relations de confiance établies pendant un atelier d'observation des étoiles avec les participants.","Les nouveaux contacts professionnels pris pendant un atelier d'observation des étoiles.","La meilleure organisation des activités obtenue grâce à un atelier d'observation des étoiles."],"correct":"B","explanation":"Le document permet de retenir « Les relations de confiance établies pendant un atelier d'observation des étoiles avec les participants ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à un atelier d'observation des étoiles. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à un atelier d'observation des étoiles. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":47.346,"slotSeconds":64},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Tester des explications publiques des méthodes et des données, consulter les usagers puis publier un bilan.","Consulter les habitants sur des explications publiques des méthodes et des données sans mener d’essai concret.","Expérimenter des explications publiques des méthodes et des données mais ne publier aucun retour des participants.","Mettre en place des explications publiques des méthodes et des données partout avant de mesurer les résultats."],"correct":"A","explanation":"Le document permet de retenir « Tester des explications publiques des méthodes et des données, consulter les usagers puis publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Sciences et recherche ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des explications publiques des méthodes et des données.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Sciences et recherche »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des explications publiques des méthodes et des données."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":54.032,"slotSeconds":71},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le programme de sciences participatives s’appuie principalement sur les réponses des agents.","L’étude de le programme de sciences participatives donne peu de place aux nouveaux inscrits.","L’étude de le programme de sciences participatives comprend surtout des personnes en attente.","L’étude sur le programme de sciences participatives n’a presque pas touché ceux qui ont abandonné."],"correct":"D","explanation":"Le document permet de retenir « L’étude sur le programme de sciences participatives n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le programme de sciences participatives. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le programme de sciences participatives. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.767,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement.","Concilier les activités scientifiques avec les limites des données recueillies.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours."],"correct":"C","explanation":"Le document permet de retenir « Concilier les activités scientifiques avec les limites des données recueillies ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans le centre scientifique de Montpellier, une initiative propose des explications publiques des méthodes et des données. Les responsables espèrent ainsi répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude.\nNous soutenons l’objectif général, mais il faut prendre en compte la qualité des données issues d'observations irrégulières. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que maintenir le suivi scientifique et rendre les résultats compréhensibles. Pourtant, certaines observations restent impossibles par mauvais temps. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans le centre scientifique de Montpellier, une initiative propose des explications publiques des méthodes et des données. Les responsables espèrent ainsi répondre à une difficulté bien connue : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte la qualité des données issues d'observations irrégulières. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que maintenir le suivi scientifique et rendre les résultats compréhensibles. Pourtant, certaines observations restent impossibles par mauvais temps. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":56.327,"slotSeconds":73},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les résultats de l'ouverture d'un laboratoire aux visiteurs le jeudi concernent uniquement les coûts de gestion.","La nouvelle mesure, l'ouverture d'un laboratoire aux visiteurs le jeudi, doit encore être évaluée sur la durée.","L’équipe souhaite interrompre l'ouverture d'un laboratoire aux visiteurs le jeudi dès la fin des premiers essais.","Le projet de l'ouverture d'un laboratoire aux visiteurs le jeudi est annoncé mais n’a pas encore été lancé."],"correct":"B","explanation":"Le document permet de retenir « La nouvelle mesure, l'ouverture d'un laboratoire aux visiteurs le jeudi, doit encore être évaluée sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé l'ouverture d'un laboratoire aux visiteurs le jeudi. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines observations restent impossibles par mauvais temps. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la reproductibilité des observations recueillies. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé l'ouverture d'un laboratoire aux visiteurs le jeudi. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines observations restent impossibles par mauvais temps. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la reproductibilité des observations recueillies. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.658,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Adapter les horaires du programme de sciences participatives sans pénaliser les usagers du soir.","Réserver les créneaux matinaux de le programme de sciences participatives aux seuls abonnés.","Ouvrir le programme de sciences participatives plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de le programme de sciences participatives malgré les demandes du matin."],"correct":"A","explanation":"Le document permet de retenir « Adapter les horaires du programme de sciences participatives sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le programme de sciences participatives ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le programme de sciences participatives ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.468,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Préparer le budget de une station de mesures partagée avant de calculer son entretien.","Adapter les équipements de une station de mesures partagée après consultation des équipes.","Tester une station de mesures partagée sur un seul site avant de l’ouvrir à tous.","Concevoir une station de mesures partagée avant de comprendre les besoins réels des utilisateurs."],"correct":"D","explanation":"Le document permet de retenir « Concevoir une station de mesures partagée avant de comprendre les besoins réels des utilisateurs ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de une station de mesures partagée a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la qualité des données issues d'observations irrégulières est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de une station de mesures partagée a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de la qualité des données issues d'observations irrégulières est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.21,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut mesurer la reproductibilité des observations recueillies ; l’autre demande des récits.","L’un veut comparer les coûts de la reproductibilité des observations recueillies ; l’autre mesure la fréquentation."],"correct":"C","explanation":"Le document permet de retenir « L’un veut mesurer la reproductibilité des observations recueillies ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Sciences et recherche ».\nSans chiffres comparables, impossible de dire si l'ouverture d'un laboratoire aux visiteurs le jeudi apporte un bénéfice mesurable. Nous devons étudier la reproductibilité des observations recueillies.\nLes chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Sciences et recherche »."},{"voice":"male","text":"Sans chiffres comparables, impossible de dire si l'ouverture d'un laboratoire aux visiteurs le jeudi apporte un bénéfice mesurable. Nous devons étudier la reproductibilité des observations recueillies."},{"voice":"female","text":"Les chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":48.481,"slotSeconds":65},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Moderniser les salles de un atelier d'observation des étoiles en effaçant les anciennes traces.","Conserver l’identité du lieu accueillant un atelier d'observation des étoiles tout en permettant de nouveaux usages.","Rénover le lieu de un atelier d'observation des étoiles sans changer l’usage actuel des espaces.","Conserver le bâtiment de un atelier d'observation des étoiles uniquement pour ses activités passées."],"correct":"B","explanation":"Le document permet de retenir « Conserver l’identité du lieu accueillant un atelier d'observation des étoiles tout en permettant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule un atelier d'observation des étoiles, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule un atelier d'observation des étoiles, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":52.53,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Confronter les prévisions d’un modèle aux observations réelles.","Comparer les prévisions de plusieurs modèles entre elles.","Vérifier seulement si le modèle retrouve les données de départ.","Réviser les hypothèses avant toute observation de terrain."],"correct":"A","explanation":"Le document permet de retenir « Confronter les prévisions d’un modèle aux observations réelles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la reproductibilité des observations recueillies. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la reproductibilité des observations recueillies. Une simulation décrit ce qui devrait se produire si certaines hypothèses se réalisent. Or, sur le terrain, les comportements, les conditions matérielles et les ressources peuvent différer de ces hypothèses. Il est donc nécessaire de comparer régulièrement les prévisions aux observations et de réviser le modèle lorsque les écarts deviennent significatifs. Cette prudence est particulièrement importante ici : les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":57.916,"slotSeconds":74},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le programme de sciences participatives, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le programme de sciences participatives, publier un chiffre précis sans détailler ses limites.","Pour le programme de sciences participatives, annoncer une moyenne sans préciser les hypothèses retenues.","Pour le programme de sciences participatives, présenter les hypothèses et les incertitudes des prévisions."],"correct":"D","explanation":"Le document permet de retenir « Pour le programme de sciences participatives, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le programme de sciences participatives, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le programme de sciences participatives, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.24,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites à le centre scientifique de Montpellier vient surtout des horaires étendus.","La fréquentation de le centre scientifique de Montpellier varie trop selon les saisons.","La hausse de fréquentation à le centre scientifique de Montpellier ne démontre pas à elle seule un bénéfice durable.","Les chiffres de le centre scientifique de Montpellier ne tiennent pas compte du prix des activités."],"correct":"C","explanation":"Le document permet de retenir « La hausse de fréquentation à le centre scientifique de Montpellier ne démontre pas à elle seule un bénéfice durable ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans le centre scientifique de Montpellier, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : l'ouverture d'un laboratoire aux visiteurs le jeudi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la reproductibilité des observations recueillies ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans le centre scientifique de Montpellier, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : l'ouverture d'un laboratoire aux visiteurs le jeudi. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la reproductibilité des observations recueillies ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.21,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Faire tester le programme de sciences uniquement par les usagers réguliers.","Faire tester le programme de sciences par divers publics, avec une aide humaine conservée.","Maintenir une aide humaine à le programme de sciences pendant le seul lancement.","Évaluer le programme de sciences auprès de tous puis supprimer l’accueil individuel."],"correct":"B","explanation":"Le document permet de retenir « Faire tester le programme de sciences par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans le centre scientifique de Montpellier.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la qualité des données issues d'observations irrégulières.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans le centre scientifique de Montpellier."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : la qualité des données issues d'observations irrégulières."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":52.871,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les résultats techniques de l'observatoire de la colline suffiraient même si les usages réels diffèrent.","Les usages quotidiens du matériel de l'observatoire de la colline peuvent changer ses effets.","Les conditions de terrain de l'observatoire de la colline influencent les résultats observés.","La performance du dispositif de l'observatoire de la colline exige un entretien régulier."],"correct":"A","explanation":"Le document permet de retenir « Les résultats techniques de l'observatoire de la colline suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans l'observatoire de la colline affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans l'observatoire de la colline affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":51.596,"slotSeconds":69},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Évaluer le lien créé à un atelier d'observation des étoiles uniquement par le nombre de présences.","Assurer une présence régulière aux séances de un atelier d'observation des étoiles sans échanger.","Répartir les rôles de un atelier d'observation des étoiles entre des participants désignés à l’avance.","Permettre une participation volontaire et réciproque à un atelier d'observation des étoiles."],"correct":"D","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à un atelier d'observation des étoiles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de un atelier d'observation des étoiles réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la qualité des données issues d'observations irrégulières. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de un atelier d'observation des étoiles réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : la qualité des données issues d'observations irrégulières. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.968,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Conserver les récits de le programme de sciences participatives qui concordent avec la majorité.","Classer les témoignages de le programme de sciences participatives selon l’ancienneté de leurs auteurs.","Comparer les récits concernant le programme de sciences participatives aux faits vérifiables.","Comparer les récits de le programme de sciences participatives sans consulter les archives disponibles."],"correct":"C","explanation":"Le document permet de retenir « Comparer les récits concernant le programme de sciences participatives aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le programme de sciences participatives, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le programme de sciences participatives, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.058,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La fréquentation de l'ouverture d'un laboratoire aux visiteurs le jeudi ralentit la promotion du dispositif.","Une initiative comme l'ouverture d'un laboratoire aux visiteurs le jeudi peut devenir victime de son succès et fragiliser les usagers.","La croissance de l'ouverture d'un laboratoire aux visiteurs le jeudi augmente le budget sans effet sur les usagers.","Le succès de l'ouverture d'un laboratoire aux visiteurs le jeudi réduit les demandes des services voisins."],"correct":"B","explanation":"Le document permet de retenir « Une initiative comme l'ouverture d'un laboratoire aux visiteurs le jeudi peut devenir victime de son succès et fragiliser les usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Sciences et recherche ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, l'ouverture d'un laboratoire aux visiteurs le jeudi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la qualité des données issues d'observations irrégulières. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Sciences et recherche ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, l'ouverture d'un laboratoire aux visiteurs le jeudi peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les résultats expérimentaux sont parfois présentés sans leurs marges d'incertitude. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner la qualité des données issues d'observations irrégulières. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":64.906,"slotSeconds":82},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Stabiliser les moyens et suivre la reproductibilité des observations recueillies dans la durée.","Étendre le service en privilégiant seulement les premiers résultats de la reproductibilité des observations recueillies.","Suivre la reproductibilité des observations recueillies en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer la reproductibilité des observations recueillies."],"correct":"A","explanation":"Le document permet de retenir « Stabiliser les moyens et suivre la reproductibilité des observations recueillies dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le programme de sciences participatives, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines observations restent impossibles par mauvais temps. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la reproductibilité des observations recueillies. L’idée n’est pas d’abandonner l’ambition de départ : maintenir le suivi scientifique et rendre les résultats compréhensibles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le programme de sciences participatives, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines observations restent impossibles par mauvais temps. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la reproductibilité des observations recueillies. L’idée n’est pas d’abandonner l’ambition de départ : maintenir le suivi scientifique et rendre les résultats compréhensibles. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.845,"slotSeconds":81}]},{"id":"tcf-listening-12","version":"tcf-listening-2026-11-test12-v2","title":"TCF Listening · Test 12","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La scène représente une personne assise, occupée à consulter une carte des itinéraires.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte une carte des itinéraires à une table.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle court sur un terrain de sport. B. Elle transporte une grande valise. C. Elle répare le moteur d'une voiture. D. Elle consulte une carte des itinéraires à une table."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.922,"slotSeconds":33},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Un homme présente une affiche liée à voyages et tourisme.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur voyages et tourisme à un groupe. D. Il prépare un repas dans la cuisine.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prend le train avec deux sacs. B. Il peint une façade extérieure. C. Il présente une affiche sur voyages et tourisme à un groupe. D. Il prépare un repas dans la cuisine."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.839,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Deux interlocuteurs préparent une rencontre des guides locaux autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Trois personnes font de la randonnée. B. Deux personnes préparent une rencontre des guides locaux autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Trois personnes font de la randonnée. B. Deux personnes préparent une rencontre des guides locaux autour d'une table. C. Deux personnes traversent une rivière. D. Une seule personne conduit un autobus."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.162,"slotSeconds":35},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'illustration montre une personne portant un sac devant l'office du tourisme de Chambéry.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Une femme porte un sac devant l'office du tourisme de Chambéry. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Une femme porte un sac devant l'office du tourisme de Chambéry. B. Une femme nage dans une piscine. C. Un homme répare un vélo. D. Des enfants jouent dans un jardin."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.106,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse précise le point de départ de l'activité.","transcript":"Question 5.\nExcusez-moi, où commence une promenade commentée du vieux centre ?\nA. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Le point de départ est devant l’accueil.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où commence une promenade commentée du vieux centre ?"},{"voice":"female","text":"A. Oui, j'en ai acheté trois kilos. B. Je suis rentré hier soir. C. La météo annonce de la pluie. D. Le point de départ est devant l’accueil."}],"audio":"q-05.mp3","audioSeconds":18.106,"slotSeconds":34},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter une carte des itinéraires pour participer à une rencontre des guides locaux ?\nA. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter une carte des itinéraires pour participer à une rencontre des guides locaux ?"},{"voice":"female","text":"A. Il a changé de travail. B. La gare est en face de la pharmacie. C. Oui, prenez-le avec vous, il sera utile sur place. D. Nous arriverons seulement dimanche."}],"audio":"q-06.mp3","audioSeconds":20.474,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour une promenade commentée du vieux centre ?\nA. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour une promenade commentée du vieux centre ?"},{"voice":"female","text":"A. Ce vêtement doit sécher à plat. B. Bien sûr, disons dix heures devant l'entrée. C. J'en ai acheté cinq bouteilles. D. Il n'est pas encore assez mûr."}],"audio":"q-07.mp3","audioSeconds":17.299,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une rencontre des guides locaux. Est-ce possible ?\nA. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une rencontre des guides locaux. Est-ce possible ?"},{"voice":"female","text":"A. Oui, donnez-moi votre nom et nous chercherons un autre créneau. B. Le parc est fermé en hiver. C. J'habite au troisième étage. D. Je préfère la couleur bleue."}],"audio":"q-08.mp3","audioSeconds":21.37,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles.","une réservation obligatoire pour les randonnées du dimanche"],"correct":"D","explanation":"Le document permet de retenir « une réservation obligatoire pour les randonnées du dimanche ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans l'office du tourisme de Chambéry, à compter de lundi prochain, nous mettons en place une réservation obligatoire pour les randonnées du dimanche. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans l'office du tourisme de Chambéry, à compter de lundi prochain, nous mettons en place une réservation obligatoire pour les randonnées du dimanche. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":22.959,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous pour une promenade commentée du vieux centre est reporté au lendemain.","Un autre créneau est proposé pour une promenade commentée du vieux centre en raison des transports.","Le rendez-vous d’une promenade commentée du vieux centre est repoussé à cause d’une réunion prolongée.","Le rendez-vous pour une promenade commentée du vieux centre est avancé d’une demi-heure."],"correct":"C","explanation":"Le document permet de retenir « Le rendez-vous d’une promenade commentée du vieux centre est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour une promenade commentée du vieux centre ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour une promenade commentée du vieux centre ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.088,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Déposer sa demande pour une rencontre des guides locaux à l’accueil le jour même.","Remplir en ligne le formulaire d’inscription pour une rencontre des guides locaux avant jeudi.","Réserver sa place pour une rencontre des guides locaux par téléphone avant jeudi.","Envoyer le formulaire de une rencontre des guides locaux par courriel avant vendredi."],"correct":"B","explanation":"Le document permet de retenir « Remplir en ligne le formulaire d’inscription pour une rencontre des guides locaux avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Voyages et tourisme » aura lieu dans l'office du tourisme de Chambéry. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Voyages et tourisme » aura lieu dans l'office du tourisme de Chambéry. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.723,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Montrer le courriel de confirmation à l’accueil pour retrouver son inscription.","Présenter une pièce d’identité à l’accueil pour accéder à une promenade commentée du vieux centre.","Remplir un nouveau formulaire d’inscription pour participer à une promenade commentée du vieux centre.","Demander une confirmation écrite après la fin de une promenade commentée du vieux centre."],"correct":"A","explanation":"Le document permet de retenir « Montrer le courriel de confirmation à l’accueil pour retrouver son inscription ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à une promenade commentée du vieux centre, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à une promenade commentée du vieux centre, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.908,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de une promenade commentée du vieux centre est reportée au lendemain à la même heure.","La séance de une promenade commentée du vieux centre change de salle mais garde le même horaire.","La séance de une promenade commentée du vieux centre commence une heure plus tôt que prévu.","La séance prévue pour une promenade commentée du vieux centre commence une heure plus tard."],"correct":"D","explanation":"Le document permet de retenir « La séance prévue pour une promenade commentée du vieux centre commence une heure plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour une promenade commentée du vieux centre. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour une promenade commentée du vieux centre. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.272,"slotSeconds":40},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Garder une promenade commentée du vieux centre mais renoncer à fournir la démonstration prévue.","Maintenir une promenade commentée du vieux centre avec une démonstration réalisée sans le matériel.","Conserver une promenade commentée du vieux centre et envoyer ensuite la démonstration manquante.","Reporter une promenade commentée du vieux centre jusqu’à ce que le matériel soit disponible."],"correct":"C","explanation":"Le document permet de retenir « Conserver une promenade commentée du vieux centre et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à une promenade commentée du vieux centre n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à une promenade commentée du vieux centre n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":29.863,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans l'office du tourisme de Chambéry, la mesure a été suspendue faute de participants.","La mesure présentée à l'office du tourisme de Chambéry répond au besoin sans lever toutes les difficultés.","Dans l'office du tourisme de Chambéry, les difficultés ont été réglées avant le lancement.","Dans l'office du tourisme de Chambéry, l’initiative est désormais réservée aux habitués."],"correct":"B","explanation":"Le document permet de retenir « La mesure présentée à l'office du tourisme de Chambéry répond au besoin sans lever toutes les difficultés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans l'office du tourisme de Chambéry : une réservation obligatoire pour les randonnées du dimanche. Le dispositif vise à répondre à une difficulté bien connue : la fréquentation saisonnière fragilise les chemins et dérange les riverains. Plusieurs représentants soulignent toutefois que les navettes sont complètes lors des jours fériés. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans l'office du tourisme de Chambéry : une réservation obligatoire pour les randonnées du dimanche. Le dispositif vise à répondre à une difficulté bien connue : la fréquentation saisonnière fragilise les chemins et dérange les riverains. Plusieurs représentants soulignent toutefois que les navettes sont complètes lors des jours fériés. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":32.27,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Maintenir un accueil sans interruption malgré les changements de service.","Réserver les permanences de la navette vers les sentiers aux inscriptions du matin.","Répartir les permanences de la navette vers les sentiers entre deux lieux différents.","Avancer les horaires de la navette vers les sentiers en supprimant le relais du soir."],"correct":"A","explanation":"Le document permet de retenir « Maintenir un accueil sans interruption malgré les changements de service ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la navette vers les sentiers.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour la navette vers les sentiers."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":24.668,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les employés chargés d’accueillir et d’orienter les visiteurs de l'office du tourisme de Chambéry.","Les visiteurs ayant déjà terminé leurs démarches dans l'office du tourisme de Chambéry.","Les personnes qui fréquentent régulièrement les ateliers de l'office du tourisme de Chambéry.","Les visiteurs de l'office du tourisme de Chambéry qui peinent à accéder au service ordinaire."],"correct":"D","explanation":"Le document permet de retenir « Les visiteurs de l'office du tourisme de Chambéry qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans l'office du tourisme de Chambéry. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : la fréquentation saisonnière fragilise les chemins et dérange les riverains. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans l'office du tourisme de Chambéry. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : la fréquentation saisonnière fragilise les chemins et dérange les riverains. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":31.655,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle ne peut se rendre à une rencontre des guides locaux à cause d’un retard de transport.","Elle souhaite déplacer une rencontre des guides locaux à cause d’un changement de salle.","Elle travaille encore vendredi à seize heures, au moment d’une rencontre des guides locaux.","Elle demande un autre horaire pour une rencontre des guides locaux afin d’accompagner un proche."],"correct":"C","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’une rencontre des guides locaux ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une rencontre des guides locaux. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une rencontre des guides locaux. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.718,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Adapter le nombre de places de une rencontre des guides locaux à la taille de la salle.","Limiter le groupe pendant une rencontre des guides locaux afin que chacun puisse poser des questions.","Répartir les participants de une rencontre des guides locaux selon leur expérience.","Réduire le groupe de une rencontre des guides locaux pour utiliser moins de matériel."],"correct":"B","explanation":"Le document permet de retenir « Limiter le groupe pendant une rencontre des guides locaux afin que chacun puisse poser des questions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une rencontre des guides locaux, des visites en petits groupes seront proposées dans l'office du tourisme de Chambéry. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une rencontre des guides locaux, des visites en petits groupes seront proposées dans l'office du tourisme de Chambéry. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.213,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["La visiteuse souhaite des précisions sur l'accès aux sites sans voiture particulière.","Elle cherche à connaître le prix définitif de sa participation au projet.","Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle veut savoir comment les horaires des séances seront communiqués."],"correct":"A","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur l'accès aux sites sans voiture particulière ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte l'accès aux sites sans voiture particulière. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte l'accès aux sites sans voiture particulière. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.498,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Adapter les tâches des bénévoles aux compétences requises pour une rencontre des guides locaux.","Prévoir le matériel nécessaire selon les inscriptions à une rencontre des guides locaux.","Définir les activités prioritaires selon le public attendu pour une rencontre des guides locaux.","Répartir les bénévoles d’une rencontre des guides locaux selon les créneaux où ils sont libres."],"correct":"D","explanation":"Le document permet de retenir « Répartir les bénévoles d’une rencontre des guides locaux selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans l'office du tourisme de Chambéry, pour préparer une rencontre des guides locaux, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans l'office du tourisme de Chambéry, pour préparer une rencontre des guides locaux, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.682,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les nouveaux contacts professionnels pris pendant une promenade commentée du vieux centre.","La meilleure organisation des activités obtenue grâce à une promenade commentée du vieux centre.","Les relations de confiance créées autour d’une promenade commentée du vieux centre.","Les connaissances pratiques acquises au cours de une promenade commentée du vieux centre."],"correct":"C","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’une promenade commentée du vieux centre ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à une promenade commentée du vieux centre. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que la fréquentation saisonnière fragilise les chemins et dérange les riverains. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à une promenade commentée du vieux centre. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que la fréquentation saisonnière fragilise les chemins et dérange les riverains. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.769,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Expérimenter une répartition des visites et des transports collectifs mais ne publier aucun retour des participants.","Expérimenter une répartition des visites et des transports collectifs, recueillir les avis et publier un bilan.","Mettre en place une répartition des visites et des transports collectifs partout avant de mesurer les résultats.","Consulter les habitants sur une répartition des visites et des transports collectifs sans mener d’essai concret."],"correct":"B","explanation":"Le document permet de retenir « Expérimenter une répartition des visites et des transports collectifs, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Voyages et tourisme ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré une répartition des visites et des transports collectifs.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : la fréquentation saisonnière fragilise les chemins et dérange les riverains.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Voyages et tourisme »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré une répartition des visites et des transports collectifs."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : la fréquentation saisonnière fragilise les chemins et dérange les riverains."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":54.322,"slotSeconds":71},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["Les usagers qui ont abandonné la navette vers les sentiers sont peu représentés.","L’étude de la navette vers les sentiers donne peu de place aux nouveaux inscrits.","L’étude de la navette vers les sentiers comprend surtout des personnes en attente.","L’étude de la navette vers les sentiers s’appuie principalement sur les réponses des agents."],"correct":"A","explanation":"Le document permet de retenir « Les usagers qui ont abandonné la navette vers les sentiers sont peu représentés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant la navette vers les sentiers. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car la fréquentation saisonnière fragilise les chemins et dérange les riverains. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant la navette vers les sentiers. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car la fréquentation saisonnière fragilise les chemins et dérange les riverains. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":52.124,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Concilier les visites touristiques avec les besoins des résidents près des sentiers."],"correct":"D","explanation":"Le document permet de retenir « Concilier les visites touristiques avec les besoins des résidents près des sentiers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans l'office du tourisme de Chambéry, une initiative propose une répartition des visites et des transports collectifs. Les responsables espèrent ainsi répondre à une difficulté bien connue : la fréquentation saisonnière fragilise les chemins et dérange les riverains.\nNous soutenons l’objectif général, mais il faut prendre en compte l'accès aux sites sans voiture particulière. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que protéger les paysages et conserver des emplois locaux hors saison. Pourtant, les navettes sont complètes lors des jours fériés. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans l'office du tourisme de Chambéry, une initiative propose une répartition des visites et des transports collectifs. Les responsables espèrent ainsi répondre à une difficulté bien connue : la fréquentation saisonnière fragilise les chemins et dérange les riverains."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte l'accès aux sites sans voiture particulière. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que protéger les paysages et conserver des emplois locaux hors saison. Pourtant, les navettes sont complètes lors des jours fériés. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":55.491,"slotSeconds":72},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["L’équipe souhaite interrompre une réservation obligatoire pour les randonnées du dimanche dès la fin des premiers essais.","Le projet de une réservation obligatoire pour les randonnées du dimanche est annoncé mais n’a pas encore été lancé.","Les premiers effets d’une réservation obligatoire pour les randonnées du dimanche doivent être vérifiés dans la durée.","Les résultats de une réservation obligatoire pour les randonnées du dimanche concernent uniquement les coûts de gestion."],"correct":"C","explanation":"Le document permet de retenir « Les premiers effets d’une réservation obligatoire pour les randonnées du dimanche doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une réservation obligatoire pour les randonnées du dimanche. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les navettes sont complètes lors des jours fériés. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la satisfaction des visiteurs et des résidents tout au long de l'année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une réservation obligatoire pour les randonnées du dimanche. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Les navettes sont complètes lors des jours fériés. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la satisfaction des visiteurs et des résidents tout au long de l'année. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":49.948,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Ouvrir la navette vers les sentiers plus tôt en supprimant les créneaux tardifs.","Réorganiser les horaires de la navette vers les sentiers sans supprimer les créneaux du soir.","Conserver les horaires de la navette vers les sentiers malgré les demandes du matin.","Réserver les créneaux matinaux de la navette vers les sentiers aux seuls abonnés."],"correct":"B","explanation":"Le document permet de retenir « Réorganiser les horaires de la navette vers les sentiers sans supprimer les créneaux du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que la navette vers les sentiers ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que la navette vers les sentiers ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":40.528,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Adapter les équipements de un parcours de découverte adapté après consultation des équipes.","Tester un parcours de découverte adapté sur un seul site avant de l’ouvrir à tous.","Préparer le budget de un parcours de découverte adapté avant de calculer son entretien."],"correct":"A","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un parcours de découverte adapté a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'accès aux sites sans voiture particulière est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un parcours de découverte adapté a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'accès aux sites sans voiture particulière est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":48.983,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de la satisfaction des visiteurs et des résidents tout au long de l'année ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut mesurer la satisfaction des visiteurs et des résidents tout au long de l'année ; l’autre demande des récits."],"correct":"D","explanation":"Le document permet de retenir « L’un veut mesurer la satisfaction des visiteurs et des résidents tout au long de l'année ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Voyages et tourisme ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la satisfaction des visiteurs et des résidents tout au long de l'année et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. La fréquentation saisonnière fragilise les chemins et dérange les riverains. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Voyages et tourisme »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la satisfaction des visiteurs et des résidents tout au long de l'année et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. La fréquentation saisonnière fragilise les chemins et dérange les riverains. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":52.012,"slotSeconds":70},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Rénover le lieu de une promenade commentée du vieux centre sans changer l’usage actuel des espaces.","Conserver le bâtiment de une promenade commentée du vieux centre uniquement pour ses activités passées.","Préserver l’histoire du lieu d’une promenade commentée du vieux centre tout en y proposant de nouveaux usages.","Moderniser les salles de une promenade commentée du vieux centre en effaçant les anciennes traces."],"correct":"C","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’une promenade commentée du vieux centre tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule une promenade commentée du vieux centre, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule une promenade commentée du vieux centre, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.416,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Déduire un effet causal lorsque deux tendances se répètent.","Ne pas confondre une corrélation statistique et une cause démontrée.","Établir une cause unique à partir de deux changements simultanés.","Comparer la force d’une corrélation dans plusieurs échantillons."],"correct":"B","explanation":"Le document permet de retenir « Ne pas confondre une corrélation statistique et une cause démontrée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la satisfaction des visiteurs et des résidents tout au long de l'année. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : la fréquentation saisonnière fragilise les chemins et dérange les riverains. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la satisfaction des visiteurs et des résidents tout au long de l'année. Lorsqu'un phénomène augmente en même temps qu'un autre, cela ne prouve pas que le premier soit la cause du second. De multiples facteurs peuvent influencer les mesures, y compris les ressources disponibles et les habitudes des personnes observées. Cette prudence est particulièrement importante ici : la fréquentation saisonnière fragilise les chemins et dérange les riverains. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":51.937,"slotSeconds":69},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour la navette vers les sentiers, présenter les hypothèses et les incertitudes des prévisions.","Pour la navette vers les sentiers, publier un chiffre précis sans détailler ses limites.","Pour la navette vers les sentiers, annoncer une moyenne sans préciser les hypothèses retenues.","Pour la navette vers les sentiers, accorder la même fiabilité à toutes les prévisions disponibles."],"correct":"A","explanation":"Le document permet de retenir « Pour la navette vers les sentiers, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant la navette vers les sentiers, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant la navette vers les sentiers, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.176,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La fréquentation de l'office du tourisme de Chambéry varie trop selon les saisons.","Les chiffres de l'office du tourisme de Chambéry ne tiennent pas compte du prix des activités.","La hausse des visites à l'office du tourisme de Chambéry vient surtout des horaires étendus.","La hausse des visites ne démontre pas un bénéfice durable du projet."],"correct":"D","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans l'office du tourisme de Chambéry, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une réservation obligatoire pour les randonnées du dimanche. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la satisfaction des visiteurs et des résidents tout au long de l'année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans l'office du tourisme de Chambéry, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une réservation obligatoire pour les randonnées du dimanche. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la satisfaction des visiteurs et des résidents tout au long de l'année ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":50.869,"slotSeconds":68},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Maintenir une aide humaine à la navette vers les sentiers pendant le seul lancement.","Évaluer la navette vers les sentiers auprès de tous puis supprimer l’accueil individuel.","Faire tester la navette vers les sentiers par divers publics, avec une aide humaine conservée.","Faire tester la navette vers les sentiers uniquement par les usagers réguliers."],"correct":"C","explanation":"Le document permet de retenir « Faire tester la navette vers les sentiers par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans l'office du tourisme de Chambéry.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'accès aux sites sans voiture particulière.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans l'office du tourisme de Chambéry."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'accès aux sites sans voiture particulière."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.579,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les conditions de terrain de la gare de montagne influencent les résultats observés.","Une technologie installée dans la gare de montagne garantit un bon résultat sans tenir compte des usages.","La performance du dispositif de la gare de montagne exige un entretien régulier.","Les usages quotidiens du matériel de la gare de montagne peuvent changer ses effets."],"correct":"B","explanation":"Le document permet de retenir « Une technologie installée dans la gare de montagne garantit un bon résultat sans tenir compte des usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans la gare de montagne affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans la gare de montagne affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50,"slotSeconds":67},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Permettre une participation volontaire et réciproque à une promenade commentée du vieux centre.","Assurer une présence régulière aux séances de une promenade commentée du vieux centre sans échanger.","Répartir les rôles de une promenade commentée du vieux centre entre des participants désignés à l’avance.","Évaluer le lien créé à une promenade commentée du vieux centre uniquement par le nombre de présences."],"correct":"A","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à une promenade commentée du vieux centre ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de une promenade commentée du vieux centre réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'accès aux sites sans voiture particulière. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de une promenade commentée du vieux centre réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'accès aux sites sans voiture particulière. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":54.109,"slotSeconds":72},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Classer les témoignages de la navette vers les sentiers selon l’ancienneté de leurs auteurs.","Comparer les récits de la navette vers les sentiers sans consulter les archives disponibles.","Conserver les récits de la navette vers les sentiers qui concordent avec la majorité.","Comparer les récits concernant la navette vers les sentiers aux faits vérifiables."],"correct":"D","explanation":"Le document permet de retenir « Comparer les récits concernant la navette vers les sentiers aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant la navette vers les sentiers, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant la navette vers les sentiers, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.285,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["La croissance de une réservation obligatoire pour les randonnées du dimanche augmente le budget sans effet sur les usagers.","Le succès de une réservation obligatoire pour les randonnées du dimanche réduit les demandes des services voisins.","Le succès d’une réservation obligatoire pour les randonnées du dimanche peut créer des difficultés aux usagers.","La fréquentation de une réservation obligatoire pour les randonnées du dimanche ralentit la promotion du dispositif."],"correct":"C","explanation":"Le document permet de retenir « Le succès d’une réservation obligatoire pour les randonnées du dimanche peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Voyages et tourisme ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une réservation obligatoire pour les randonnées du dimanche peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, la fréquentation saisonnière fragilise les chemins et dérange les riverains. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'accès aux sites sans voiture particulière. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Voyages et tourisme ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une réservation obligatoire pour les randonnées du dimanche peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, la fréquentation saisonnière fragilise les chemins et dérange les riverains. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'accès aux sites sans voiture particulière. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":63.71,"slotSeconds":81},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Suivre la satisfaction des visiteurs et des résidents tout au long de l'année en comptant sur les bénévoles actuels.","Organiser des ressources durables et suivre la satisfaction des visiteurs et des résidents tout au long de l'année pour poursuivre la navette vers les sentiers.","Obtenir des moyens durables mais ne plus mesurer la satisfaction des visiteurs et des résidents tout au long de l'année.","Étendre le service en privilégiant seulement les premiers résultats de la satisfaction des visiteurs et des résidents tout au long de l'année."],"correct":"B","explanation":"Le document permet de retenir « Organiser des ressources durables et suivre la satisfaction des visiteurs et des résidents tout au long de l'année pour poursuivre la navette vers les sentiers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à la navette vers les sentiers, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les navettes sont complètes lors des jours fériés. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la satisfaction des visiteurs et des résidents tout au long de l'année. L’idée n’est pas d’abandonner l’ambition de départ : protéger les paysages et conserver des emplois locaux hors saison. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à la navette vers les sentiers, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper les navettes sont complètes lors des jours fériés. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la satisfaction des visiteurs et des résidents tout au long de l'année. L’idée n’est pas d’abandonner l’ambition de départ : protéger les paysages et conserver des emplois locaux hors saison. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":62.817,"slotSeconds":80}]},{"id":"tcf-listening-13","version":"tcf-listening-2026-11-test13-v2","title":"TCF Listening · Test 13","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La scène représente une personne assise, occupée à consulter un sac de matériel de sport.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle consulte un sac de matériel de sport à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle consulte un sac de matériel de sport à une table. B. Elle court sur un terrain de sport. C. Elle transporte une grande valise. D. Elle répare le moteur d'une voiture."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":18.431,"slotSeconds":34},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Un homme présente une affiche liée à sport et loisirs.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur sport et loisirs à un groupe.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il prépare un repas dans la cuisine. B. Il prend le train avec deux sacs. C. Il peint une façade extérieure. D. Il présente une affiche sur sport et loisirs à un groupe."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.49,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Deux interlocuteurs préparent un tournoi de quartier autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent un tournoi de quartier autour d'une table. D. Deux personnes traversent une rivière.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Une seule personne conduit un autobus. B. Trois personnes font de la randonnée. C. Deux personnes préparent un tournoi de quartier autour d'une table. D. Deux personnes traversent une rivière."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":18.802,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'illustration montre une personne portant un sac devant le complexe sportif de Reims.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Des enfants jouent dans un jardin. B. Une femme porte un sac devant le complexe sportif de Reims. C. Une femme nage dans une piscine. D. Un homme répare un vélo.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Des enfants jouent dans un jardin. B. Une femme porte un sac devant le complexe sportif de Reims. C. Une femme nage dans une piscine. D. Un homme répare un vélo."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.083,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique le lieu de l'activité demandée.","transcript":"Question 5.\nExcusez-moi, où se tient une initiation à la natation ?\nA. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où se tient une initiation à la natation ?"},{"voice":"female","text":"A. Dans la salle du premier étage, juste après l'accueil. B. Oui, j'en ai acheté trois kilos. C. Je suis rentré hier soir. D. La météo annonce de la pluie."}],"audio":"q-05.mp3","audioSeconds":18.512,"slotSeconds":34},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter un sac de matériel de sport pour participer à un tournoi de quartier ?\nA. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter un sac de matériel de sport pour participer à un tournoi de quartier ?"},{"voice":"female","text":"A. Nous arriverons seulement dimanche. B. Il a changé de travail. C. La gare est en face de la pharmacie. D. Oui, prenez-le avec vous, il sera utile sur place."}],"audio":"q-06.mp3","audioSeconds":19.894,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour une initiation à la natation ?\nA. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour une initiation à la natation ?"},{"voice":"female","text":"A. Il n'est pas encore assez mûr. B. Ce vêtement doit sécher à plat. C. Bien sûr, disons dix heures devant l'entrée. D. J'en ai acheté cinq bouteilles."}],"audio":"q-07.mp3","audioSeconds":17.096,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à un tournoi de quartier. Est-ce possible ?\nA. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à un tournoi de quartier. Est-ce possible ?"},{"voice":"female","text":"A. Je préfère la couleur bleue. B. Oui, donnez-moi votre nom et nous chercherons un autre créneau. C. Le parc est fermé en hiver. D. J'habite au troisième étage."}],"audio":"q-08.mp3","audioSeconds":20.799,"slotSeconds":36},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["un créneau de piscine pour les familles le dimanche","Un nouveau lieu d’accueil pour les visiteurs inscrits.","Un changement des modalités des réservations actuelles.","Une adaptation des tarifs des activités déjà annoncées."],"correct":"A","explanation":"Le document permet de retenir « un créneau de piscine pour les familles le dimanche ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans le complexe sportif de Reims, à compter de lundi prochain, nous mettons en place un créneau de piscine pour les familles le dimanche. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans le complexe sportif de Reims, à compter de lundi prochain, nous mettons en place un créneau de piscine pour les familles le dimanche. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":21.914,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Un autre créneau est proposé pour une initiation à la natation en raison des transports.","Le rendez-vous pour une initiation à la natation est avancé d’une demi-heure.","Le rendez-vous pour une initiation à la natation est reporté au lendemain.","Le rendez-vous d’une initiation à la natation est repoussé à cause d’une réunion prolongée."],"correct":"D","explanation":"Le document permet de retenir « Le rendez-vous d’une initiation à la natation est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour une initiation à la natation ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour une initiation à la natation ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":26.781,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Réserver sa place pour un tournoi de quartier par téléphone avant jeudi.","Envoyer le formulaire de un tournoi de quartier par courriel avant vendredi.","Pour un tournoi de quartier, le formulaire doit être rempli en ligne avant jeudi.","Déposer sa demande pour un tournoi de quartier à l’accueil le jour même."],"correct":"C","explanation":"Le document permet de retenir « Pour un tournoi de quartier, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Sport et loisirs » aura lieu dans le complexe sportif de Reims. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Sport et loisirs » aura lieu dans le complexe sportif de Reims. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":24.642,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Remplir un nouveau formulaire d’inscription pour participer à une initiation à la natation.","Présenter le message de confirmation pour une initiation à la natation à l’accueil.","Demander une confirmation écrite après la fin de une initiation à la natation.","Présenter une pièce d’identité à l’accueil pour accéder à une initiation à la natation."],"correct":"B","explanation":"Le document permet de retenir « Présenter le message de confirmation pour une initiation à la natation à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à une initiation à la natation, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à une initiation à la natation, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":26.7,"slotSeconds":42},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance est décalée de quatorze à quinze heures, au même endroit.","La séance de une initiation à la natation change de salle mais garde le même horaire.","La séance de une initiation à la natation commence une heure plus tôt que prévu.","La séance de une initiation à la natation est reportée au lendemain à la même heure."],"correct":"A","explanation":"Le document permet de retenir « La séance est décalée de quatorze à quinze heures, au même endroit ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour une initiation à la natation. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour une initiation à la natation. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":22.415,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Maintenir une initiation à la natation avec une démonstration réalisée sans le matériel.","Reporter une initiation à la natation jusqu’à ce que le matériel soit disponible.","Garder une initiation à la natation mais renoncer à fournir la démonstration prévue.","Conserver une initiation à la natation et envoyer ensuite la démonstration manquante."],"correct":"D","explanation":"Le document permet de retenir « Conserver une initiation à la natation et envoyer ensuite la démonstration manquante ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à une initiation à la natation n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à une initiation à la natation n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":29.776,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans le complexe sportif de Reims, les difficultés ont été réglées avant le lancement.","Dans le complexe sportif de Reims, l’initiative est désormais réservée aux habitués.","La mesure répond à un besoin local, mais certaines difficultés persistent.","Dans le complexe sportif de Reims, la mesure a été suspendue faute de participants."],"correct":"C","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans le complexe sportif de Reims : un créneau de piscine pour les familles le dimanche. Le dispositif vise à répondre à une difficulté bien connue : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Plusieurs représentants soulignent toutefois que le nombre de maîtres-nageurs disponibles demeure limité. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans le complexe sportif de Reims : un créneau de piscine pour les familles le dimanche. Le dispositif vise à répondre à une difficulté bien connue : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Plusieurs représentants soulignent toutefois que le nombre de maîtres-nageurs disponibles demeure limité. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":33.582,"slotSeconds":50},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Répartir les permanences de le prêt d'équipements sportifs entre deux lieux différents.","Répartir les permanences du prêt d'équipements sportifs pour maintenir l’accueil continu.","Avancer les horaires de le prêt d'équipements sportifs en supprimant le relais du soir.","Réserver les permanences de le prêt d'équipements sportifs aux inscriptions du matin."],"correct":"B","explanation":"Le document permet de retenir « Répartir les permanences du prêt d'équipements sportifs pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le prêt d'équipements sportifs.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le prêt d'équipements sportifs."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":24.714,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui rencontrent des obstacles dans le complexe sportif de Reims.","Les visiteurs ayant déjà terminé leurs démarches dans le complexe sportif de Reims.","Les personnes qui fréquentent régulièrement les ateliers de le complexe sportif de Reims.","Les employés chargés d’accueillir et d’orienter les visiteurs de le complexe sportif de Reims."],"correct":"A","explanation":"Le document permet de retenir « Les personnes qui rencontrent des obstacles dans le complexe sportif de Reims ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans le complexe sportif de Reims. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans le complexe sportif de Reims. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":31.202,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["Elle souhaite déplacer un tournoi de quartier à cause d’un changement de salle.","Elle demande un autre horaire pour un tournoi de quartier afin d’accompagner un proche.","Elle ne peut se rendre à un tournoi de quartier à cause d’un retard de transport.","Elle travaille encore vendredi à seize heures, au moment d’un tournoi de quartier."],"correct":"D","explanation":"Le document permet de retenir « Elle travaille encore vendredi à seize heures, au moment d’un tournoi de quartier ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour un tournoi de quartier. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour un tournoi de quartier. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":29.033,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Répartir les participants de un tournoi de quartier selon leur expérience.","Réduire le groupe de un tournoi de quartier pour utiliser moins de matériel.","Le petit groupe permet d’échanger davantage pendant un tournoi de quartier.","Adapter le nombre de places de un tournoi de quartier à la taille de la salle."],"correct":"C","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant un tournoi de quartier ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour un tournoi de quartier, des visites en petits groupes seront proposées dans le complexe sportif de Reims. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour un tournoi de quartier, des visites en petits groupes seront proposées dans le complexe sportif de Reims. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":23.565,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle demande des précisions sur le nombre de places prévues dans le projet.","Elle souhaite savoir comment sera pris en compte le maintien des installations en bon état.","Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet."],"correct":"B","explanation":"Le document permet de retenir « Elle souhaite savoir comment sera pris en compte le maintien des installations en bon état ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte le maintien des installations en bon état. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte le maintien des installations en bon état. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":29.347,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Organiser les permanences selon les horaires disponibles des bénévoles.","Prévoir le matériel nécessaire selon les inscriptions à un tournoi de quartier.","Définir les activités prioritaires selon le public attendu pour un tournoi de quartier.","Adapter les tâches des bénévoles aux compétences requises pour un tournoi de quartier."],"correct":"A","explanation":"Le document permet de retenir « Organiser les permanences selon les horaires disponibles des bénévoles ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans le complexe sportif de Reims, pour préparer un tournoi de quartier, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans le complexe sportif de Reims, pour préparer un tournoi de quartier, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":36.659,"slotSeconds":53},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["La meilleure organisation des activités obtenue grâce à une initiation à la natation.","Les connaissances pratiques acquises au cours de une initiation à la natation.","Les nouveaux contacts professionnels pris pendant une initiation à la natation.","Les relations de confiance créées autour d’une initiation à la natation."],"correct":"D","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’une initiation à la natation ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à une initiation à la natation. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à une initiation à la natation. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":45.431,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Mettre en place des activités adaptées conçues avec les pratiquants partout avant de mesurer les résultats.","Consulter les habitants sur des activités adaptées conçues avec les pratiquants sans mener d’essai concret.","Expérimenter des activités adaptées conçues avec les pratiquants, recueillir les avis et publier un bilan.","Expérimenter des activités adaptées conçues avec les pratiquants mais ne publier aucun retour des participants."],"correct":"C","explanation":"Le document permet de retenir « Expérimenter des activités adaptées conçues avec les pratiquants, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Sport et loisirs ».\nNous avons discuté de des activités adaptées conçues avec les pratiquants, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan.\nLes usagers craignent surtout le maintien des installations en bon état. Une application immédiate, sans consultation, risquerait de perdre leur confiance.\nAlors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Sport et loisirs »."},{"voice":"male","text":"Nous avons discuté de des activités adaptées conçues avec les pratiquants, mais les réactions restent partagées. Il nous faut une décision praticable, pas seulement un slogan."},{"voice":"female","text":"Les usagers craignent surtout le maintien des installations en bon état. Une application immédiate, sans consultation, risquerait de perdre leur confiance."},{"voice":"male","text":"Alors fixons une période d’essai, relevons les résultats et laissons les participants nous signaler les difficultés."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":56.412,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le prêt d'équipements sportifs comprend surtout des personnes en attente.","L’étude sur le prêt d'équipements sportifs n’a presque pas touché ceux qui ont abandonné.","L’étude de le prêt d'équipements sportifs s’appuie principalement sur les réponses des agents.","L’étude de le prêt d'équipements sportifs donne peu de place aux nouveaux inscrits."],"correct":"B","explanation":"Le document permet de retenir « L’étude sur le prêt d'équipements sportifs n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le prêt d'équipements sportifs. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le prêt d'équipements sportifs. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.267,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Concilier des activités sportives adaptées avec l’accès des publics handicapés.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours.","Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement."],"correct":"A","explanation":"Le document permet de retenir « Concilier des activités sportives adaptées avec l’accès des publics handicapés ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans le complexe sportif de Reims, une initiative propose des activités adaptées conçues avec les pratiquants. Les responsables espèrent ainsi répondre à une difficulté bien connue : les équipements restent inaccessibles à plusieurs personnes en situation de handicap.\nNous soutenons l’objectif général, mais il faut prendre en compte le maintien des installations en bon état. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que former les bénévoles et assurer un budget de maintenance. Pourtant, le nombre de maîtres-nageurs disponibles demeure limité. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans le complexe sportif de Reims, une initiative propose des activités adaptées conçues avec les pratiquants. Les responsables espèrent ainsi répondre à une difficulté bien connue : les équipements restent inaccessibles à plusieurs personnes en situation de handicap."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte le maintien des installations en bon état. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que former les bénévoles et assurer un budget de maintenance. Pourtant, le nombre de maîtres-nageurs disponibles demeure limité. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":55.712,"slotSeconds":72},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Le projet de un créneau de piscine pour les familles le dimanche est annoncé mais n’a pas encore été lancé.","Les résultats de un créneau de piscine pour les familles le dimanche concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre un créneau de piscine pour les familles le dimanche dès la fin des premiers essais.","Les premiers effets d’un créneau de piscine pour les familles le dimanche doivent être vérifiés dans la durée."],"correct":"D","explanation":"Le document permet de retenir « Les premiers effets d’un créneau de piscine pour les familles le dimanche doivent être vérifiés dans la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé un créneau de piscine pour les familles le dimanche. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Le nombre de maîtres-nageurs disponibles demeure limité. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la participation régulière plutôt que les seules inscriptions. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé un créneau de piscine pour les familles le dimanche. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Le nombre de maîtres-nageurs disponibles demeure limité. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : la participation régulière plutôt que les seules inscriptions. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":49.61,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Conserver les horaires de le prêt d'équipements sportifs malgré les demandes du matin.","Réserver les créneaux matinaux de le prêt d'équipements sportifs aux seuls abonnés.","Adapter les horaires du prêt d'équipements sportifs sans pénaliser les usagers du soir.","Ouvrir le prêt d'équipements sportifs plus tôt en supprimant les créneaux tardifs."],"correct":"C","explanation":"Le document permet de retenir « Adapter les horaires du prêt d'équipements sportifs sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le prêt d'équipements sportifs ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le prêt d'équipements sportifs ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.422,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Tester un vestiaire accessible sur un seul site avant de l’ouvrir à tous.","Les équipements d’un vestiaire accessible ont été choisis avant la consultation des futurs usagers.","Préparer le budget de un vestiaire accessible avant de calculer son entretien.","Adapter les équipements de un vestiaire accessible après consultation des équipes."],"correct":"B","explanation":"Le document permet de retenir « Les équipements d’un vestiaire accessible ont été choisis avant la consultation des futurs usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un vestiaire accessible a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le maintien des installations en bon état est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un vestiaire accessible a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de le maintien des installations en bon état est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":48.635,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un veut mesurer la participation régulière plutôt que les seules inscriptions ; l’autre demande des récits.","L’un veut comparer les coûts de la participation régulière plutôt que les seules inscriptions ; l’autre mesure la fréquentation.","L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres."],"correct":"A","explanation":"Le document permet de retenir « L’un veut mesurer la participation régulière plutôt que les seules inscriptions ; l’autre demande des récits ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Sport et loisirs ».\nPour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la participation régulière plutôt que les seules inscriptions et comparer les périodes avant de décider.\nC’est utile, mais il faut aussi rencontrer les personnes concernées. Les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Cette réalité risque de disparaître derrière une moyenne flatteuse.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Sport et loisirs »."},{"voice":"male","text":"Pour évaluer le projet, regardons des indicateurs vérifiables. Nous pourrions suivre cet indicateur : la participation régulière plutôt que les seules inscriptions et comparer les périodes avant de décider."},{"voice":"female","text":"C’est utile, mais il faut aussi rencontrer les personnes concernées. Les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Cette réalité risque de disparaître derrière une moyenne flatteuse."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":53.287,"slotSeconds":71},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Conserver le bâtiment de une initiation à la natation uniquement pour ses activités passées.","Moderniser les salles de une initiation à la natation en effaçant les anciennes traces.","Rénover le lieu de une initiation à la natation sans changer l’usage actuel des espaces.","Préserver l’histoire du lieu d’une initiation à la natation tout en y proposant de nouveaux usages."],"correct":"D","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’une initiation à la natation tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule une initiation à la natation, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule une initiation à la natation, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":51.067,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Suivre seulement les personnes arrivées au cours du premier mois.","Comparer les progrès enregistrés lors des deux premières semaines.","Distinguer une amélioration immédiate d’un changement durable.","Mesurer l’évolution d’un projet uniquement pendant son lancement."],"correct":"C","explanation":"Le document permet de retenir « Distinguer une amélioration immédiate d’un changement durable ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la participation régulière plutôt que les seules inscriptions. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, la participation régulière plutôt que les seules inscriptions. Une amélioration relevée quelques jours après une intervention n'est pas nécessairement durable. Les changements de saison, la composition des participants et les adaptations successives peuvent modifier les résultats. Seul un suivi suffisamment long permet de comprendre ce qui se maintient et ce qui disparaît. Cette prudence est particulièrement importante ici : les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":55.362,"slotSeconds":73},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le prêt d'équipements sportifs, annoncer une moyenne sans préciser les hypothèses retenues.","Pour le prêt d'équipements sportifs, présenter les hypothèses et les incertitudes des prévisions.","Pour le prêt d'équipements sportifs, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le prêt d'équipements sportifs, publier un chiffre précis sans détailler ses limites."],"correct":"B","explanation":"Le document permet de retenir « Pour le prêt d'équipements sportifs, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le prêt d'équipements sportifs, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le prêt d'équipements sportifs, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":51.752,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites ne démontre pas un bénéfice durable du projet.","Les chiffres de le complexe sportif de Reims ne tiennent pas compte du prix des activités.","La hausse des visites à le complexe sportif de Reims vient surtout des horaires étendus.","La fréquentation de le complexe sportif de Reims varie trop selon les saisons."],"correct":"A","explanation":"Le document permet de retenir « La hausse des visites ne démontre pas un bénéfice durable du projet ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans le complexe sportif de Reims, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un créneau de piscine pour les familles le dimanche. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la participation régulière plutôt que les seules inscriptions ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans le complexe sportif de Reims, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : un créneau de piscine pour les familles le dimanche. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer la participation régulière plutôt que les seules inscriptions ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":49.139,"slotSeconds":67},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Évaluer le prêt d'équipements sportifs auprès de tous puis supprimer l’accueil individuel.","Faire tester le prêt d'équipements sportifs uniquement par les usagers réguliers.","Maintenir une aide humaine à le prêt d'équipements sportifs pendant le seul lancement.","Faire tester le prêt d'équipements sportifs par divers publics, avec une aide humaine conservée."],"correct":"D","explanation":"Le document permet de retenir « Faire tester le prêt d'équipements sportifs par divers publics, avec une aide humaine conservée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans le complexe sportif de Reims.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le maintien des installations en bon état.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans le complexe sportif de Reims."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : le maintien des installations en bon état."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.196,"slotSeconds":71},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["La performance du dispositif de le gymnase municipal exige un entretien régulier.","Les usages quotidiens du matériel de le gymnase municipal peuvent changer ses effets.","Les résultats techniques du gymnase municipal suffiraient même si les usages réels diffèrent.","Les conditions de terrain de le gymnase municipal influencent les résultats observés."],"correct":"C","explanation":"Le document permet de retenir « Les résultats techniques du gymnase municipal suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le gymnase municipal affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le gymnase municipal affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.266,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Répartir les rôles de une initiation à la natation entre des participants désignés à l’avance.","Le volontariat et les échanges réciproques pendant une initiation à la natation renforcent les liens.","Évaluer le lien créé à une initiation à la natation uniquement par le nombre de présences.","Assurer une présence régulière aux séances de une initiation à la natation sans échanger."],"correct":"B","explanation":"Le document permet de retenir « Le volontariat et les échanges réciproques pendant une initiation à la natation renforcent les liens ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de une initiation à la natation réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le maintien des installations en bon état. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de une initiation à la natation réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : le maintien des installations en bon état. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":52.456,"slotSeconds":70},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Comparer les récits concernant le prêt d'équipements sportifs aux faits vérifiables.","Comparer les récits de le prêt d'équipements sportifs sans consulter les archives disponibles.","Conserver les récits de le prêt d'équipements sportifs qui concordent avec la majorité.","Classer les témoignages de le prêt d'équipements sportifs selon l’ancienneté de leurs auteurs."],"correct":"A","explanation":"Le document permet de retenir « Comparer les récits concernant le prêt d'équipements sportifs aux faits vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le prêt d'équipements sportifs, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le prêt d'équipements sportifs, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":52.926,"slotSeconds":70},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès de un créneau de piscine pour les familles le dimanche réduit les demandes des services voisins.","La fréquentation de un créneau de piscine pour les familles le dimanche ralentit la promotion du dispositif.","La croissance de un créneau de piscine pour les familles le dimanche augmente le budget sans effet sur les usagers.","Le succès d’un créneau de piscine pour les familles le dimanche peut créer des difficultés aux usagers."],"correct":"D","explanation":"Le document permet de retenir « Le succès d’un créneau de piscine pour les familles le dimanche peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Sport et loisirs ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un créneau de piscine pour les familles le dimanche peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le maintien des installations en bon état. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Sport et loisirs ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, un créneau de piscine pour les familles le dimanche peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les équipements restent inaccessibles à plusieurs personnes en situation de handicap. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner le maintien des installations en bon état. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":62.677,"slotSeconds":80},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Obtenir des moyens durables mais ne plus mesurer la participation régulière plutôt que les seules inscriptions.","Étendre le service en privilégiant seulement les premiers résultats de la participation régulière plutôt que les seules inscriptions.","Assurer des moyens durables et suivre la participation régulière plutôt que les seules inscriptions sur la durée.","Suivre la participation régulière plutôt que les seules inscriptions en comptant sur les bénévoles actuels."],"correct":"C","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre la participation régulière plutôt que les seules inscriptions sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le prêt d'équipements sportifs, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper le nombre de maîtres-nageurs disponibles demeure limité. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la participation régulière plutôt que les seules inscriptions. L’idée n’est pas d’abandonner l’ambition de départ : former les bénévoles et assurer un budget de maintenance. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le prêt d'équipements sportifs, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper le nombre de maîtres-nageurs disponibles demeure limité. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre la participation régulière plutôt que les seules inscriptions. L’idée n’est pas d’abandonner l’ambition de départ : former les bénévoles et assurer un budget de maintenance. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.136,"slotSeconds":81}]},{"id":"tcf-listening-14","version":"tcf-listening-2026-11-test14-v2","title":"TCF Listening · Test 14","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La scène représente une personne assise, occupée à consulter une paire de jumelles.","transcript":"Question 1.\nObservez l'image et choisissez la phrase qui convient.\nA. Elle répare le moteur d'une voiture. B. Elle consulte une paire de jumelles à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Observez l'image et choisissez la phrase qui convient."},{"voice":"female","text":"A. Elle répare le moteur d'une voiture. B. Elle consulte une paire de jumelles à une table. C. Elle court sur un terrain de sport. D. Elle transporte une grande valise."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":17.978,"slotSeconds":32},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Un homme présente une affiche liée à environnement et biodiversité.","transcript":"Question 2.\nÉcoutez les quatre propositions.\nA. Il présente une affiche sur environnement et biodiversité à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions."},{"voice":"female","text":"A. Il présente une affiche sur environnement et biodiversité à un groupe. B. Il prépare un repas dans la cuisine. C. Il prend le train avec deux sacs. D. Il peint une façade extérieure."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":18.236,"slotSeconds":33},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Deux interlocuteurs préparent une journée d'observation des oiseaux autour d'une table.","transcript":"Question 3.\nÉcoutez les propositions et identifiez la bonne.\nA. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une journée d'observation des oiseaux autour d'une table.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Écoutez les propositions et identifiez la bonne."},{"voice":"female","text":"A. Deux personnes traversent une rivière. B. Une seule personne conduit un autobus. C. Trois personnes font de la randonnée. D. Deux personnes préparent une journée d'observation des oiseaux autour d'une table."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":19.209,"slotSeconds":34},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"L'illustration montre une personne portant un sac devant la réserve naturelle de la Loire.","transcript":"Question 4.\nChoisissez la phrase correspondant à l'image.\nA. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant la réserve naturelle de la Loire. D. Une femme nage dans une piscine.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Choisissez la phrase correspondant à l'image."},{"voice":"female","text":"A. Un homme répare un vélo. B. Des enfants jouent dans un jardin. C. Une femme porte un sac devant la réserve naturelle de la Loire. D. Une femme nage dans une piscine."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":18.431,"slotSeconds":34},{"number":5,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La réponse précise le point de départ de l'activité.","transcript":"Question 5.\nExcusez-moi, où commence une sortie de reconnaissance des plantes ?\nA. La météo annonce de la pluie. B. Le point de départ est devant l’accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, où commence une sortie de reconnaissance des plantes ?"},{"voice":"female","text":"A. La météo annonce de la pluie. B. Le point de départ est devant l’accueil. C. Oui, j'en ai acheté trois kilos. D. Je suis rentré hier soir."}],"audio":"q-05.mp3","audioSeconds":17.827,"slotSeconds":33},{"number":6,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"L'interlocuteur répond directement à la question sur l'objet à apporter.","transcript":"Question 6.\nEst-ce que je dois apporter une paire de jumelles pour participer à une journée d'observation des oiseaux ?\nA. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Est-ce que je dois apporter une paire de jumelles pour participer à une journée d'observation des oiseaux ?"},{"voice":"female","text":"A. Oui, prenez-le avec vous, il sera utile sur place. B. Nous arriverons seulement dimanche. C. Il a changé de travail. D. La gare est en face de la pharmacie."}],"audio":"q-06.mp3","audioSeconds":19.673,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"La réponse confirme le rendez-vous en proposant un horaire et un lieu.","transcript":"Question 7.\nOn peut se retrouver demain pour une sortie de reconnaissance des plantes ?\nA. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"On peut se retrouver demain pour une sortie de reconnaissance des plantes ?"},{"voice":"female","text":"A. J'en ai acheté cinq bouteilles. B. Il n'est pas encore assez mûr. C. Ce vêtement doit sécher à plat. D. Bien sûr, disons dix heures devant l'entrée."}],"audio":"q-07.mp3","audioSeconds":17.305,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse est appropriée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La réponse donne une démarche adaptée pour modifier l'inscription.","transcript":"Question 8.\nBonjour, je voudrais déplacer mon inscription à une journée d'observation des oiseaux. Est-ce possible ?\nA. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Bonjour, je voudrais déplacer mon inscription à une journée d'observation des oiseaux. Est-ce possible ?"},{"voice":"female","text":"A. J'habite au troisième étage. B. Je préfère la couleur bleue. C. Oui, donnez-moi votre nom et nous chercherons un autre créneau. D. Le parc est fermé en hiver."}],"audio":"q-08.mp3","audioSeconds":21.426,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Quelle nouveauté est annoncée ?","options":["Un changement des modalités des réservations actuelles.","Une nouvelle zone de quiétude au printemps.","Une adaptation des tarifs des activités déjà annoncées.","Un nouveau lieu d’accueil pour les visiteurs inscrits."],"correct":"B","explanation":"Le document permet de retenir « Une nouvelle zone de quiétude au printemps ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 9.\nInformation aux visiteurs. Dans la réserve naturelle de la Loire, à compter de lundi prochain, nous mettons en place une nouvelle zone de quiétude au printemps. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil.\nQuelle nouveauté est annoncée ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Information aux visiteurs. Dans la réserve naturelle de la Loire, à compter de lundi prochain, nous mettons en place une nouvelle zone de quiétude au printemps. Les autres activités et les tarifs habituels restent inchangés. Les personnes qui souhaitent obtenir des renseignements peuvent contacter directement l'accueil."},{"voice":"female","text":"Quelle nouveauté est annoncée ?"}],"audio":"q-09.mp3","audioSeconds":22.448,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?","options":["Le rendez-vous d’une sortie de reconnaissance des plantes est repoussé à cause d’une réunion prolongée.","Le rendez-vous pour une sortie de reconnaissance des plantes est avancé d’une demi-heure.","Le rendez-vous pour une sortie de reconnaissance des plantes est reporté au lendemain.","Un autre créneau est proposé pour une sortie de reconnaissance des plantes en raison des transports."],"correct":"A","explanation":"Le document permet de retenir « Le rendez-vous d’une sortie de reconnaissance des plantes est repoussé à cause d’une réunion prolongée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 10.\nTu es toujours disponible demain pour une sortie de reconnaissance des plantes ?\nJe comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue.\nOn pourrait commencer trente minutes après. L'activité n'aura pas encore commencé.\nD'accord, merci. Je t'enverrai un message quand je partirai.\nPourquoi les interlocuteurs modifient-ils leur rendez-vous ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Tu es toujours disponible demain pour une sortie de reconnaissance des plantes ?"},{"voice":"female","text":"Je comptais venir, mais ma réunion finit plus tard que prévu. Je ne pourrai pas arriver à l'heure convenue."},{"voice":"male","text":"On pourrait commencer trente minutes après. L'activité n'aura pas encore commencé."},{"voice":"female","text":"D'accord, merci. Je t'enverrai un message quand je partirai."},{"voice":"female","text":"Pourquoi les interlocuteurs modifient-ils leur rendez-vous ?"}],"audio":"q-10.mp3","audioSeconds":27.077,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment les personnes intéressées doivent-elles s'inscrire ?","options":["Envoyer le formulaire de une journée d'observation des oiseaux par courriel avant vendredi.","Déposer sa demande pour une journée d'observation des oiseaux à l’accueil le jour même.","Réserver sa place pour une journée d'observation des oiseaux par téléphone avant jeudi.","Pour une journée d'observation des oiseaux, le formulaire doit être rempli en ligne avant jeudi."],"correct":"D","explanation":"Le document permet de retenir « Pour une journée d'observation des oiseaux, le formulaire doit être rempli en ligne avant jeudi ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 11.\nUne rencontre sur le thème « Environnement et biodiversité » aura lieu dans la réserve naturelle de la Loire. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel.\nComment les personnes intéressées doivent-elles s'inscrire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"Une rencontre sur le thème « Environnement et biodiversité » aura lieu dans la réserve naturelle de la Loire. Les places sont limitées et la participation ne sera confirmée qu'après inscription. Pour réserver, il faut remplir le formulaire disponible sur le site de l'organisateur avant jeudi soir. Une confirmation sera envoyée par courriel."},{"voice":"female","text":"Comment les personnes intéressées doivent-elles s'inscrire ?"}],"audio":"q-11.mp3","audioSeconds":25.513,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Quelle démarche le visiteur doit-il effectuer ?","options":["Demander une confirmation écrite après la fin de une sortie de reconnaissance des plantes.","Présenter une pièce d’identité à l’accueil pour accéder à une sortie de reconnaissance des plantes.","Présenter le message de confirmation pour une sortie de reconnaissance des plantes à l’accueil.","Remplir un nouveau formulaire d’inscription pour participer à une sortie de reconnaissance des plantes."],"correct":"C","explanation":"Le document permet de retenir « Présenter le message de confirmation pour une sortie de reconnaissance des plantes à l’accueil ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 12.\nBonjour, j'aimerais participer à une sortie de reconnaissance des plantes, mais mon nom ne figure pas sur la liste.\nVotre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?\nOui, je peux vous le montrer sur mon téléphone.\nParfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier.\nQuelle démarche le visiteur doit-il effectuer ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'aimerais participer à une sortie de reconnaissance des plantes, mais mon nom ne figure pas sur la liste."},{"voice":"male","text":"Votre inscription a peut-être été faite avec une autre adresse. Avez-vous conservé le message de confirmation ?"},{"voice":"female","text":"Oui, je peux vous le montrer sur mon téléphone."},{"voice":"male","text":"Parfait. Présentez-le à l'accueil, nous vérifierons immédiatement votre dossier."},{"voice":"female","text":"Quelle démarche le visiteur doit-il effectuer ?"}],"audio":"q-12.mp3","audioSeconds":27.048,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quel changement concerne l'activité annoncée ?","options":["La séance de une sortie de reconnaissance des plantes commence une heure plus tôt que prévu.","La séance d’une sortie de reconnaissance des plantes est décalée à quinze heures, au même endroit.","La séance de une sortie de reconnaissance des plantes est reportée au lendemain à la même heure.","La séance de une sortie de reconnaissance des plantes change de salle mais garde le même horaire."],"correct":"B","explanation":"Le document permet de retenir « La séance d’une sortie de reconnaissance des plantes est décalée à quinze heures, au même endroit ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 13.\nMessage aux participants inscrits pour une sortie de reconnaissance des plantes. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début.\nQuel changement concerne l'activité annoncée ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Message aux participants inscrits pour une sortie de reconnaissance des plantes. La séance prévue à quatorze heures commencera finalement à quinze heures, en raison d'une intervention technique dans la salle. L'adresse ne change pas. Merci de conserver votre confirmation d'inscription et d'arriver quelques minutes avant le début."},{"voice":"female","text":"Quel changement concerne l'activité annoncée ?"}],"audio":"q-13.mp3","audioSeconds":23.147,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quelle solution les deux personnes retiennent-elles ?","options":["Conserver une sortie de reconnaissance des plantes et envoyer la démonstration plus tard.","Reporter une sortie de reconnaissance des plantes jusqu’à ce que le matériel soit disponible.","Garder une sortie de reconnaissance des plantes mais renoncer à fournir la démonstration prévue.","Maintenir une sortie de reconnaissance des plantes avec une démonstration réalisée sans le matériel."],"correct":"A","explanation":"Le document permet de retenir « Conserver une sortie de reconnaissance des plantes et envoyer la démonstration plus tard ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 14.\nLe matériel destiné à une sortie de reconnaissance des plantes n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu.\nMais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?\nOui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt.\nParfait, cela évitera d'annuler toute la rencontre.\nQuelle solution les deux personnes retiennent-elles ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le matériel destiné à une sortie de reconnaissance des plantes n'est pas encore arrivé. Nous ne pourrons pas faire la démonstration comme prévu."},{"voice":"female","text":"Mais les participants sont déjà en route. Peut-on conserver l'introduction et présenter les documents disponibles ?"},{"voice":"male","text":"Oui, puis nous enverrons un lien vers la démonstration dès que le matériel sera prêt."},{"voice":"female","text":"Parfait, cela évitera d'annuler toute la rencontre."},{"voice":"female","text":"Quelle solution les deux personnes retiennent-elles ?"}],"audio":"q-14.mp3","audioSeconds":30.612,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Quelle idée principale ressort de cette information ?","options":["Dans la réserve naturelle de la Loire, l’initiative est désormais réservée aux habitués.","Dans la réserve naturelle de la Loire, la mesure a été suspendue faute de participants.","Dans la réserve naturelle de la Loire, les difficultés ont été réglées avant le lancement.","La mesure répond à un besoin local, mais certaines difficultés persistent."],"correct":"D","explanation":"Le document permet de retenir « La mesure répond à un besoin local, mais certaines difficultés persistent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 15.\nVoici les nouvelles de la région. Une initiative vient d'être annoncée dans la réserve naturelle de la Loire : une nouvelle zone de quiétude au printemps. Le dispositif vise à répondre à une difficulté bien connue : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Plusieurs représentants soulignent toutefois que certaines passerelles seront fermées durant la nidification. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation.\nQuelle idée principale ressort de cette information ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les nouvelles de la région. Une initiative vient d'être annoncée dans la réserve naturelle de la Loire : une nouvelle zone de quiétude au printemps. Le dispositif vise à répondre à une difficulté bien connue : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Plusieurs représentants soulignent toutefois que certaines passerelles seront fermées durant la nidification. Les organisateurs présenteront un premier bilan après trois mois d'expérimentation."},{"voice":"female","text":"Quelle idée principale ressort de cette information ?"}],"audio":"q-15.mp3","audioSeconds":33.35,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Pourquoi les horaires sont-ils réorganisés ?","options":["Avancer les horaires de le programme de suivi des espèces en supprimant le relais du soir.","Réserver les permanences de le programme de suivi des espèces aux inscriptions du matin.","Répartir les permanences du programme de suivi des espèces pour maintenir l’accueil continu.","Répartir les permanences de le programme de suivi des espèces entre deux lieux différents."],"correct":"C","explanation":"Le document permet de retenir « Répartir les permanences du programme de suivi des espèces pour maintenir l’accueil continu ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 16.\nIl manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?\nJe peux venir à huit heures, mais je dois partir avant dix-sept heures.\nPas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de suivi des espèces.\nTrès bien. Je préviens aussi les autres membres de l'équipe.\nPourquoi les horaires sont-ils réorganisés ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Il manque une personne à l'accueil demain matin. Est-ce que tu pourrais commencer plus tôt ?"},{"voice":"male","text":"Je peux venir à huit heures, mais je dois partir avant dix-sept heures."},{"voice":"female","text":"Pas de problème, je prendrai le relais en fin de journée. Nous devons garder un accueil continu pour le programme de suivi des espèces."},{"voice":"male","text":"Très bien. Je préviens aussi les autres membres de l'équipe."},{"voice":"female","text":"Pourquoi les horaires sont-ils réorganisés ?"}],"audio":"q-16.mp3","audioSeconds":25.446,"slotSeconds":41},{"number":17,"kind":"announcement","question":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?","options":["Les personnes qui fréquentent régulièrement les ateliers de la réserve naturelle de la Loire.","Les visiteurs de la réserve naturelle de la Loire qui peinent à accéder au service ordinaire.","Les employés chargés d’accueillir et d’orienter les visiteurs de la réserve naturelle de la Loire.","Les visiteurs ayant déjà terminé leurs démarches dans la réserve naturelle de la Loire."],"correct":"B","explanation":"Le document permet de retenir « Les visiteurs de la réserve naturelle de la Loire qui peinent à accéder au service ordinaire ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 17.\nUne nouvelle formule d’accompagnement est proposée dans la réserve naturelle de la Loire. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. La première permanence se tiendra mardi matin.\nÀ qui le nouveau dispositif s'adresse-t-il particulièrement ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"Une nouvelle formule d’accompagnement est proposée dans la réserve naturelle de la Loire. Elle est destinée aux personnes qui rencontrent des obstacles pour utiliser les dispositifs ordinaires. Des conseillers seront disponibles sur rendez-vous et pourront expliquer les étapes à suivre. Cette initiative répond notamment à une difficulté : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. La première permanence se tiendra mardi matin."},{"voice":"female","text":"À qui le nouveau dispositif s'adresse-t-il particulièrement ?"}],"audio":"q-17.mp3","audioSeconds":31.063,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Pourquoi la personne choisit-elle un autre créneau ?","options":["La personne travaille à l’heure prévue pour une journée d'observation des oiseaux.","Elle demande un autre horaire pour une journée d'observation des oiseaux afin d’accompagner un proche.","Elle ne peut se rendre à une journée d'observation des oiseaux à cause d’un retard de transport.","Elle souhaite déplacer une journée d'observation des oiseaux à cause d’un changement de salle."],"correct":"A","explanation":"Le document permet de retenir « La personne travaille à l’heure prévue pour une journée d'observation des oiseaux ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 18.\nBonjour, j'appelle au sujet de ma réservation pour une journée d'observation des oiseaux. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail.\nNous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir.\nLe samedi me conviendrait. Faut-il refaire le paiement ?\nNon. Je modifie simplement le rendez-vous et vous envoie une confirmation.\nPourquoi la personne choisit-elle un autre créneau ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'appelle au sujet de ma réservation pour une journée d'observation des oiseaux. Vous m'avez proposé vendredi à seize heures, mais je serai encore au travail."},{"voice":"female","text":"Nous avons une place samedi matin, ou vous pouvez choisir la séance de lundi soir."},{"voice":"male","text":"Le samedi me conviendrait. Faut-il refaire le paiement ?"},{"voice":"female","text":"Non. Je modifie simplement le rendez-vous et vous envoie une confirmation."},{"voice":"female","text":"Pourquoi la personne choisit-elle un autre créneau ?"}],"audio":"q-18.mp3","audioSeconds":30.455,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Pourquoi la participation est-elle limitée ?","options":["Réduire le groupe de une journée d'observation des oiseaux pour utiliser moins de matériel.","Adapter le nombre de places de une journée d'observation des oiseaux à la taille de la salle.","Répartir les participants de une journée d'observation des oiseaux selon leur expérience.","Le petit groupe permet d’échanger davantage pendant une journée d'observation des oiseaux."],"correct":"D","explanation":"Le document permet de retenir « Le petit groupe permet d’échanger davantage pendant une journée d'observation des oiseaux ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 19.\nPour une journée d'observation des oiseaux, des visites en petits groupes seront proposées dans la réserve naturelle de la Loire. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable.\nPourquoi la participation est-elle limitée ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pour une journée d'observation des oiseaux, des visites en petits groupes seront proposées dans la réserve naturelle de la Loire. Le nombre de participants est limité à douze par séance, afin que chacun puisse poser des questions et bénéficier des explications de l'animateur. L'inscription est ouverte à tous, sans obligation d'expérience préalable."},{"voice":"female","text":"Pourquoi la participation est-elle limitée ?"}],"audio":"q-19.mp3","audioSeconds":24.677,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Quelle est l'inquiétude principale de la visiteuse ?","options":["Elle veut savoir comment les horaires des séances seront communiqués.","Elle cherche à connaître le prix définitif de sa participation au projet.","La visiteuse souhaite des précisions sur l'équilibre entre accès à la nature et protection des habitats.","Elle demande des précisions sur le nombre de places prévues dans le projet."],"correct":"C","explanation":"Le document permet de retenir « La visiteuse souhaite des précisions sur l'équilibre entre accès à la nature et protection des habitats ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 20.\nVotre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription.\nY a-t-il une information qui vous manque ?\nOui, je voudrais comprendre comment vous prenez en compte l'équilibre entre accès à la nature et protection des habitats. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager.\nC'est tout à fait normal. Je peux vous présenter nos procédures en détail.\nQuelle est l'inquiétude principale de la visiteuse ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"Votre projet me plaît et les horaires sont pratiques, mais j'aimerais revenir avant de confirmer mon inscription."},{"voice":"male","text":"Y a-t-il une information qui vous manque ?"},{"voice":"female","text":"Oui, je voudrais comprendre comment vous prenez en compte l'équilibre entre accès à la nature et protection des habitats. J'ai eu une mauvaise expérience ailleurs et je préfère poser mes questions avant de m'engager."},{"voice":"male","text":"C'est tout à fait normal. Je peux vous présenter nos procédures en détail."},{"voice":"female","text":"Quelle est l'inquiétude principale de la visiteuse ?"}],"audio":"q-20.mp3","audioSeconds":30.473,"slotSeconds":47},{"number":21,"kind":"announcement","question":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","options":["Définir les activités prioritaires selon le public attendu pour une journée d'observation des oiseaux.","Répartir les bénévoles d’une journée d'observation des oiseaux selon les créneaux où ils sont libres.","Adapter les tâches des bénévoles aux compétences requises pour une journée d'observation des oiseaux.","Prévoir le matériel nécessaire selon les inscriptions à une journée d'observation des oiseaux."],"correct":"B","explanation":"Le document permet de retenir « Répartir les bénévoles d’une journée d'observation des oiseaux selon les créneaux où ils sont libres ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 21.\nAnnonce locale. Dans la réserve naturelle de la Loire, pour préparer une journée d'observation des oiseaux, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée.\nPour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Annonce locale. Dans la réserve naturelle de la Loire, pour préparer une journée d'observation des oiseaux, nous recherchons des volontaires pour l’accueil, la préparation des salles et l’orientation des visiteurs. Certaines personnes pourront rester toute la journée, d’autres seulement une heure. Afin d’éviter de réunir trop de monde en début de matinée et de manquer d’aide en fin d’après-midi, veuillez indiquer vos horaires avant mercredi. Vous recevrez ensuite un planning personnalisé. Aucune expérience préalable n’est exigée."},{"voice":"female","text":"Pour quelle raison les volontaires doivent-ils préciser leurs disponibilités ?"}],"audio":"q-21.mp3","audioSeconds":37.018,"slotSeconds":54},{"number":22,"kind":"interview","question":"Quel avantage l'invitée juge-t-elle le plus important ?","options":["Les relations de confiance créées autour d’une sortie de reconnaissance des plantes.","Les connaissances pratiques acquises au cours de une sortie de reconnaissance des plantes.","Les nouveaux contacts professionnels pris pendant une sortie de reconnaissance des plantes.","La meilleure organisation des activités obtenue grâce à une sortie de reconnaissance des plantes."],"correct":"A","explanation":"Le document permet de retenir « Les relations de confiance créées autour d’une sortie de reconnaissance des plantes ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 22.\nVous participez à une sortie de reconnaissance des plantes. Qu’est-ce que cette expérience vous a apporté ?\nAu départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre.\nQuel avantage l'invitée juge-t-elle le plus important ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez à une sortie de reconnaissance des plantes. Qu’est-ce que cette expérience vous a apporté ?"},{"voice":"female","text":"Au départ, je voulais surtout obtenir des informations pratiques. Mais les rencontres avec des gens d’horizons différents ont changé ma manière de voir les choses. Nous avons parfois des désaccords, et c’est justement en les discutant que nous trouvons des idées auxquelles personne n’aurait pensé seul. Je sais que les difficultés ne disparaissent pas immédiatement, notamment parce que les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Pourtant, j’apprécie surtout les relations de confiance qui se sont créées. Elles me donnent envie de continuer à m’impliquer, même lorsque les résultats visibles se font attendre."},{"voice":"female","text":"Quel avantage l'invitée juge-t-elle le plus important ?"}],"audio":"q-22.mp3","audioSeconds":46.673,"slotSeconds":63},{"number":23,"kind":"panel-discussion","question":"Sur quelle démarche les participants se mettent-ils d'accord ?","options":["Consulter les habitants sur des itinéraires alternatifs et une information claire du public sans mener d’essai concret.","Expérimenter des itinéraires alternatifs et une information claire du public mais ne publier aucun retour des participants.","Mettre en place des itinéraires alternatifs et une information claire du public partout avant de mesurer les résultats.","Expérimenter des itinéraires alternatifs et une information claire du public, recueillir les avis et publier un bilan."],"correct":"D","explanation":"Le document permet de retenir « Expérimenter des itinéraires alternatifs et une information claire du public, recueillir les avis et publier un bilan ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 23.\nVous écoutez une table ronde sur le thème « Environnement et biodiversité ».\nPour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des itinéraires alternatifs et une information claire du public.\nMais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les passages répétés dans les zones sensibles perturbent la reproduction des animaux.\nIl faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible.\nJe suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin.\nAlors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider.\nCette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas.\nSur quelle démarche les participants se mettent-ils d'accord ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une table ronde sur le thème « Environnement et biodiversité »."},{"voice":"male","text":"Pour avancer, nous devons agir rapidement. Nos équipes ont déjà élaboré des itinéraires alternatifs et une information claire du public."},{"voice":"female","text":"Mais nous n’avons pas encore consulté les personnes qui risquent d’être gênées. La difficulté est réelle : les passages répétés dans les zones sensibles perturbent la reproduction des animaux."},{"voice":"male","text":"Il faudrait un essai limité dans le temps, avec des observations précises plutôt qu’une décision irréversible."},{"voice":"female","text":"Je suis d’accord, à condition que les habitants puissent donner leur avis pendant l’expérience, et pas seulement à la fin."},{"voice":"male","text":"Alors nous lancerons une expérimentation de trois mois, publierons les résultats et ajusterons le dispositif avant de décider."},{"voice":"female","text":"Cette méthode me paraît acceptable, car elle laisse la possibilité de corriger ce qui ne fonctionne pas."},{"voice":"female","text":"Sur quelle démarche les participants se mettent-ils d'accord ?"}],"audio":"q-23.mp3","audioSeconds":56.725,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle limite méthodologique la spécialiste identifie-t-elle ?","options":["L’étude de le programme de suivi des espèces s’appuie principalement sur les réponses des agents.","L’étude de le programme de suivi des espèces donne peu de place aux nouveaux inscrits.","L’étude sur le programme de suivi des espèces n’a presque pas touché ceux qui ont abandonné.","L’étude de le programme de suivi des espèces comprend surtout des personnes en attente."],"correct":"C","explanation":"Le document permet de retenir « L’étude sur le programme de suivi des espèces n’a presque pas touché ceux qui ont abandonné ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 24.\nVotre enquête semble montrer une forte satisfaction concernant le programme de suivi des espèces. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?\nPas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes.\nQuelle limite méthodologique la spécialiste identifie-t-elle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête semble montrer une forte satisfaction concernant le programme de suivi des espèces. Peut-on en conclure que le dispositif fonctionne pour tout le monde ?"},{"voice":"female","text":"Pas encore. Nos questionnaires ont été distribués aux personnes qui utilisent déjà ce service. Celles qui ont renoncé à cause des obstacles rencontrés sont presque absentes de l’échantillon. C’est un problème particulièrement important ici, car les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Nous risquons donc de mesurer la satisfaction des utilisateurs réguliers sans comprendre les raisons de l’exclusion des autres. Dans la prochaine phase, nous contacterons également les anciens usagers et les personnes qui n’ont jamais réussi à s’inscrire. Une moyenne élevée ne suffit pas si elle masque des expériences très différentes."},{"voice":"female","text":"Quelle limite méthodologique la spécialiste identifie-t-elle ?"}],"audio":"q-24.mp3","audioSeconds":53.331,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Quelle tension centrale le reportage souligne-t-il ?","options":["Donner la priorité à la fréquentation avant d’examiner les effets du projet sur les habitants.","Concilier les nouveaux itinéraires avec la protection des habitats naturels.","Limiter la nouvelle initiative aux personnes qui la fréquentent déjà régulièrement.","Reporter la décision concernant le projet jusqu’à la fin de la saison en cours."],"correct":"B","explanation":"Le document permet de retenir « Concilier les nouveaux itinéraires avec la protection des habitats naturels ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 25.\nVous regardez un reportage régional. Dans la réserve naturelle de la Loire, une initiative propose des itinéraires alternatifs et une information claire du public. Les responsables espèrent ainsi répondre à une difficulté bien connue : les passages répétés dans les zones sensibles perturbent la reproduction des animaux.\nNous soutenons l’objectif général, mais il faut prendre en compte l'équilibre entre accès à la nature et protection des habitats. Une décision utile à certains peut compliquer la vie d’autres personnes.\nLes organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que suivre les espèces plusieurs saisons et entretenir les chemins. Pourtant, certaines passerelles seront fermées durant la nidification. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées.\nQuelle tension centrale le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Vous regardez un reportage régional. Dans la réserve naturelle de la Loire, une initiative propose des itinéraires alternatifs et une information claire du public. Les responsables espèrent ainsi répondre à une difficulté bien connue : les passages répétés dans les zones sensibles perturbent la reproduction des animaux."},{"voice":"male","text":"Nous soutenons l’objectif général, mais il faut prendre en compte l'équilibre entre accès à la nature et protection des habitats. Une décision utile à certains peut compliquer la vie d’autres personnes."},{"voice":"female","text":"Les organisateurs reconnaissent cette difficulté et annoncent un calendrier progressif, avec des étapes de consultation. Ils affirment que suivre les espèces plusieurs saisons et entretenir les chemins. Pourtant, certaines passerelles seront fermées durant la nidification. La réussite du projet dépendra de la manière dont ces exigences pourront être conciliées."},{"voice":"female","text":"Quelle tension centrale le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":57.303,"slotSeconds":74},{"number":26,"kind":"interview","question":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","options":["Les premiers résultats sont positifs, mais il faut mesurer les effets durables.","Les résultats de une nouvelle zone de quiétude au printemps concernent uniquement les coûts de gestion.","L’équipe souhaite interrompre une nouvelle zone de quiétude au printemps dès la fin des premiers essais.","Le projet de une nouvelle zone de quiétude au printemps est annoncé mais n’a pas encore été lancé."],"correct":"A","explanation":"Le document permet de retenir « Les premiers résultats sont positifs, mais il faut mesurer les effets durables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 26.\nVous avez lancé une nouvelle zone de quiétude au printemps. Quels résultats retenez-vous après les premières semaines ?\nIl y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines passerelles seront fermées durant la nidification. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : l'évolution des populations d'espèces après les mesures. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture.\nPourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez lancé une nouvelle zone de quiétude au printemps. Quels résultats retenez-vous après les premières semaines ?"},{"voice":"female","text":"Il y a des signes encourageants, notamment une meilleure information des usagers. Cependant, nous devons rester prudents. Certaines passerelles seront fermées durant la nidification. Et nous n’avons pas encore assez de recul pour suivre cet indicateur : l'évolution des populations d'espèces après les mesures. Le dispositif a été préparé avec les équipes, mais les situations rencontrées sont plus diverses que prévu. Nous allons modifier certaines consignes et poursuivre les entretiens avec les usagers. Ce serait une erreur d’évaluer la réussite uniquement à partir du nombre de personnes venues à l’ouverture."},{"voice":"female","text":"Pourquoi la responsable refuse-t-elle d'annoncer une réussite définitive ?"}],"audio":"q-26.mp3","audioSeconds":48.13,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quel compromis les deux collègues souhaitent-ils préserver ?","options":["Réserver les créneaux matinaux de le programme de suivi des espèces aux seuls abonnés.","Ouvrir le programme de suivi des espèces plus tôt en supprimant les créneaux tardifs.","Conserver les horaires de le programme de suivi des espèces malgré les demandes du matin.","Adapter les horaires du programme de suivi des espèces sans pénaliser les usagers du soir."],"correct":"D","explanation":"Le document permet de retenir « Adapter les horaires du programme de suivi des espèces sans pénaliser les usagers du soir ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 27.\nPlusieurs personnes demandent que le programme de suivi des espèces ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée.\nSi nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir.\nPourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?\nOui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois.\nD’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre.\nQuel compromis les deux collègues souhaitent-ils préserver ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs personnes demandent que le programme de suivi des espèces ouvre plus tôt. C’est compréhensible, mais nous sommes déjà peu nombreux en fin de journée."},{"voice":"male","text":"Si nous avançons tous les horaires, les usagers qui terminent tard leur travail ne pourront plus venir."},{"voice":"female","text":"Pourrions-nous répartir les permanences différemment, sans supprimer celles du soir ?"},{"voice":"male","text":"Oui. Mais discutons d’abord avec les équipes et les personnes concernées. Nous pourrions tester deux horaires pendant un mois."},{"voice":"female","text":"D’accord. Notre objectif doit rester le même : faciliter l’accès au service plutôt que déplacer le problème d’un groupe à un autre."},{"voice":"female","text":"Quel compromis les deux collègues souhaitent-ils préserver ?"}],"audio":"q-27.mp3","audioSeconds":41.584,"slotSeconds":58},{"number":28,"kind":"interview","question":"Quelle erreur de conception l'experte dénonce-t-elle ?","options":["Préparer le budget de un observatoire en bois avant de calculer son entretien.","Adapter les équipements de un observatoire en bois après consultation des équipes.","Choisir les équipements avant d’interroger ceux qui vont les utiliser.","Tester un observatoire en bois sur un seul site avant de l’ouvrir à tous."],"correct":"C","explanation":"Le document permet de retenir « Choisir les équipements avant d’interroger ceux qui vont les utiliser ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 28.\nLe projet de un observatoire en bois a été présenté comme une innovation. Pourquoi demandez-vous une révision ?\nLes concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'équilibre entre accès à la nature et protection des habitats est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises.\nQuelle erreur de conception l'experte dénonce-t-elle ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Le projet de un observatoire en bois a été présenté comme une innovation. Pourquoi demandez-vous une révision ?"},{"voice":"female","text":"Les concepteurs ont d’abord choisi les équipements, puis seulement interrogé leurs futurs utilisateurs. Or, il est difficile d’anticiper les usages réels sans observer les pratiques quotidiennes. Certaines personnes ont besoin d’explications supplémentaires, d’autres rencontrent des obstacles physiques ou techniques. La question de l'équilibre entre accès à la nature et protection des habitats est aussi apparue très tard. On risque alors de multiplier les corrections coûteuses. Nous recommandons de commencer par des essais avec des publics divers et de laisser leurs retours modifier le projet, plutôt que de les consulter uniquement pour confirmer des décisions déjà prises."},{"voice":"female","text":"Quelle erreur de conception l'experte dénonce-t-elle ?"}],"audio":"q-28.mp3","audioSeconds":49.297,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle divergence méthodologique oppose les intervenants ?","options":["L’un défend les entretiens, l’autre réclame surtout les données financières.","L’un veut suivre cet indicateur : l'évolution des populations d'espèces après les mesures; l’autre demande aussi des témoignages.","L’un veut des statistiques d’usage et l’autre propose d’écarter les chiffres.","L’un veut comparer les coûts de l'évolution des populations d'espèces après les mesures ; l’autre mesure la fréquentation."],"correct":"B","explanation":"Le document permet de retenir « L’un veut suivre cet indicateur : l'évolution des populations d'espèces après les mesures; l’autre demande aussi des témoignages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 29.\nVous écoutez un débat consacré au thème « Environnement et biodiversité ».\nSans chiffres comparables, impossible de dire si une nouvelle zone de quiétude au printemps apporte un bénéfice mesurable. Nous devons étudier l'évolution des populations d'espèces après les mesures.\nLes chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les passages répétés dans les zones sensibles perturbent la reproduction des animaux.\nJe ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme.\nNous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir.\nQuelle divergence méthodologique oppose les intervenants ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat consacré au thème « Environnement et biodiversité »."},{"voice":"male","text":"Sans chiffres comparables, impossible de dire si une nouvelle zone de quiétude au printemps apporte un bénéfice mesurable. Nous devons étudier l'évolution des populations d'espèces après les mesures."},{"voice":"female","text":"Les chiffres sont nécessaires, mais nous devons comprendre les expériences des personnes touchées. Les passages répétés dans les zones sensibles perturbent la reproduction des animaux."},{"voice":"male","text":"Je ne nie pas l’intérêt des témoignages. Mais nous ne pouvons pas attendre plusieurs années avant d’ajuster le programme."},{"voice":"female","text":"Nous pouvons suivre des chiffres dès maintenant et mener des observations sur le terrain. Le désaccord porte sur ce que nous considérons comme une preuve suffisante, pas sur le besoin d’agir."},{"voice":"female","text":"Quelle divergence méthodologique oppose les intervenants ?"}],"audio":"q-29.mp3","audioSeconds":47.331,"slotSeconds":64},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","options":["Préserver l’histoire du lieu d’une sortie de reconnaissance des plantes tout en y proposant de nouveaux usages.","Moderniser les salles de une sortie de reconnaissance des plantes en effaçant les anciennes traces.","Rénover le lieu de une sortie de reconnaissance des plantes sans changer l’usage actuel des espaces.","Conserver le bâtiment de une sortie de reconnaissance des plantes uniquement pour ses activités passées."],"correct":"A","explanation":"Le document permet de retenir « Préserver l’histoire du lieu d’une sortie de reconnaissance des plantes tout en y proposant de nouveaux usages ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 30.\nVotre établissement, où se déroule une sortie de reconnaissance des plantes, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?\nNous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer.\nQuelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre établissement, où se déroule une sortie de reconnaissance des plantes, doit évoluer. Certaines personnes craignent qu’il perde son identité. Que leur répondez-vous ?"},{"voice":"female","text":"Nous ne devons pas confondre conservation et immobilité. Les éléments qui racontent l’histoire d’un endroit méritent d’être documentés et protégés. Mais si un bâtiment ou une institution ne répond plus aux besoins actuels, son avenir peut aussi passer par de nouveaux usages. Il faut expliquer les transformations, garder les traces significatives et écouter les personnes attachées au lieu. Le projet ne réussira pas si l’on gomme toute mémoire ; il ne réussira pas davantage si l’on interdit toute adaptation. L’enjeu est de transmettre un sens sans empêcher la vie de continuer."},{"voice":"female","text":"Quelle conception du patrimoine ou de l'héritage collectif l'invitée défend-elle ?"}],"audio":"q-30.mp3","audioSeconds":52.025,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Quelle précaution méthodologique la conférencière recommande-t-elle ?","options":["Calculer une nouvelle moyenne globale avec davantage de données.","Comparer la moyenne d’un groupe à la moyenne de l’ensemble.","Privilégier les chiffres globaux plutôt que les résultats détaillés.","Examiner les différences entre groupes, cachées par une moyenne."],"correct":"D","explanation":"Le document permet de retenir « Examiner les différences entre groupes, cachées par une moyenne ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 31.\nVous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, l'évolution des populations d'espèces après les mesures. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner.\nQuelle précaution méthodologique la conférencière recommande-t-elle ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence universitaire. Nous examinons plusieurs projets locaux et, plus précisément, l'évolution des populations d'espèces après les mesures. Une moyenne permet de résumer un ensemble, mais elle peut masquer des situations opposées. Deux quartiers ou deux groupes peuvent obtenir le même résultat global tout en connaissant des contraintes très différentes. Pour comprendre ce que les chiffres racontent, il faut examiner leur répartition et les personnes qui restent invisibles. Cette prudence est particulièrement importante ici : les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Les décideurs ont besoin de résultats compréhensibles, mais la simplicité d’une présentation ne doit jamais faire oublier les limites de la méthode. Une interprétation responsable indique à la fois ce que l’on sait, ce que l’on suppose et ce qui reste à examiner."},{"voice":"female","text":"Quelle précaution méthodologique la conférencière recommande-t-elle ?"}],"audio":"q-31.mp3","audioSeconds":55.351,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","options":["Pour le programme de suivi des espèces, accorder la même fiabilité à toutes les prévisions disponibles.","Pour le programme de suivi des espèces, publier un chiffre précis sans détailler ses limites.","Pour le programme de suivi des espèces, présenter les hypothèses et les incertitudes des prévisions.","Pour le programme de suivi des espèces, annoncer une moyenne sans préciser les hypothèses retenues."],"correct":"C","explanation":"Le document permet de retenir « Pour le programme de suivi des espèces, présenter les hypothèses et les incertitudes des prévisions ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 32.\nVous avancez des projections concernant le programme de suivi des espèces, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?\nAu contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions.\nComment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous avancez des projections concernant le programme de suivi des espèces, mais sans annoncer de résultat certain. Cela ne risque-t-il pas de troubler le public ?"},{"voice":"female","text":"Au contraire, il faut expliquer ce que nos données permettent d’affirmer. Nous pouvons décrire des tendances, identifier des facteurs de risque et proposer plusieurs scénarios. Mais nous ne connaissons pas à l’avance chaque décision individuelle ni toutes les conditions qui modifieront le résultat. Cette incertitude n’annule pas l’utilité de la recherche : elle invite à préparer des mesures adaptées et à les réévaluer. Un chiffre extrêmement précis, présenté sans contexte, peut donner une fausse impression de certitude. Il vaut mieux communiquer les hypothèses, une fourchette raisonnable et ce qui pourrait modifier nos conclusions."},{"voice":"female","text":"Comment la spécialiste souhaite-t-elle communiquer les limites de ses prévisions ?"}],"audio":"q-32.mp3","audioSeconds":52.352,"slotSeconds":69},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","options":["La hausse des visites à la réserve naturelle de la Loire vient surtout des horaires étendus.","La hausse de fréquentation dans la réserve naturelle de la Loire ne suffit pas à mesurer les résultats durables.","La fréquentation de la réserve naturelle de la Loire varie trop selon les saisons.","Les chiffres de la réserve naturelle de la Loire ne tiennent pas compte du prix des activités."],"correct":"B","explanation":"Le document permet de retenir « La hausse de fréquentation dans la réserve naturelle de la Loire ne suffit pas à mesurer les résultats durables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 33.\nDans la réserve naturelle de la Loire, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une nouvelle zone de quiétude au printemps. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer l'évolution des populations d'espèces après les mesures ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu.\nQuelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Dans la réserve naturelle de la Loire, les responsables mettent en avant un résultat spectaculaire : la fréquentation a augmenté depuis l'annonce de cette mesure : une nouvelle zone de quiétude au printemps. C’est une information utile, mais elle ne suffit pas à juger de la qualité du dispositif. Qui a pu en bénéficier ? Les personnes les plus éloignées du service y ont-elles réellement accès ? Et surtout, comment observer l'évolution des populations d'espèces après les mesures ? Un indicateur de volume n’est pas automatiquement un indicateur de progrès. Il faut aussi regarder les effets indirects, les coûts pour certains groupes et la stabilité des résultats dans le temps. Sans cela, un succès de communication peut masquer un problème qui n’a pas été résolu."},{"voice":"female","text":"Quelle critique la chroniqueuse formule-t-elle à propos des chiffres présentés ?"}],"audio":"q-33.mp3","audioSeconds":48.025,"slotSeconds":65},{"number":34,"kind":"roundtable","question":"Quelle condition commune les participants retiennent-ils ?","options":["Consulter des publics variés et maintenir un accompagnement humain.","Faire tester le programme de suivi des espèces uniquement par les usagers réguliers.","Maintenir une aide humaine à le programme de suivi des espèces pendant le seul lancement.","Évaluer le programme de suivi des espèces auprès de tous puis supprimer l’accueil individuel."],"correct":"A","explanation":"Le document permet de retenir « Consulter des publics variés et maintenir un accompagnement humain ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 34.\nVous écoutez une table ronde sur les difficultés rencontrées dans la réserve naturelle de la Loire.\nNous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues.\nCertaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'équilibre entre accès à la nature et protection des habitats.\nDans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches.\nNous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours.\nEt prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre.\nOui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel.\nQuelle condition commune les participants retiennent-ils ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Vous écoutez une table ronde sur les difficultés rencontrées dans la réserve naturelle de la Loire."},{"voice":"male","text":"Nous avons mis en place des outils, mais les usagers signalent encore des difficultés inattendues."},{"voice":"female","text":"Certaines personnes n’arrivent pas à terminer la démarche sans aide. Cela pose notamment cette question : l'équilibre entre accès à la nature et protection des habitats."},{"voice":"male","text":"Dans notre évaluation, nous avons surtout compté les connexions ou les visites, pas l’achèvement des démarches."},{"voice":"female","text":"Nous devons donc inviter des personnes de profils différents à essayer le service et observer leurs parcours."},{"voice":"male","text":"Et prévoir une assistance humaine pour celles qui en ont besoin, sans les obliger à passer par une procédure impossible à comprendre."},{"voice":"female","text":"Oui. Les retours doivent réellement modifier nos décisions et pas simplement illustrer notre rapport annuel."},{"voice":"female","text":"Quelle condition commune les participants retiennent-ils ?"}],"audio":"q-34.mp3","audioSeconds":53.95,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle idée la spécialiste conteste-t-elle ?","options":["Les usages quotidiens du matériel de le sentier des roseaux peuvent changer ses effets.","Les conditions de terrain de le sentier des roseaux influencent les résultats observés.","La performance du dispositif de le sentier des roseaux exige un entretien régulier.","Les résultats techniques du sentier des roseaux suffiraient même si les usages réels diffèrent."],"correct":"D","explanation":"Le document permet de retenir « Les résultats techniques du sentier des roseaux suffiraient même si les usages réels diffèrent ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 35.\nLe dispositif que vous avez installé dans le sentier des roseaux affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?\nLes chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes.\nQuelle idée la spécialiste conteste-t-elle ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Le dispositif que vous avez installé dans le sentier des roseaux affiche d’excellentes performances. Pourquoi les résultats observés restent-ils décevants ?"},{"voice":"female","text":"Les chiffres du fabricant ont été obtenus dans des conditions idéales. Sur le terrain, les personnes utilisent les équipements d’une manière plus variée. Les conditions matérielles changent aussi d’un lieu à l’autre. Nous avons sous-estimé le temps nécessaire pour l’entretien, et certains réglages sont difficiles à comprendre. Il serait injuste d’en conclure que les utilisateurs sont simplement responsables. Nous devons comparer les hypothèses techniques aux pratiques réelles, former les équipes et revoir les procédures. Un appareil efficace en laboratoire ne garantit pas à lui seul une amélioration dans tous les contextes."},{"voice":"female","text":"Quelle idée la spécialiste conteste-t-elle ?"}],"audio":"q-35.mp3","audioSeconds":50.144,"slotSeconds":68},{"number":36,"kind":"interview","question":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?","options":["Évaluer le lien créé à une sortie de reconnaissance des plantes uniquement par le nombre de présences.","Assurer une présence régulière aux séances de une sortie de reconnaissance des plantes sans échanger.","Permettre une participation volontaire et réciproque à une sortie de reconnaissance des plantes.","Répartir les rôles de une sortie de reconnaissance des plantes entre des participants désignés à l’avance."],"correct":"C","explanation":"Le document permet de retenir « Permettre une participation volontaire et réciproque à une sortie de reconnaissance des plantes ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 36.\nVotre initiative autour de une sortie de reconnaissance des plantes réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?\nNon, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'équilibre entre accès à la nature et protection des habitats. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement.\nÀ quelle condition l'engagement des participants produit-il des bénéfices durables ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre initiative autour de une sortie de reconnaissance des plantes réunit plusieurs générations et différents milieux. Peut-on dire que la participation suffit à créer des liens ?"},{"voice":"female","text":"Non, car une présence imposée ne produit pas nécessairement un échange sincère. Nous avons d’abord prévu un programme très détaillé, en attribuant à chacun un rôle selon son âge ou son expérience. Certains ne s’y reconnaissaient pas. Les activités ont mieux fonctionné lorsque nous avons laissé les personnes proposer des idées, refuser un atelier et avancer à leur rythme. Il faut également tenir compte de cet enjeu : l'équilibre entre accès à la nature et protection des habitats. Nous cherchons une relation réciproque, pas un simple nombre de présences enregistré dans un tableau. Les effets se construisent progressivement."},{"voice":"female","text":"À quelle condition l'engagement des participants produit-il des bénéfices durables ?"}],"audio":"q-36.mp3","audioSeconds":55.438,"slotSeconds":73},{"number":37,"kind":"interview","question":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","options":["Conserver les récits de le programme de suivi des espèces qui concordent avec la majorité.","La chercheuse confronte les témoignages sur le programme de suivi des espèces aux dates et décisions vérifiables.","Classer les témoignages de le programme de suivi des espèces selon l’ancienneté de leurs auteurs.","Comparer les récits de le programme de suivi des espèces sans consulter les archives disponibles."],"correct":"B","explanation":"Le document permet de retenir « La chercheuse confronte les témoignages sur le programme de suivi des espèces aux dates et décisions vérifiables ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 37.\nDans votre étude concernant le programme de suivi des espèces, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?\nNous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves.\nPourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Dans votre étude concernant le programme de suivi des espèces, les participants racontent parfois des expériences très différentes. Comment traiter ces contradictions ?"},{"voice":"female","text":"Nous commençons par vérifier les faits que les documents permettent de confirmer. Les dates, les décisions et les chiffres ne sont pas de simples opinions. Mais il arrive que plusieurs personnes aient vécu le même événement depuis des positions différentes. Leurs récits nous renseignent alors sur ce qu’elles ont observé, ce qu’elles craignaient et ce qu’elles ignoraient. Notre travail consiste à conserver le contexte des entretiens et à confronter les versions, plutôt qu’à en choisir une uniquement parce qu’elle paraît plus convaincante. Cela ne signifie pas que toutes les affirmations se valent. Au contraire, leurs différences nous obligent à préciser la nature des preuves."},{"voice":"female","text":"Pourquoi la chercheuse conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":53.54,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Quel paradoxe l'exposé met-il principalement en évidence ?","options":["Le succès d’une nouvelle zone de quiétude au printemps peut créer des difficultés aux usagers.","La fréquentation de une nouvelle zone de quiétude au printemps ralentit la promotion du dispositif.","La croissance de une nouvelle zone de quiétude au printemps augmente le budget sans effet sur les usagers.","Le succès de une nouvelle zone de quiétude au printemps réduit les demandes des services voisins."],"correct":"A","explanation":"Le document permet de retenir « Le succès d’une nouvelle zone de quiétude au printemps peut créer des difficultés aux usagers ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 38.\nVous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Environnement et biodiversité ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une nouvelle zone de quiétude au printemps peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'équilibre entre accès à la nature et protection des habitats. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent.\nQuel paradoxe l'exposé met-il principalement en évidence ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez une conférence publique sur la manière d’évaluer les politiques locales. Le cas étudié relève du thème « Environnement et biodiversité ».  Une initiative conçue pour résoudre un problème peut parfois le déplacer ou en créer de nouveaux. Ainsi, une nouvelle zone de quiétude au printemps peut susciter un véritable enthousiasme. Mais si le nombre de participants augmente sans adaptation des moyens, les passages répétés dans les zones sensibles perturbent la reproduction des animaux. Il serait tentant de célébrer immédiatement la fréquentation, sans examiner l'équilibre entre accès à la nature et protection des habitats. Nous devons distinguer le succès d’un lancement de ses effets durables. Une politique pertinente doit pouvoir évoluer lorsque de nouveaux besoins apparaissent. Il ne s’agit ni de refuser toute innovation ni de considérer qu’une forte demande suffit à prouver une réussite. Il s’agit de choisir les conditions dans lesquelles les bénéfices peuvent se maintenir sans fragiliser ceux qui en dépendent."},{"voice":"female","text":"Quel paradoxe l'exposé met-il principalement en évidence ?"}],"audio":"q-38.mp3","audioSeconds":65.347,"slotSeconds":83},{"number":39,"kind":"interview","question":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","options":["Étendre le service en privilégiant seulement les premiers résultats de l'évolution des populations d'espèces après les mesures.","Suivre l'évolution des populations d'espèces après les mesures en comptant sur les bénévoles actuels.","Obtenir des moyens durables mais ne plus mesurer l'évolution des populations d'espèces après les mesures.","Assurer des moyens durables et suivre l'évolution des populations d'espèces après les mesures sur la durée."],"correct":"D","explanation":"Le document permet de retenir « Assurer des moyens durables et suivre l'évolution des populations d'espèces après les mesures sur la durée ». Les autres propositions modifient un élément décisif de la situation enregistrée.","transcript":"Question 39.\nVotre initiative, liée à le programme de suivi des espèces, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines passerelles seront fermées durant la nidification. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre l'évolution des populations d'espèces après les mesures. L’idée n’est pas d’abandonner l’ambition de départ : suivre les espèces plusieurs saisons et entretenir les chemins. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne.\nQuelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre initiative, liée à le programme de suivi des espèces, a suscité beaucoup d’intérêt durant ses premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que cet essai a bénéficié de circonstances exceptionnelles. Une partie du matériel a été prêtée et plusieurs bénévoles ont fourni un effort qu’il serait difficile de maintenir chaque semaine. La fréquentation démontre un besoin, mais ne nous dit pas comment répartir équitablement le travail ni comment financer les frais réguliers. Il faut aussi anticiper certaines passerelles seront fermées durant la nidification. Nous proposons donc d’établir un budget réaliste, de discuter des responsabilités et de suivre l'évolution des populations d'espèces après les mesures. L’idée n’est pas d’abandonner l’ambition de départ : suivre les espèces plusieurs saisons et entretenir les chemins. Pour durer, une initiative doit pouvoir fonctionner lorsque l’enthousiasme des premiers jours se transforme en activité quotidienne."},{"voice":"female","text":"Quelle approche la spécialiste juge-t-elle nécessaire pour assurer l'avenir du projet ?"}],"audio":"q-39.mp3","audioSeconds":63.705,"slotSeconds":81}]}]$eight_data$::jsonb;
 paper jsonb; previous jsonb; existing jsonb;
 protected_before jsonb;protected_after jsonb;
 old_before jsonb;old_after jsonb;
 others_before jsonb;others_after jsonb;
 function_before text;function_after text;
begin
 perform pg_advisory_xact_lock(hashtext('hzad-tcf-listening-07-14-v2'));
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_before;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_before
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test07-v2','tcf-listening-2026-11-test08-v2','tcf-listening-2026-11-test09-v2','tcf-listening-2026-11-test10-v2','tcf-listening-2026-11-test11-v2','tcf-listening-2026-11-test12-v2','tcf-listening-2026-11-test13-v2','tcf-listening-2026-11-test14-v2');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into others_before
  from academy_tcf_listening.published where test_id not in ('tcf-listening-07','tcf-listening-08','tcf-listening-09','tcf-listening-10','tcf-listening-11','tcf-listening-12','tcf-listening-13','tcf-listening-14');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into function_before;
 for paper in select value from jsonb_array_elements(wanted) loop
  select content into previous from academy_tcf_listening.papers
   where id=paper->>'id' and version='tcf-listening-2026-11-test'||right(paper->>'id',2)||'-v1';
  if not found then raise exception 'Historical v1 source bank missing: %',paper->>'id';end if;
  if jsonb_array_length(paper->'questions')<>39 or (paper->>'seconds')::integer<>2100 or
   (select sum((q->>'slotSeconds')::integer) from jsonb_array_elements(paper->'questions') q)<>2100
   or exists(
    select 1 from jsonb_array_elements(paper->'questions') with ordinality x(q,n)
    where (q->>'number')::integer<>x.n or jsonb_array_length(q->'options')<>4
      or q->>'correct' not in ('A','B','C','D')
      or coalesce((q->>'audioSeconds')::numeric,0)<=0
      or (q->>'audioSeconds')::numeric+12>(q->>'slotSeconds')::numeric
   ) then raise exception 'Incomplete or mistimed listening v2 bank: %',paper->>'id';end if;
  if exists(
   select 1 from jsonb_array_elements(paper->'questions') with ordinality new(q,n)
    join jsonb_array_elements(previous->'questions') with ordinality old(q,n) using(n)
    where new.q->>'number' is distinct from old.q->>'number'
     or new.q->>'kind' is distinct from old.q->>'kind'
     or new.q->>'correct' is distinct from old.q->>'correct'
     or new.q->>'question' is distinct from old.q->>'question'
     or new.q->'segments' is distinct from old.q->'segments'
     or new.q->>'transcript' is distinct from old.q->>'transcript'
     or new.q->>'audio' is distinct from old.q->>'audio'
     or new.q->>'audioSeconds' is distinct from old.q->>'audioSeconds'
     or new.q->>'slotSeconds' is distinct from old.q->>'slotSeconds'
     or new.q->>'image' is distinct from old.q->>'image'
     or (new.n<=8 and new.q->'options' is distinct from old.q->'options')
  ) then raise exception 'Audio, key or historical timing changed: %',paper->>'id';end if;
  select content into existing from academy_tcf_listening.papers
   where id=paper->>'id' and version=paper->>'version';
  if found and existing is distinct from paper then
   raise exception 'Refusing to overwrite immutable v2 bank: %',paper->>'id';end if;
  insert into academy_tcf_listening.papers(id,version,content)
   values(paper->>'id',paper->>'version',paper) on conflict(id,version) do nothing;
  insert into academy_tcf_listening.published(test_id,version)
   values(paper->>'id',paper->>'version')
   on conflict(test_id) do update set version=excluded.version
    where academy_tcf_listening.published.version is distinct from excluded.version;
 end loop;
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tef_speaking.calls t)) into protected_after;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_after
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test07-v2','tcf-listening-2026-11-test08-v2','tcf-listening-2026-11-test09-v2','tcf-listening-2026-11-test10-v2','tcf-listening-2026-11-test11-v2','tcf-listening-2026-11-test12-v2','tcf-listening-2026-11-test13-v2','tcf-listening-2026-11-test14-v2');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into others_after
  from academy_tcf_listening.published where test_id not in ('tcf-listening-07','tcf-listening-08','tcf-listening-09','tcf-listening-10','tcf-listening-11','tcf-listening-12','tcf-listening-13','tcf-listening-14');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into function_after;
 if protected_before is distinct from protected_after
 or old_before is distinct from old_after or others_before is distinct from others_after
 or function_before is distinct from function_after
 then raise exception 'Student/history preservation mismatch: entire batch rolled back';end if;
 if exists(
  select 1 from jsonb_array_elements(wanted) p
  where not exists(select 1 from academy_tcf_listening.papers b
   join academy_tcf_listening.published v on v.test_id=b.id and v.version=b.version
   where b.id=p->>'id' and b.version=p->>'version' and b.content=p)
 ) then raise exception 'One or more exact TCF listening v2 bank publications failed';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='academy_tcf_listening' and c.relkind='r' and not c.relrowsecurity)
  or has_table_privilege('anon','academy_tcf_listening.papers','select')
  or has_table_privilege('authenticated','academy_tcf_listening.papers','select')
 then raise exception 'Private answer-key bank protection altered';end if;
end;
$publish_eight$;
